CREATE EXTENSION IF NOT EXISTS "pg_cron" WITH SCHEMA "pg_catalog";






CREATE EXTENSION IF NOT EXISTS "pgsodium";






COMMENT ON SCHEMA "public" IS 'Departamento Pessoal (dp_*) — Convenções obrigatórias:
  PKs: UUID DEFAULT gen_random_uuid()
  Timestamps: TIMESTAMPTZ NOT NULL DEFAULT NOW()
  RLS: SEMPRE habilitado antes do primeiro dado
  Migrations: YYYYMMDDHHMMSS_dp_nome.sql via supabase_apply_migration
  PII: COMMENTs em colunas com dados pessoais indicando classificação LGPD
  Audit: toda operação sensível registra em dp_audit_log
  Imutabilidade: logs não permitem UPDATE/DELETE sem role postgres';



CREATE EXTENSION IF NOT EXISTS "pg_stat_statements" WITH SCHEMA "extensions";






CREATE EXTENSION IF NOT EXISTS "pgaudit" WITH SCHEMA "public";






