CREATE OR REPLACE FUNCTION "public"."_is_admin_bypass"() RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  BEGIN
    IF auth.uid() IS NOT NULL AND public.has_role(auth.uid(), 'admin'::app_role) THEN
      RETURN true;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RETURN false;
  END;
  RETURN false;
END;
$$;


ALTER FUNCTION "public"."_is_admin_bypass"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_purge_audit_log_internal"("_dias" integer DEFAULT 365) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _deleted integer;
BEGIN
  IF _dias < 30 THEN
    RAISE EXCEPTION 'Retenção mínima de 30 dias';
  END IF;

  WITH del AS (
    DELETE FROM public.audit_log
    WHERE created_at < now() - (_dias || ' days')::interval
    RETURNING 1
  )
  SELECT count(*) INTO _deleted FROM del;

  -- Registra a execução no próprio audit_log para observabilidade
  INSERT INTO public.audit_log (tabela, registro_id, acao, user_id, dados_novos)
  VALUES ('audit_log', gen_random_uuid(), 'AUTO_PURGE', NULL,
          jsonb_build_object('deleted', _deleted, 'retention_days', _dias, 'at', now()));

  RETURN _deleted;
END;
$$;


ALTER FUNCTION "public"."_purge_audit_log_internal"("_dias" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_scan_status_anomalies_global"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _alerts integer := 0;
  _max_alerts_per_run constant integer := 20;
  _cooldown_interval constant interval := interval '1 hour';
  _lock_acquired boolean;
  r record;
BEGIN
  -- Advisory lock não-bloqueante: se outro scan já roda, retorna imediatamente
  -- Hash 'scan_anomalies_global' → int estável
  SELECT pg_try_advisory_lock(hashtext('scan_anomalies_global')::bigint) INTO _lock_acquired;
  IF NOT _lock_acquired THEN
    RETURN 0;
  END IF;

  BEGIN
    FOR r IN
      SELECT tabela, count(*) AS c
      FROM public.audit_log
      WHERE acao = 'STATUS_CHANGE'
        AND created_at >= now() - interval '10 minutes'
      GROUP BY tabela
      HAVING count(*) >= 500
      ORDER BY count(*) DESC
      LIMIT _max_alerts_per_run
    LOOP
      -- Cooldown 1h (era 10min) — reduz spam em incidentes prolongados
      IF NOT EXISTS (
        SELECT 1 FROM public.security_alerts
        WHERE type = 'status_change_burst_global'
          AND details->>'tabela' = r.tabela
          AND created_at >= now() - _cooldown_interval
      ) THEN
        INSERT INTO public.security_alerts (type, severity, details)
        VALUES ('status_change_burst_global', 'critical',
                jsonb_build_object('tabela', r.tabela, 'count', r.c,
                                   'window_minutes', 10, 'threshold', 500,
                                   'cooldown_minutes', 60,
                                   'detected_at', now()));
        _alerts := _alerts + 1;

        EXIT WHEN _alerts >= _max_alerts_per_run;
      END IF;
    END LOOP;

    -- Observabilidade — sempre loga execução (mesmo com 0 alerts)
    IF _alerts > 0 THEN
      INSERT INTO public.audit_log (tabela, registro_id, acao, dados_novos)
      VALUES ('security_alerts', gen_random_uuid(), 'ANOMALY_SCAN_RUN',
              jsonb_build_object('alerts_created', _alerts,
                                 'max_per_run', _max_alerts_per_run,
                                 'ran_at', now()));
    END IF;
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_advisory_unlock(hashtext('scan_anomalies_global')::bigint);
    RAISE;
  END;

  PERFORM pg_advisory_unlock(hashtext('scan_anomalies_global')::bigint);
  RETURN _alerts;
END; $$;


ALTER FUNCTION "public"."_scan_status_anomalies_global"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_security_definer_rpcs"() RETURNS TABLE("function_name" "text", "arguments" "text", "return_type" "text", "executable_by_anon" boolean, "executable_by_authenticated" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin'::app_role) THEN
    RAISE EXCEPTION 'access denied';
  END IF;

  RETURN QUERY
  SELECT
    p.proname::text,
    pg_get_function_identity_arguments(p.oid)::text,
    pg_get_function_result(p.oid)::text,
    has_function_privilege('anon', p.oid, 'EXECUTE'),
    has_function_privilege('authenticated', p.oid, 'EXECUTE')
  FROM pg_proc p
  JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public'
    AND p.prosecdef = true
  ORDER BY p.proname;
END;
$$;


ALTER FUNCTION "public"."admin_list_security_definer_rpcs"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_user_roles"() RETURNS TABLE("id" "uuid", "user_id" "uuid", "role" "public"."app_role", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Apenas administradores podem listar papéis de usuário' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
    SELECT ur.id, ur.user_id, ur.role, ur.created_at
    FROM public.user_roles ur
    ORDER BY ur.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."admin_list_user_roles"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_user_role"("_target_user_id" "uuid", "_role" "public"."app_role") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Apenas administradores podem gerenciar papéis de usuário' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.user_roles (user_id, role, created_by)
  VALUES (_target_user_id, _role, auth.uid())
  ON CONFLICT (user_id, role) DO NOTHING;

  INSERT INTO public.audit_log (tabela, registro_id, acao, user_id, dados_novos)
  VALUES ('user_roles', _target_user_id, 'UPDATE', auth.uid(), jsonb_build_object('role', _role, 'action', 'admin_set_user_role'));

  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."admin_set_user_role"("_target_user_id" "uuid", "_role" "public"."app_role") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agendar_limpeza_pos_desligamento"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF (NEW.status = 'desligado' AND (OLD.status IS DISTINCT FROM NEW.status)) THEN
        -- Agendar anonimização para daqui a 5 anos (60 meses)
        INSERT INTO public.lgpd_fila_limpeza (registro_id, tabela, data_programada)
        VALUES (NEW.id, 'colaboradores', (CURRENT_DATE + INTERVAL '60 months')::DATE);
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."agendar_limpeza_pos_desligamento"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."anonimizar_dados_pessoais"("target_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    UPDATE public.colaboradores
    SET 
        nome_completo = 'COLABORADOR ANONIMIZADO (LGPD)',
        cpf = '000.000.000-00',
        rg = 'ANONIMO',
        email = 'anonimo@empresa.com.br',
        telefone = '(00) 0000-0000',
        metadata = jsonb_set(COALESCE(metadata, '{}'::jsonb), '{lgpd_anonimizado}', 'true'),
        updated_at = now()
    WHERE id = target_id;

    -- Registrar a ação na auditoria LGPD
    INSERT INTO public.lgpd_solicitacoes (colaborador_id, tipo, status, descricao, concluida_em)
    VALUES (target_id, 'exclusao', 'concluida', 'Anonimização automática por política de retenção', now());
END;
$$;


ALTER FUNCTION "public"."anonimizar_dados_pessoais"("target_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aplicar_medida_folha_ponto"("p_medida_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_medida        RECORD;
  v_colab         RECORD;
  v_data_fim      DATE;
  v_afast_id      UUID;
  v_deslig_id     UUID;
  v_rubrica_id    UUID;
  v_valor_dia     NUMERIC(12,2);
  v_valor_desc    NUMERIC(12,2);
  v_competencia   TEXT;
  v_result        JSONB := '{}'::jsonb;
BEGIN
  SELECT * INTO v_medida FROM public.medidas_disciplinares WHERE id = p_medida_id;
  IF v_medida.id IS NULL THEN
    RAISE EXCEPTION 'medida_nao_encontrada';
  END IF;

  IF v_medida.status_workflow <> 'aplicada' THEN
    RAISE EXCEPTION 'medida_nao_aplicada';
  END IF;

  -- Tenant guard
  IF NOT (v_medida.empresa_id = ANY (SELECT get_user_empresas(auth.uid())))
     AND NOT (auth.role() = 'service_role') THEN
    RAISE EXCEPTION 'sem_permissao';
  END IF;

  SELECT * INTO v_colab FROM public.colaboradores WHERE id = v_medida.colaborador_id;

  -- SUSPENSÃO
  IF v_medida.tipo = 'suspensao' THEN
    IF COALESCE(v_medida.dias_suspensao,0) <= 0 THEN
      RAISE EXCEPTION 'dias_suspensao_invalidos';
    END IF;
    IF COALESCE(v_medida.dias_suspensao,0) > 30 THEN
      RAISE EXCEPTION 'dias_suspensao_excede_clt'; -- Art. 474 CLT
    END IF;

    v_data_fim := COALESCE(v_medida.data_inicio_efeito, v_medida.data_ocorrencia)
                  + (v_medida.dias_suspensao - 1);

    -- Evita duplicidade
    SELECT ref_id INTO v_afast_id
    FROM public.medidas_disciplinares_integracao
    WHERE medida_id = p_medida_id AND tipo_integracao = 'afastamento' AND status = 'aplicado'
    LIMIT 1;

    IF v_afast_id IS NULL THEN
      INSERT INTO public.afastamentos (
        colaborador_id, empresa_id, tipo, data_inicio, data_fim_prevista,
        dias_empresa, status, observacoes, created_by
      ) VALUES (
        v_medida.colaborador_id, v_medida.empresa_id, 'suspensao_disciplinar'::tipo_afastamento,
        COALESCE(v_medida.data_inicio_efeito, v_medida.data_ocorrencia), v_data_fim,
        v_medida.dias_suspensao, 'ativo'::status_afastamento,
        'Gerado automaticamente pela medida disciplinar ' || p_medida_id::text,
        auth.uid()
      )
      RETURNING id INTO v_afast_id;

      INSERT INTO public.medidas_disciplinares_integracao (
        medida_id, empresa_id, colaborador_id, tipo_integracao, ref_id, dias, status, detalhes
      ) VALUES (
        p_medida_id, v_medida.empresa_id, v_medida.colaborador_id,
        'afastamento', v_afast_id, v_medida.dias_suspensao, 'aplicado',
        jsonb_build_object('data_inicio', COALESCE(v_medida.data_inicio_efeito, v_medida.data_ocorrencia),
                           'data_fim', v_data_fim)
      );
    END IF;

    -- Desconto proporcional em folha (fila para próxima competência)
    v_rubrica_id := public.garantir_rubrica_suspensao(v_medida.empresa_id);
    v_valor_dia  := COALESCE(v_colab.salario_base, 0) / 30.0;
    v_valor_desc := ROUND(v_valor_dia * v_medida.dias_suspensao, 2);
    v_competencia := to_char(COALESCE(v_medida.data_inicio_efeito, v_medida.data_ocorrencia), 'YYYY-MM');

    IF NOT EXISTS (
      SELECT 1 FROM public.medidas_disciplinares_integracao
      WHERE medida_id = p_medida_id
        AND tipo_integracao IN ('lancamento_folha_pendente','lancamento_folha_aplicado')
    ) THEN
      INSERT INTO public.medidas_disciplinares_integracao (
        medida_id, empresa_id, colaborador_id, tipo_integracao,
        competencia, valor, dias, status, detalhes
      ) VALUES (
        p_medida_id, v_medida.empresa_id, v_medida.colaborador_id,
        'lancamento_folha_pendente', v_competencia, v_valor_desc, v_medida.dias_suspensao,
        'pendente',
        jsonb_build_object('rubrica_id', v_rubrica_id, 'rubrica_codigo', 'DESC_SUSP',
                           'valor_dia', v_valor_dia, 'salario_base', COALESCE(v_colab.salario_base,0))
      );
    END IF;

    v_result := jsonb_build_object(
      'tipo', 'suspensao',
      'afastamento_id', v_afast_id,
      'competencia', v_competencia,
      'valor_desconto', v_valor_desc,
      'dias', v_medida.dias_suspensao
    );

  -- JUSTA CAUSA
  ELSIF v_medida.tipo IN ('justa_causa','demissao_justa_causa') THEN
    SELECT ref_id INTO v_deslig_id
    FROM public.medidas_disciplinares_integracao
    WHERE medida_id = p_medida_id AND tipo_integracao = 'desligamento' AND status = 'aplicado'
    LIMIT 1;

    IF v_deslig_id IS NULL THEN
      INSERT INTO public.desligamentos (
        colaborador_id, tipo, data_desligamento, motivo, status, salario_base
      ) VALUES (
        v_medida.colaborador_id, 'justa_causa'::tipo_desligamento,
        COALESCE(v_medida.data_inicio_efeito, v_medida.data_ocorrencia),
        'Justa causa aplicada via medida disciplinar ' || p_medida_id::text ||
          coalesce(' — Art. CLT: ' || v_medida.artigo_clt, ''),
        'em_andamento', COALESCE(v_colab.salario_base, 0)
      )
      RETURNING id INTO v_deslig_id;

      INSERT INTO public.medidas_disciplinares_integracao (
        medida_id, empresa_id, colaborador_id, tipo_integracao, ref_id, status, detalhes
      ) VALUES (
        p_medida_id, v_medida.empresa_id, v_medida.colaborador_id,
        'desligamento', v_deslig_id, 'aplicado',
        jsonb_build_object('data', COALESCE(v_medida.data_inicio_efeito, v_medida.data_ocorrencia),
                           'artigo_clt', v_medida.artigo_clt)
      );
    END IF;

    v_result := jsonb_build_object('tipo', 'justa_causa', 'desligamento_id', v_deslig_id);

  ELSE
    -- Advertência ou similar: nada a integrar
    v_result := jsonb_build_object('tipo', v_medida.tipo, 'integracao', 'nao_aplicavel');
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."aplicar_medida_folha_ponto"("p_medida_id" "uuid") OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."despesas" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "colaborador_id" "uuid" NOT NULL,
    "categoria" "text" NOT NULL,
    "descricao" "text" NOT NULL,
    "valor" numeric(10,2) NOT NULL,
    "data_despesa" "date" NOT NULL,
    "comprovante_url" "text",
    "status" "text" DEFAULT 'pendente'::"text",
    "aprovado_por" "uuid",
    "aprovado_em" timestamp with time zone,
    "observacoes" "text",
    "observacoes_aprovador" "text",
    "empresa_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "tipo" "text" DEFAULT 'reembolso'::"text" NOT NULL,
    "folha_id" "uuid",
    "rejeitado_motivo" "text",
    "integrado_folha_em" timestamp with time zone,
    CONSTRAINT "despesas_status_check" CHECK (("status" = ANY (ARRAY['rascunho'::"text", 'pendente'::"text", 'aprovado'::"text", 'rejeitado'::"text", 'integrado_folha'::"text", 'pago'::"text", 'cancelado'::"text"]))),
    CONSTRAINT "despesas_tipo_check" CHECK (("tipo" = ANY (ARRAY['reembolso'::"text", 'adiantamento'::"text", 'despesa_viagem'::"text", 'material'::"text", 'alimentacao'::"text", 'transporte'::"text", 'outro'::"text"]))),
    CONSTRAINT "despesas_valor_positivo" CHECK (("valor" > (0)::numeric))
);


ALTER TABLE "public"."despesas" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aprovar_despesa"("_despesa_id" "uuid", "_observacoes" "text" DEFAULT NULL::"text") RETURNS "public"."despesas"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _row public.despesas;
BEGIN
  UPDATE public.despesas
    SET status = 'aprovado',
        aprovado_por = auth.uid(),
        aprovado_em = now(),
        observacoes_aprovador = COALESCE(_observacoes, observacoes_aprovador),
        updated_at = now()
    WHERE id = _despesa_id
      AND status = 'pendente'
      AND empresa_id IN (SELECT get_user_empresas(auth.uid()))
    RETURNING * INTO _row;

  IF _row.id IS NULL THEN
    RAISE EXCEPTION 'Despesa não encontrada ou não pode ser aprovada';
  END IF;
  RETURN _row;
END;
$$;


ALTER FUNCTION "public"."aprovar_despesa"("_despesa_id" "uuid", "_observacoes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."asos_auto_marcar_agendamento_realizado"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'validado' AND OLD.status <> 'validado' AND NEW.agendamento_id IS NOT NULL THEN
    UPDATE public.exames_agendamentos
       SET status = 'realizado', updated_at = now()
     WHERE id = NEW.agendamento_id AND status <> 'realizado';
  END IF;
  RETURN NEW;
END;
$$;


