CREATE OR REPLACE FUNCTION "public"."asos_validar_restricoes"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.resultado = 'apto_com_restricoes' AND (NEW.restricoes_descricao IS NULL OR length(trim(NEW.restricoes_descricao)) < 5) THEN
    RAISE EXCEPTION 'ASO com restrições exige descrição detalhada (mínimo 5 caracteres)';
  END IF;
  IF NEW.resultado = 'apto_com_restricoes' AND NEW.restricao_data_fim IS NULL THEN
    RAISE EXCEPTION 'ASO com restrições exige data_fim da restrição';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."asos_validar_restricoes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."asos_validar_transicao_status"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_allowed BOOLEAN := FALSE;
BEGIN
  IF TG_OP = 'INSERT' THEN
    RETURN NEW;
  END IF;
  IF NEW.status = OLD.status THEN
    RETURN NEW;
  END IF;
  -- Transições permitidas
  v_allowed := (OLD.status,NEW.status) IN (
    ('rascunho','emitido_clinica'),
    ('rascunho','cancelado'),
    ('emitido_clinica','recebido_rh'),
    ('emitido_clinica','cancelado'),
    ('recebido_rh','validado'),
    ('recebido_rh','cancelado'),
    ('validado','arquivado')
  );
  IF NOT v_allowed THEN
    RAISE EXCEPTION 'Transição de status inválida: % -> %', OLD.status, NEW.status;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."asos_validar_transicao_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assinar_aviso_ferias"("p_ferias_id" "uuid", "p_hash" "text", "p_pdf_url" "text", "p_ip" "inet" DEFAULT NULL::"inet", "p_ua" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_empresa uuid;
  v_aprovado_gestor boolean;
  v_ja_assinado boolean;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT (public.has_role(v_uid, 'admin') OR public.has_role(v_uid, 'rh')) THEN
    RAISE EXCEPTION 'forbidden: apenas admin/rh podem assinar aviso' USING ERRCODE = '42501';
  END IF;

  IF p_hash IS NULL OR length(p_hash) <> 64 THEN
    RAISE EXCEPTION 'hash SHA-256 inválido' USING ERRCODE = '22023';
  END IF;

  SELECT empresa_id, COALESCE(aprovado_gestor,false), (aviso_assinatura_hash IS NOT NULL)
    INTO v_empresa, v_aprovado_gestor, v_ja_assinado
  FROM public.ferias
  WHERE id = p_ferias_id
  FOR UPDATE;

  IF v_empresa IS NULL THEN
    RAISE EXCEPTION 'ferias não encontrada' USING ERRCODE = '02000';
  END IF;

  IF NOT v_aprovado_gestor THEN
    RAISE EXCEPTION 'aviso requer aprovação prévia do gestor' USING ERRCODE = '22023';
  END IF;

  -- Idempotência: se hash idêntico já foi assinado, retornar sucesso sem regravar
  IF v_ja_assinado THEN
    IF EXISTS (SELECT 1 FROM public.ferias WHERE id = p_ferias_id AND aviso_assinatura_hash = p_hash) THEN
      RETURN jsonb_build_object('status','replay','ferias_id',p_ferias_id);
    END IF;
    RAISE EXCEPTION 'aviso já assinado com hash divergente' USING ERRCODE = '23505';
  END IF;

  UPDATE public.ferias SET
    aviso_pdf_url             = p_pdf_url,
    aviso_assinatura_hash     = p_hash,
    aviso_assinatura_em       = now(),
    aviso_assinatura_por      = v_uid,
    aviso_assinatura_ip       = p_ip,
    aviso_assinatura_user_agent = p_ua,
    aviso_gerado_em           = COALESCE(aviso_gerado_em, now()),
    aprovado_rh               = true,
    aprovado_rh_em            = now(),
    aprovado_rh_por           = v_uid,
    status_aprovacao_rh       = 'aprovada',
    updated_at                = now()
  WHERE id = p_ferias_id;

  INSERT INTO public.audit_log_unified
    (source_table, source_id, empresa_id, user_id, action, entity, entity_id, payload, ip_address, user_agent)
  VALUES
    ('ferias', p_ferias_id, v_empresa, v_uid, 'ferias.aviso_assinado', 'ferias', p_ferias_id,
     jsonb_build_object('hash', p_hash, 'pdf_url', p_pdf_url),
     p_ip, p_ua);

  RETURN jsonb_build_object('status','ok','ferias_id',p_ferias_id,'assinado_em', now());
END;
$$;


ALTER FUNCTION "public"."assinar_aviso_ferias"("p_ferias_id" "uuid", "p_hash" "text", "p_pdf_url" "text", "p_ip" "inet", "p_ua" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assinar_desligamento"("_desligamento_id" "uuid", "_parte" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.desligamentos%ROWTYPE;
  v_canonical TEXT;
  v_hash TEXT;
BEGIN
  IF _parte NOT IN ('empresa', 'colaborador') THEN
    RAISE EXCEPTION 'Parte invalida: % (use empresa ou colaborador)', _parte USING ERRCODE = '22023';
  END IF;
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Apenas administradores podem confirmar assinatura de rescisao' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_row FROM public.desligamentos WHERE id = _desligamento_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Desligamento nao encontrado' USING ERRCODE = 'P0002';
  END IF;
  IF v_row.status NOT IN ('calculado', 'em_homologacao') THEN
    RAISE EXCEPTION 'Rescisao precisa estar calculada e ainda nao homologada (status atual: %)', v_row.status
      USING ERRCODE = 'check_violation';
  END IF;
  IF (_parte = 'empresa' AND v_row.assinado_empresa) OR (_parte = 'colaborador' AND v_row.assinado_colaborador) THEN
    RAISE EXCEPTION 'Esta parte ja assinou esta rescisao' USING ERRCODE = 'check_violation';
  END IF;

  v_canonical := COALESCE(v_row.colaborador_id::text,'') || '|' || COALESCE(v_row.empresa_id::text,'') || '|' ||
                 COALESCE(v_row.valor_liquido::text,'0') || '|' || _parte || '|' || auth.uid()::text || '|' || clock_timestamp()::text;
  v_hash := encode(digest(v_canonical, 'sha256'), 'hex');

  PERFORM set_config('app.allow_signature_write', 'true', true);

  IF _parte = 'empresa' THEN
    UPDATE public.desligamentos
    SET assinado_empresa = true, hash_assinatura_empresa = v_hash, data_assinatura_empresa = now()
    WHERE id = _desligamento_id;
  ELSE
    UPDATE public.desligamentos
    SET assinado_colaborador = true, hash_assinatura_colaborador = v_hash, data_assinatura_colaborador = now()
    WHERE id = _desligamento_id;
  END IF;

  INSERT INTO public.audit_log (tabela, registro_id, acao, user_id, dados_novos)
  VALUES ('desligamentos', _desligamento_id, 'UPDATE', auth.uid(),
          jsonb_build_object('action','assinar_desligamento','parte',_parte,'hash',v_hash));

  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."assinar_desligamento"("_desligamento_id" "uuid", "_parte" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assinar_espelho_ponto"("_colaborador_id" "uuid", "_competencia" "text", "_ip" "inet" DEFAULT NULL::"inet", "_user_agent" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_canonical jsonb;
  v_hash text;
  v_empresa_id uuid;
  v_periodo_inicio date;
  v_periodo_fim date;
  v_espelho_id uuid;
  v_total int;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Autenticação requerida';
  END IF;

  -- Validar acesso: colaborador assinando o próprio OU admin/RH da empresa
  SELECT c.empresa_id INTO v_empresa_id
    FROM public.colaboradores c
   WHERE c.id = _colaborador_id;

  IF v_empresa_id IS NULL THEN
    RAISE EXCEPTION 'Colaborador inválido';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.user_empresas
    WHERE user_id = auth.uid() AND empresa_id = v_empresa_id
  ) AND auth.uid() <> _colaborador_id THEN
    RAISE EXCEPTION 'Sem permissão para assinar este espelho';
  END IF;

  v_periodo_inicio := to_date(_competencia || '-01', 'YYYY-MM-DD');
  v_periodo_fim := (v_periodo_inicio + interval '1 month' - interval '1 day')::date;

  v_canonical := public.gerar_canonical_espelho_ponto(_colaborador_id, _competencia);
  v_hash := encode(digest(v_canonical::text, 'sha256'), 'hex');
  v_total := (v_canonical->>'total_batidas')::int;

  -- Impedir reassinatura salvo se revogado
  IF EXISTS (
    SELECT 1 FROM public.ponto_espelhos_assinados
    WHERE colaborador_id = _colaborador_id AND competencia = _competencia
      AND NOT EXISTS (
        SELECT 1 FROM public.ponto_espelhos_revogacoes r
        WHERE r.espelho_id = ponto_espelhos_assinados.id
      )
  ) THEN
    RAISE EXCEPTION 'Espelho já assinado para esta competência (revogue antes de reassinar)';
  END IF;

  INSERT INTO public.ponto_espelhos_assinados (
    colaborador_id, empresa_id, competencia,
    periodo_inicio, periodo_fim,
    canonical_json, hash_sha256, total_batidas,
    assinado_por_user_id, assinado_ip, assinado_user_agent,
    assinado_em, data_assinatura_colaborador, status_assinatura
  ) VALUES (
    _colaborador_id, v_empresa_id, _competencia,
    v_periodo_inicio, v_periodo_fim,
    v_canonical, v_hash, v_total,
    auth.uid(), _ip, _user_agent,
    now(), now(), 'assinado'
  )
  RETURNING id INTO v_espelho_id;

  RETURN jsonb_build_object(
    'success', true,
    'espelho_id', v_espelho_id,
    'hash_sha256', v_hash,
    'total_batidas', v_total,
    'competencia', _competencia,
    'assinado_em', now()
  );
END;
$$;


ALTER FUNCTION "public"."assinar_espelho_ponto"("_colaborador_id" "uuid", "_competencia" "text", "_ip" "inet", "_user_agent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."associar_pis_colaborador_afdt"("_divergencia_id" "uuid", "_colaborador_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_div public.afdt_divergencias%ROWTYPE;
  v_colab_empresa uuid;
BEGIN
  SELECT * INTO v_div FROM public.afdt_divergencias WHERE id = _divergencia_id;
  IF v_div.id IS NULL THEN RAISE EXCEPTION 'Divergência não encontrada'; END IF;
  IF v_div.pis IS NULL THEN RAISE EXCEPTION 'Divergência sem PIS'; END IF;

  SELECT empresa_id INTO v_colab_empresa FROM public.colaboradores WHERE id = _colaborador_id;
  IF v_colab_empresa IS NULL OR v_colab_empresa <> v_div.empresa_id THEN
    RAISE EXCEPTION 'Colaborador não pertence à empresa da divergência';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.user_empresas WHERE user_id = auth.uid() AND empresa_id = v_div.empresa_id) THEN
    RAISE EXCEPTION 'Sem permissão para esta empresa';
  END IF;

  -- Atualiza PIS do colaborador apenas se estiver vazio (evita sobrescrever)
  UPDATE public.colaboradores
     SET pis_pasep = v_div.pis
   WHERE id = _colaborador_id
     AND (pis_pasep IS NULL OR pis_pasep = '');

  UPDATE public.afdt_divergencias
     SET colaborador_id = _colaborador_id,
         observacao = COALESCE(observacao, '') || ' [PIS associado ao colaborador ' || _colaborador_id || ']'
   WHERE id = _divergencia_id;

  INSERT INTO public.trilha_auditoria_ponto (empresa_id, colaborador_id, acao, detalhes, executado_por)
  VALUES (v_div.empresa_id, _colaborador_id, 'pis_associado_via_afdt',
          jsonb_build_object('divergencia_id', _divergencia_id, 'pis', v_div.pis),
          auth.uid());
END; $$;


ALTER FUNCTION "public"."associar_pis_colaborador_afdt"("_divergencia_id" "uuid", "_colaborador_id" "uuid") OWNER TO "postgres";


