    INSERT INTO public.provisoes_folha (empresa_id, colaborador_id, competencia, valor_13_salario, valor_ferias, encargos_provisao)
    VALUES (
        NEW.empresa_id,
        NEW.colaborador_id,
        NEW.competencia,
        NEW.total_proventos / 12,
        (NEW.total_proventos / 12) * 1.33, -- 1/12 + 1/3
