CREATE OR REPLACE FUNCTION "public"."calculate_lockout_duration"("attempts" integer) RETURNS interval
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN LEAST(POWER(2, GREATEST(0, attempts - 5))::INTEGER * INTERVAL '1 minute', INTERVAL '60 minutes');
END;
$$;


ALTER FUNCTION "public"."calculate_lockout_duration"("attempts" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_brute_force"("check_email" "text", "check_ip" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  failed_count INTEGER;
  policy_record RECORD;
BEGIN
  SELECT * INTO policy_record FROM public.password_policies LIMIT 1;
  IF NOT FOUND THEN
    policy_record.lockout_attempts := 5;
    policy_record.lockout_duration_minutes := 30;
  END IF;
  SELECT COUNT(*) INTO failed_count
  FROM public.login_attempts
  WHERE (email = check_email OR ip_address = check_ip)
  AND success = false
  AND created_at > now() - (policy_record.lockout_duration_minutes || ' minutes')::INTERVAL;
  IF failed_count >= policy_record.lockout_attempts THEN
    INSERT INTO public.security_alerts (type, severity, ip_address, details)
    VALUES ('brute_force', 'critical', check_ip, jsonb_build_object('email', check_email, 'attempts', failed_count));
    RETURN jsonb_build_object('locked', true, 'attempts', failed_count, 'lockout_minutes', policy_record.lockout_duration_minutes);
  END IF;
  RETURN jsonb_build_object('locked', false, 'attempts', failed_count, 'remaining', policy_record.lockout_attempts - failed_count);
END;
$$;


ALTER FUNCTION "public"."check_brute_force"("check_email" "text", "check_ip" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_ciencia_rate_limit"("p_rpc_name" "text", "p_identifier" "text" DEFAULT NULL::"text", "p_max_requests" integer DEFAULT 30, "p_window_minutes" integer DEFAULT 10) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ip INET;
  v_count INT;
BEGIN
  BEGIN
    v_ip := COALESCE(
      NULLIF(current_setting('request.headers', true)::json->>'x-forwarded-for', ''),
      NULLIF(current_setting('request.headers', true)::json->>'cf-connecting-ip', ''),
      '0.0.0.0'
    )::INET;
  EXCEPTION WHEN OTHERS THEN
    v_ip := '0.0.0.0'::INET;
  END;

  SELECT COUNT(*) INTO v_count
  FROM public.ciencia_rate_limits
  WHERE ip_address = v_ip
    AND rpc_name = p_rpc_name
    AND created_at > now() - (p_window_minutes || ' minutes')::INTERVAL;

  INSERT INTO public.ciencia_rate_limits (ip_address, rpc_name, identifier, success)
  VALUES (v_ip, p_rpc_name, p_identifier, v_count < p_max_requests);

  RETURN v_count < p_max_requests;
END;
$$;


ALTER FUNCTION "public"."check_ciencia_rate_limit"("p_rpc_name" "text", "p_identifier" "text", "p_max_requests" integer, "p_window_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_idempotency_anomalies"() RETURNS TABLE("endpoint" "text", "severity" "text", "reason" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  r RECORD;
  v_stuck_count INTEGER;
BEGIN
  -- 1) Endpoints com taxa de falha > 5% nas últimas 24h (mínimo 10 chamadas para relevância estatística)
  FOR r IN
    SELECT
      m.endpoint,
      m.total_24h,
      m.failed_24h,
      m.failure_rate_pct_24h
    FROM public.v_idempotency_metrics m
    WHERE m.total_24h >= 10
      AND m.failure_rate_pct_24h > 5
  LOOP
    -- Deduplica: só cria alerta se não houver alerta ativo (não resolvido) na última hora
    IF NOT EXISTS (
      SELECT 1 FROM public.security_alerts
      WHERE type = 'IDEMPOTENCY_HIGH_FAILURE'
        AND details->>'endpoint' = r.endpoint
        AND resolved = false
        AND created_at > now() - interval '1 hour'
    ) THEN
      INSERT INTO public.security_alerts (type, severity, details)
      VALUES (
        'IDEMPOTENCY_HIGH_FAILURE',
        CASE WHEN r.failure_rate_pct_24h > 20 THEN 'critical'
             WHEN r.failure_rate_pct_24h > 10 THEN 'high'
             ELSE 'medium' END,
        jsonb_build_object(
          'endpoint', r.endpoint,
          'failure_rate_pct', r.failure_rate_pct_24h,
          'total_24h', r.total_24h,
          'failed_24h', r.failed_24h,
          'detected_at', now()
        )
      );

      RETURN QUERY SELECT
        r.endpoint::TEXT,
        (CASE WHEN r.failure_rate_pct_24h > 20 THEN 'critical'
              WHEN r.failure_rate_pct_24h > 10 THEN 'high'
              ELSE 'medium' END)::TEXT,
        format('Taxa de falha %s%% em %s chamadas', r.failure_rate_pct_24h, r.total_24h)::TEXT;
    END IF;
  END LOOP;

  -- 2) Chaves "pending" há mais de 10 minutos (possível travamento transacional)
  SELECT COUNT(*) INTO v_stuck_count
  FROM public.idempotency_keys
  WHERE status = 'pending'
    AND created_at < now() - interval '10 minutes'
    AND expires_at > now();

  IF v_stuck_count > 0 THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.security_alerts
      WHERE type = 'IDEMPOTENCY_STUCK_PENDING'
        AND resolved = false
        AND created_at > now() - interval '1 hour'
    ) THEN
      INSERT INTO public.security_alerts (type, severity, details)
      VALUES (
        'IDEMPOTENCY_STUCK_PENDING',
        CASE WHEN v_stuck_count > 20 THEN 'high' ELSE 'medium' END,
        jsonb_build_object(
          'stuck_count', v_stuck_count,
          'threshold_minutes', 10,
          'detected_at', now()
        )
      );

      RETURN QUERY SELECT
        'multiple'::TEXT,
        (CASE WHEN v_stuck_count > 20 THEN 'high' ELSE 'medium' END)::TEXT,
        format('%s chamadas idempotentes travadas em pending > 10min', v_stuck_count)::TEXT;
    END IF;
  END IF;
END;
$$;


ALTER FUNCTION "public"."check_idempotency_anomalies"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_login_lock"("p_identifier" "text", "p_identifier_type" "text" DEFAULT 'email'::"text") RETURNS TABLE("is_locked" boolean, "remaining_seconds" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_locked boolean;
  v_until timestamptz;
BEGIN
  SELECT ll.is_locked, ll.lockout_until INTO v_locked, v_until
  FROM public.login_lockouts ll
  WHERE ll.identifier = lower(p_identifier)
    AND ll.identifier_type = p_identifier_type;

  IF v_locked AND v_until IS NOT NULL AND v_until > now() THEN
    RETURN QUERY SELECT true, EXTRACT(EPOCH FROM (v_until - now()))::integer;
  ELSE
    IF v_locked THEN
      UPDATE public.login_lockouts
         SET is_locked = false, lockout_until = NULL, attempts = 0, updated_at = now()
       WHERE identifier = lower(p_identifier)
         AND identifier_type = p_identifier_type;
    END IF;
    RETURN QUERY SELECT false, 0;
  END IF;
END;
$$;


ALTER FUNCTION "public"."check_login_lock"("p_identifier" "text", "p_identifier_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_processamento_timeout"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    -- Se o status for alterado para 'failed' e o erro contiver 'timeout'
    IF NEW.status = 'failed' AND NEW.erro_log ILIKE '%timeout%' THEN
        INSERT INTO public.security_alerts (
            title,
            description,
            severity,
            metadata
        ) VALUES (
            'Timeout Detectado na Fila',
            'A tarefa do tipo ' || NEW.tipo_tarefa || ' (ID: ' || NEW.id || ') falhou por timeout.',
            'medium',
            jsonb_build_object('task_id', NEW.id, 'task_type', NEW.tipo_tarefa)
        );
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_processamento_timeout"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_rate_limit"("check_ip" "text", "check_endpoint" "text", "check_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  config_record RECORD;
  current_count INTEGER;
  is_blocked BOOLEAN;
  result JSONB;
BEGIN
  -- Verificar se IP está na whitelist
  IF public.is_ip_whitelisted(check_ip) THEN
    RETURN jsonb_build_object('allowed', true, 'reason', 'whitelisted');
  END IF;

  -- Verificar se IP está bloqueado
  IF public.is_ip_blocked(check_ip) THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'blocked');
  END IF;

  -- Obter configuração de rate limit
  SELECT * INTO config_record FROM public.rate_limit_config
  WHERE endpoint = check_endpoint OR endpoint = '*'
  ORDER BY CASE WHEN endpoint = check_endpoint THEN 0 ELSE 1 END
  LIMIT 1;

  IF NOT FOUND OR NOT config_record.enabled THEN
    RETURN jsonb_build_object('allowed', true, 'reason', 'no_limit');
  END IF;

  -- Contar requisições na janela de tempo
  SELECT COUNT(*) INTO current_count
  FROM public.rate_limit_logs
  WHERE ip_address = check_ip
  AND endpoint = check_endpoint
  AND created_at > now() - (config_record.window_seconds || ' seconds')::INTERVAL;

  IF current_count >= config_record.max_requests THEN
    -- Bloquear IP temporariamente
    INSERT INTO public.blocked_ips (ip_address, reason, expires_at, permanent)
    VALUES (
      check_ip,
      'Rate limit exceeded for ' || check_endpoint,
      now() + (config_record.block_duration_seconds || ' seconds')::INTERVAL,
      false
    )
    ON CONFLICT (ip_address) DO UPDATE SET
      expires_at = now() + (config_record.block_duration_seconds || ' seconds')::INTERVAL;

    -- Criar alerta de segurança
    INSERT INTO public.security_alerts (type, severity, ip_address, user_id, details)
    VALUES (
      'rate_limit_exceeded',
      'high',
      check_ip,
      check_user_id,
      jsonb_build_object('endpoint', check_endpoint, 'count', current_count)
    );

    RETURN jsonb_build_object(
      'allowed', false,
      'reason', 'rate_limit_exceeded',
      'retry_after', config_record.block_duration_seconds
    );
  END IF;

  -- Registrar requisição
  INSERT INTO public.rate_limit_logs (ip_address, endpoint, user_id)
  VALUES (check_ip, check_endpoint, check_user_id);

  RETURN jsonb_build_object(
    'allowed', true,
    'remaining', config_record.max_requests - current_count - 1,
    'reset_in', config_record.window_seconds
  );
END;
$$;


