CREATE OR REPLACE FUNCTION "public"."consumir_pendencias_medida_no_holerite"("p_holerite_id" "uuid", "p_colaborador_id" "uuid", "p_competencia" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pend RECORD;
  v_count INTEGER := 0;
BEGIN
  FOR v_pend IN
    SELECT * FROM public.medidas_disciplinares_integracao
    WHERE colaborador_id = p_colaborador_id
      AND tipo_integracao = 'lancamento_folha_pendente'
      AND status = 'pendente'
      AND (competencia IS NULL OR competencia <= p_competencia)
    FOR UPDATE
  LOOP
    INSERT INTO public.lancamentos_folha (
      holerite_id, rubrica_id, rubrica_codigo, rubrica_descricao,
      tipo, referencia, valor, automatico
    ) VALUES (
      p_holerite_id,
      (v_pend.detalhes->>'rubrica_id')::uuid,
      COALESCE(v_pend.detalhes->>'rubrica_codigo','DESC_SUSP'),
      'Desconto por Suspensão Disciplinar',
      'desconto'::tipo_evento_folha,
      v_pend.dias,
      v_pend.valor,
      true
    );

    UPDATE public.medidas_disciplinares_integracao
    SET status = 'aplicado',
        tipo_integracao = 'lancamento_folha_aplicado',
        detalhes = detalhes || jsonb_build_object('holerite_id', p_holerite_id, 'aplicado_em', now())
    WHERE id = v_pend.id;

    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."consumir_pendencias_medida_no_holerite"("p_holerite_id" "uuid", "p_colaborador_id" "uuid", "p_competencia" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contrato_assinar_por_token"("p_token" "text", "p_cpf" "text", "p_nome_completo" "text", "p_ip" "inet" DEFAULT NULL::"inet", "p_user_agent" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_hash TEXT;
  v_tok RECORD;
  v_assinatura_hash TEXT;
  v_cpf_limpo TEXT;
BEGIN
  IF p_token IS NULL OR length(p_token) < 16 THEN RAISE EXCEPTION 'Token inválido'; END IF;
  IF p_nome_completo IS NULL OR length(trim(p_nome_completo)) < 5 THEN
    RAISE EXCEPTION 'Nome completo obrigatório';
  END IF;

  v_cpf_limpo := regexp_replace(COALESCE(p_cpf,''), '\D', '', 'g');
  IF length(v_cpf_limpo) <> 11 THEN RAISE EXCEPTION 'CPF inválido'; END IF;

  v_hash := encode(digest(p_token, 'sha256'), 'hex');

  SELECT * INTO v_tok FROM public.contrato_assinatura_tokens
  WHERE token_hash = v_hash FOR UPDATE;

  IF v_tok IS NULL THEN RAISE EXCEPTION 'Token não encontrado'; END IF;
  IF v_tok.usado_em IS NOT NULL THEN RAISE EXCEPTION 'Token já utilizado'; END IF;
  IF v_tok.expira_em < now() THEN RAISE EXCEPTION 'Token expirado'; END IF;

  IF v_tok.cpf_esperado IS NOT NULL
    AND regexp_replace(v_tok.cpf_esperado, '\D', '', 'g') <> v_cpf_limpo THEN
    RAISE EXCEPTION 'CPF não confere com o destinatário';
  END IF;

  -- Hash de assinatura: contrato_sha256 + cpf + nome + timestamp + ip
  v_assinatura_hash := encode(digest(
    COALESCE((SELECT sha256 FROM public.contratos_gerados WHERE id = v_tok.contrato_id),'') ||
    v_cpf_limpo || upper(trim(p_nome_completo)) ||
    now()::text || COALESCE(p_ip::text,''),
    'sha256'
  ), 'hex');

  UPDATE public.contrato_assinatura_tokens
  SET usado_em = now(),
      assinado_ip = p_ip,
      assinado_ua = p_user_agent,
      assinatura_hash = v_assinatura_hash
  WHERE id = v_tok.id;

  UPDATE public.contratos_gerados
  SET status = 'assinado',
      assinado_em = now(),
      assinatura_metadata = jsonb_build_object(
        'cpf', v_cpf_limpo,
        'nome', upper(trim(p_nome_completo)),
        'ip', p_ip::text,
        'user_agent', p_user_agent,
        'assinatura_hash', v_assinatura_hash,
        'assinado_em', now()
      )
  WHERE id = v_tok.contrato_id;

  RETURN jsonb_build_object(
    'success', true,
    'contrato_id', v_tok.contrato_id,
    'assinatura_hash', v_assinatura_hash,
    'assinado_em', now()
  );
END;
$$;


ALTER FUNCTION "public"."contrato_assinar_por_token"("p_token" "text", "p_cpf" "text", "p_nome_completo" "text", "p_ip" "inet", "p_user_agent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contrato_consultar_por_token"("p_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_hash TEXT;
  v_tok RECORD;
  v_c RECORD;
BEGIN
  IF p_token IS NULL OR length(p_token) < 16 THEN RAISE EXCEPTION 'Token inválido'; END IF;
  v_hash := encode(digest(p_token, 'sha256'), 'hex');

  SELECT * INTO v_tok FROM public.contrato_assinatura_tokens WHERE token_hash = v_hash;
  IF v_tok IS NULL THEN RAISE EXCEPTION 'Token não encontrado'; END IF;
  IF v_tok.usado_em IS NOT NULL THEN RAISE EXCEPTION 'Token já utilizado'; END IF;
  IF v_tok.expira_em < now() THEN RAISE EXCEPTION 'Token expirado'; END IF;
  IF v_tok.tentativas > 20 THEN RAISE EXCEPTION 'Muitas tentativas'; END IF;

  UPDATE public.contrato_assinatura_tokens SET tentativas = tentativas + 1 WHERE id = v_tok.id;

  SELECT id, empresa_id, status, sha256, storage_path, data_inicio, data_fim, template_id
    INTO v_c FROM public.contratos_gerados WHERE id = v_tok.contrato_id;

  RETURN jsonb_build_object(
    'contrato_id', v_c.id,
    'status', v_c.status,
    'sha256', v_c.sha256,
    'data_inicio', v_c.data_inicio,
    'data_fim', v_c.data_fim,
    'requer_cpf', (v_tok.cpf_esperado IS NOT NULL),
    'expira_em', v_tok.expira_em
  );
END;
$$;


ALTER FUNCTION "public"."contrato_consultar_por_token"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contrato_estender_expiracao"("p_token_id" "uuid", "p_dias" integer DEFAULT 7) RETURNS TABLE("id" "uuid", "expira_em" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_empresa uuid;
  v_role text;
  v_current timestamptz;
  v_new timestamptz;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'não autenticado' USING ERRCODE = '42501';
  END IF;
  IF p_dias IS NULL OR p_dias < 1 OR p_dias > 30 THEN
    RAISE EXCEPTION 'extensão deve estar entre 1 e 30 dias' USING ERRCODE = '22023';
  END IF;

  SELECT t.empresa_id, t.expira_em
    INTO v_empresa, v_current
  FROM public.contrato_assinatura_tokens t
  WHERE t.id = p_token_id
    AND t.revogado_em IS NULL
    AND t.usado_em IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'token inexistente, revogado ou já utilizado' USING ERRCODE = '02000';
  END IF;

  SELECT ur.role::text INTO v_role
  FROM public.user_roles ur
  WHERE ur.user_id = v_user
    AND ur.role::text IN ('admin','rh','super_admin')
  LIMIT 1;

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'perfil sem permissão para estender token' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.user_empresas ue
    WHERE ue.user_id = v_user AND ue.empresa_id = v_empresa
  ) THEN
    RAISE EXCEPTION 'sem acesso à empresa do token' USING ERRCODE = '42501';
  END IF;

  v_new := GREATEST(v_current, now()) + make_interval(days => p_dias);

  UPDATE public.contrato_assinatura_tokens
     SET expira_em = v_new
   WHERE id = p_token_id
  RETURNING contrato_assinatura_tokens.id, contrato_assinatura_tokens.expira_em
  INTO id, expira_em;

  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."contrato_estender_expiracao"("p_token_id" "uuid", "p_dias" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contrato_gerar_token_assinatura"("p_contrato_id" "uuid", "p_email" "text" DEFAULT NULL::"text", "p_cpf" "text" DEFAULT NULL::"text", "p_validade_dias" integer DEFAULT 7) RETURNS TABLE("token" "text", "expira_em" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_empresa UUID;
  v_status TEXT;
  v_token TEXT;
  v_hash TEXT;
  v_exp TIMESTAMPTZ;
BEGIN
  SELECT empresa_id, status INTO v_empresa, v_status
  FROM public.contratos_gerados WHERE id = p_contrato_id;

  IF v_empresa IS NULL THEN RAISE EXCEPTION 'Contrato não encontrado'; END IF;

  IF NOT public.user_belongs_to_empresa(auth.uid(), v_empresa)
    OR NOT (public.has_role(auth.uid(),'admin'::app_role) OR public.has_role(auth.uid(),'rh'::app_role))
  THEN
    RAISE EXCEPTION 'Sem permissão';
  END IF;

  IF v_status = 'assinado' THEN RAISE EXCEPTION 'Contrato já assinado'; END IF;
  IF v_status = 'cancelado' THEN RAISE EXCEPTION 'Contrato cancelado'; END IF;

  -- Token de 32 chars, retornado apenas uma vez em claro; armazena SHA-256
  v_token := encode(gen_random_bytes(24), 'base64');
  v_token := regexp_replace(v_token, '[^A-Za-z0-9]', '', 'g');
  v_token := substr(v_token || encode(gen_random_bytes(12),'hex'), 1, 32);
  v_hash := encode(digest(v_token, 'sha256'), 'hex');
  v_exp := now() + make_interval(days => GREATEST(1, LEAST(30, p_validade_dias)));

  INSERT INTO public.contrato_assinatura_tokens(
    contrato_id, empresa_id, token_hash, cpf_esperado, email_destinatario, expira_em, created_by
  ) VALUES (p_contrato_id, v_empresa, v_hash, p_cpf, p_email, v_exp, auth.uid());

  UPDATE public.contratos_gerados SET status = 'enviado' WHERE id = p_contrato_id AND status = 'gerado';

  RETURN QUERY SELECT v_token, v_exp;
END;
$$;


ALTER FUNCTION "public"."contrato_gerar_token_assinatura"("p_contrato_id" "uuid", "p_email" "text", "p_cpf" "text", "p_validade_dias" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contrato_lembretes_pendentes"() RETURNS TABLE("processados" integer, "notificados" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_proc int := 0;
  v_notif int := 0;
  r RECORD;
  v_gestor uuid;
  v_dias_restantes int;
BEGIN
  FOR r IN
    SELECT t.id, t.contrato_id, t.empresa_id, t.email_destinatario, t.expira_em,
           t.reminders_enviados, cg.colaborador_id
    FROM public.contrato_assinatura_tokens t
    JOIN public.contratos_gerados cg ON cg.id = t.contrato_id
    WHERE t.usado_em IS NULL
      AND t.revogado_em IS NULL
      AND t.expira_em > now()
      AND t.expira_em <= now() + interval '3 days'
      AND (t.ultimo_reminder_at IS NULL OR t.ultimo_reminder_at < now() - interval '20 hours')
      AND COALESCE(t.reminders_enviados, 0) < 3
    LIMIT 200
  LOOP
    v_proc := v_proc + 1;
    v_dias_restantes := GREATEST(0, EXTRACT(DAY FROM r.expira_em - now())::int);

    INSERT INTO public.contrato_token_eventos (token_id, contrato_id, evento, detalhes)
    VALUES (r.id, r.contrato_id, 'reminder_enviado',
            jsonb_build_object('dias_restantes', v_dias_restantes,
                               'destinatario', r.email_destinatario,
                               'tentativa', COALESCE(r.reminders_enviados, 0) + 1));

    SELECT ur.user_id INTO v_gestor
    FROM public.user_empresas ue
    JOIN public.user_roles ur ON ur.user_id = ue.user_id
    WHERE ue.empresa_id = r.empresa_id
      AND ur.role IN ('admin','rh','gestor')
    LIMIT 1;

    IF v_gestor IS NOT NULL THEN
      INSERT INTO public.notificacoes (user_id, empresa_id, tipo, titulo, mensagem, entidade_tipo, entidade_id)
      VALUES (v_gestor, r.empresa_id, 'contrato_pendente',
              'Contrato aguardando assinatura',
              format('Contrato expira em %s dia(s). Destinatário: %s', v_dias_restantes, COALESCE(r.email_destinatario,'—')),
              'contrato_gerado', r.contrato_id);
      v_notif := v_notif + 1;
    END IF;

    UPDATE public.contrato_assinatura_tokens
       SET reminders_enviados = COALESCE(reminders_enviados, 0) + 1,
           ultimo_reminder_at = now()
     WHERE id = r.id;
  END LOOP;

  RETURN QUERY SELECT v_proc, v_notif;
END;
$$;


ALTER FUNCTION "public"."contrato_lembretes_pendentes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contrato_montar_variaveis"("p_admissao_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v JSONB;
BEGIN
  SELECT jsonb_build_object(
    'admissao', to_jsonb(a),
    'empresa', to_jsonb(e),
    'cargo', to_jsonb(c),
    'departamento', to_jsonb(d),
    'gerado_em', to_char(now() AT TIME ZONE 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI')
  )
  INTO v
  FROM public.admissoes a
  LEFT JOIN public.empresas e ON e.id = a.empresa_id
  LEFT JOIN public.cargos c ON c.empresa_id = a.empresa_id AND lower(c.nome) = lower(a.cargo)
  LEFT JOIN public.departamentos d ON d.empresa_id = a.empresa_id AND lower(d.nome) = lower(a.departamento)
  WHERE a.id = p_admissao_id;

  IF v IS NULL THEN RAISE EXCEPTION 'Admissão % não encontrada', p_admissao_id; END IF;
  IF NOT public.user_belongs_to_empresa(auth.uid(), (v->'admissao'->>'empresa_id')::uuid) THEN
    RAISE EXCEPTION 'Sem acesso a esta admissão';
  END IF;
  RETURN v;
END; $$;


ALTER FUNCTION "public"."contrato_montar_variaveis"("p_admissao_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contrato_preview_url_por_token"("p_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_token_hash text;
  v_tok record;
  v_contrato record;
  v_signed jsonb;
BEGIN
  IF p_token IS NULL OR length(p_token) < 16 THEN
    RAISE EXCEPTION 'Token inválido';
  END IF;
  v_token_hash := encode(digest(p_token, 'sha256'), 'hex');

  SELECT * INTO v_tok
  FROM public.contrato_assinatura_tokens
  WHERE token_hash = v_token_hash
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Token não encontrado ou inválido';
  END IF;
  IF v_tok.revogado_em IS NOT NULL THEN
    RAISE EXCEPTION 'Token revogado';
  END IF;
  IF v_tok.usado_em IS NOT NULL THEN
    RAISE EXCEPTION 'Contrato já assinado';
  END IF;
  IF v_tok.expira_em < now() THEN
    RAISE EXCEPTION 'Token expirado';
  END IF;

  SELECT id, storage_path INTO v_contrato
  FROM public.contratos_gerados
  WHERE id = v_tok.contrato_id
  LIMIT 1;

  IF NOT FOUND OR v_contrato.storage_path IS NULL THEN
    RAISE EXCEPTION 'Documento indisponível';
  END IF;

  -- Cria signed URL de 10 minutos via storage API
  SELECT jsonb_build_object(
    'signedURL', (storage.create_signed_url('contratos-trabalho', v_contrato.storage_path, 600))
  ) INTO v_signed;

  RETURN jsonb_build_object(
    'path', v_contrato.storage_path,
    'signed_url', v_signed->>'signedURL',
    'expira_em', (now() + interval '10 minutes')
  );
END;
$$;


ALTER FUNCTION "public"."contrato_preview_url_por_token"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contrato_resolver_template"("p_admissao_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_empresa UUID; v_cargo TEXT; v_cargo_id UUID; v_tipo TEXT; v_template UUID;
BEGIN
  SELECT a.empresa_id, a.cargo, COALESCE((a.metadata->>'tipo_contrato'),'clt_indeterminado')
    INTO v_empresa, v_cargo, v_tipo
  FROM public.admissoes a WHERE a.id = p_admissao_id;
  IF v_empresa IS NULL THEN RAISE EXCEPTION 'Admissão % não encontrada', p_admissao_id; END IF;
  IF NOT public.user_belongs_to_empresa(auth.uid(), v_empresa) THEN
    RAISE EXCEPTION 'Sem acesso a esta admissão';
  END IF;

  SELECT id INTO v_cargo_id FROM public.cargos
    WHERE empresa_id = v_empresa AND lower(nome) = lower(v_cargo) LIMIT 1;

  -- 1) match exato (empresa, tipo, cargo)
  SELECT id INTO v_template FROM public.contrato_templates
    WHERE empresa_id = v_empresa AND tipo_contrato = v_tipo
      AND cargo_id = v_cargo_id AND ativo LIMIT 1;
  -- 2) fallback: mesmo tipo, sem cargo
  IF v_template IS NULL THEN
    SELECT id INTO v_template FROM public.contrato_templates
      WHERE empresa_id = v_empresa AND tipo_contrato = v_tipo
        AND cargo_id IS NULL AND ativo LIMIT 1;
  END IF;
  RETURN v_template;
END; $$;


ALTER FUNCTION "public"."contrato_resolver_template"("p_admissao_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contrato_revogar_token"("p_token_id" "uuid", "p_motivo" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_empresa uuid;
  v_usado timestamptz;
  v_revogado timestamptz;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'auth_required' USING ERRCODE = '42501';
  END IF;

  SELECT empresa_id, usado_em, revogado_em
    INTO v_empresa, v_usado, v_revogado
  FROM public.contrato_assinatura_tokens
  WHERE id = p_token_id;

  IF v_empresa IS NULL THEN
    RAISE EXCEPTION 'token_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.user_belongs_to_empresa(v_uid, v_empresa) THEN
    RAISE EXCEPTION 'forbidden_tenant' USING ERRCODE = '42501';
  END IF;

  IF NOT (public.has_role(v_uid, 'admin'::app_role) OR public.has_role(v_uid, 'rh'::app_role)) THEN
    RAISE EXCEPTION 'forbidden_role' USING ERRCODE = '42501';
  END IF;

  IF v_usado IS NOT NULL THEN
    RAISE EXCEPTION 'token_already_signed' USING ERRCODE = '22023';
  END IF;

  -- Idempotente: se já revogado, apenas retorna
  IF v_revogado IS NOT NULL THEN
    RETURN;
  END IF;

  UPDATE public.contrato_assinatura_tokens
  SET revogado_em = now(),
      revogado_por = v_uid,
      revogacao_motivo = NULLIF(trim(p_motivo), '')
  WHERE id = p_token_id;
END;
$$;


ALTER FUNCTION "public"."contrato_revogar_token"("p_token_id" "uuid", "p_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contrato_token_evento_registrar"("p_token_id" "uuid", "p_evento" "text", "p_detalhes" "jsonb" DEFAULT '{}'::"jsonb", "p_ip" "inet" DEFAULT NULL::"inet", "p_ua" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_empresa UUID;
  v_contrato UUID;
  v_id UUID;
BEGIN
  SELECT empresa_id, contrato_id INTO v_empresa, v_contrato
  FROM public.contrato_assinatura_tokens WHERE id = p_token_id;
  IF v_empresa IS NULL THEN
    RAISE EXCEPTION 'Token % não encontrado', p_token_id;
  END IF;

  INSERT INTO public.contrato_token_eventos(
    empresa_id, token_id, contrato_id, evento, detalhes, ator_id, ip, user_agent
  ) VALUES (
    v_empresa, p_token_id, v_contrato, p_evento,
    COALESCE(p_detalhes, '{}'::jsonb), auth.uid(), p_ip, p_ua
  ) RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."contrato_token_evento_registrar"("p_token_id" "uuid", "p_evento" "text", "p_detalhes" "jsonb", "p_ip" "inet", "p_ua" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contrato_verificar_autenticidade"("p_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_hash text;
  v_row record;
BEGIN
  IF p_hash IS NULL OR length(p_hash) < 32 THEN
    RETURN jsonb_build_object('valido', false, 'motivo', 'Hash inválido');
  END IF;
  v_hash := lower(trim(p_hash));

  SELECT
    cg.id,
    cg.status,
    cg.assinado_em,
    cg.sha256 AS documento_hash,
    cg.data_inicio,
    cg.data_fim,
    e.razao_social AS empresa_nome,
    c.nome_completo AS colaborador_nome,
    c.cpf AS colaborador_cpf,
    t.assinatura_hash
  INTO v_row
  FROM public.contratos_gerados cg
  LEFT JOIN public.contrato_assinatura_tokens t ON t.contrato_id = cg.id AND t.usado_em IS NOT NULL
  LEFT JOIN public.empresas e ON e.id = cg.empresa_id
  LEFT JOIN public.colaboradores c ON c.id = cg.colaborador_id
  WHERE lower(cg.sha256) = v_hash
     OR lower(t.assinatura_hash) = v_hash
  ORDER BY cg.assinado_em DESC NULLS LAST
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('valido', false, 'motivo', 'Contrato não encontrado');
  END IF;

  RETURN jsonb_build_object(
    'valido', v_row.status = 'assinado' AND v_row.assinado_em IS NOT NULL,
    'status', v_row.status,
    'assinado_em', v_row.assinado_em,
    'documento_hash', v_row.documento_hash,
    'assinatura_hash', v_row.assinatura_hash,
    'empresa', v_row.empresa_nome,
    'data_inicio', v_row.data_inicio,
    'data_fim', v_row.data_fim,
    'signatario_nome', CASE
      WHEN v_row.colaborador_nome IS NULL THEN NULL
      ELSE regexp_replace(
        v_row.colaborador_nome,
        '(\S+)(\s+\S)?.*',
        '\1\2***'
      )
    END,
    'signatario_cpf_mascarado', CASE
      WHEN v_row.colaborador_cpf IS NULL THEN NULL
      ELSE '***.' || substr(regexp_replace(v_row.colaborador_cpf, '\D', '', 'g'), 4, 3)
           || '.' || substr(regexp_replace(v_row.colaborador_cpf, '\D', '', 'g'), 7, 3) || '-**'
    END
  );
END;
$$;


ALTER FUNCTION "public"."contrato_verificar_autenticidade"("p_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contrato_verificar_autenticidade_v2"("p_hash" "text", "p_ip" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_hash text;
  v_row record;
  v_ip text;
  v_count integer;
BEGIN
  IF p_hash IS NULL OR length(p_hash) < 32 THEN
    RETURN jsonb_build_object('valido', false, 'motivo', 'Hash inválido');
  END IF;

  v_ip := COALESCE(p_ip, 'unknown');

  SELECT COUNT(*) INTO v_count
  FROM public.ciencia_rate_limits
  WHERE identifier = 'verif_contrato:' || v_ip
    AND created_at > now() - interval '10 minutes';

  IF v_count >= 20 THEN
    RETURN jsonb_build_object(
      'valido', false,
      'motivo', 'Muitas tentativas. Aguarde 10 minutos e tente novamente.'
    );
  END IF;

  INSERT INTO public.ciencia_rate_limits (identifier, rpc_name, ip_address, success)
  VALUES ('verif_contrato:' || v_ip, 'contrato_verificar_autenticidade_v2', v_ip::inet, true);

  v_hash := lower(trim(p_hash));

  SELECT
    cg.id, cg.status, cg.assinado_em,
    cg.sha256 AS documento_hash,
    cg.data_inicio, cg.data_fim,
    e.razao_social AS empresa_nome,
    c.nome_completo AS colaborador_nome,
    c.cpf AS colaborador_cpf,
    t.assinatura_hash
  INTO v_row
  FROM public.contratos_gerados cg
  LEFT JOIN public.contrato_assinatura_tokens t ON t.contrato_id = cg.id AND t.usado_em IS NOT NULL
  LEFT JOIN public.empresas e ON e.id = cg.empresa_id
  LEFT JOIN public.colaboradores c ON c.id = cg.colaborador_id
  WHERE lower(cg.sha256) = v_hash
     OR lower(t.assinatura_hash) = v_hash
  ORDER BY cg.assinado_em DESC NULLS LAST
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('valido', false, 'motivo', 'Contrato não encontrado');
  END IF;

  RETURN jsonb_build_object(
    'valido', v_row.status = 'assinado' AND v_row.assinado_em IS NOT NULL,
    'status', v_row.status,
    'assinado_em', v_row.assinado_em,
    'documento_hash', v_row.documento_hash,
    'assinatura_hash', v_row.assinatura_hash,
    'empresa', v_row.empresa_nome,
    'data_inicio', v_row.data_inicio,
    'data_fim', v_row.data_fim,
    'signatario_nome', CASE
      WHEN v_row.colaborador_nome IS NULL THEN NULL
      ELSE regexp_replace(v_row.colaborador_nome, '(\S+)(\s+\S)?.*', '\1\2***')
    END,
    'signatario_cpf_mascarado', CASE
      WHEN v_row.colaborador_cpf IS NULL THEN NULL
      ELSE '***.' || substr(regexp_replace(v_row.colaborador_cpf, '\D', '', 'g'), 4, 3)
           || '.' || substr(regexp_replace(v_row.colaborador_cpf, '\D', '', 'g'), 7, 3) || '-**'
    END
  );
EXCEPTION WHEN OTHERS THEN
  -- Se falhar o insert do rate-limit (ex.: IP inválido), degrada com segurança
  RETURN jsonb_build_object('valido', false, 'motivo', 'Erro na verificação. Tente novamente.');
END;
$$;


ALTER FUNCTION "public"."contrato_verificar_autenticidade_v2"("p_hash" "text", "p_ip" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contratos_alertar_vencimentos"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  r RECORD;
  v_count INTEGER := 0;
BEGIN
  FOR r IN
    SELECT cg.id, cg.empresa_id, cg.data_fim, (cg.data_fim - CURRENT_DATE) AS dias,
           ct.tipo_contrato, ct.nome AS tnome
    FROM public.contratos_gerados cg
    JOIN public.contrato_templates ct ON ct.id = cg.template_id
    WHERE cg.data_fim IS NOT NULL
      AND cg.status IN ('gerado','enviado','assinado')
      AND (cg.data_fim - CURRENT_DATE) BETWEEN 0 AND 7
      AND (cg.alerta_vencimento_enviado_em IS NULL
           OR cg.alerta_vencimento_enviado_em < now() - interval '3 days')
  LOOP
    INSERT INTO public.notificacoes(empresa_id, user_id, tipo, titulo, mensagem, link, prioridade)
    SELECT r.empresa_id, ur.user_id, 'contrato_vencendo',
           'Contrato próximo ao vencimento',
           format('Contrato "%s" vence em %s dia(s) — %s. Prorrogue ou converta antes do prazo para evitar conversão automática em prazo indeterminado (CLT Art. 451).',
                  r.tnome, r.dias, to_char(r.data_fim,'DD/MM/YYYY')),
           format('/admissoes?contrato=%s', r.id),
           CASE WHEN r.dias <= 3 THEN 'alta' ELSE 'media' END
    FROM public.user_roles ur
    JOIN public.user_empresas ue ON ue.user_id = ur.user_id AND ue.empresa_id = r.empresa_id
    WHERE ur.role IN ('admin','rh');

    UPDATE public.contratos_gerados SET alerta_vencimento_enviado_em = now() WHERE id = r.id;
    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."contratos_alertar_vencimentos"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."contratos_enviar_lembretes_assinatura"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count int := 0;
  r record;
BEGIN
  FOR r IN
    SELECT t.id, t.empresa_id, t.expira_em, t.created_at, t.reminders_enviados,
           col.nome_completo
    FROM public.contrato_assinatura_tokens t
    JOIN public.contratos_gerados c ON c.id = t.contrato_id
    LEFT JOIN public.colaboradores col ON col.id = c.colaborador_id
    WHERE t.usado_em IS NULL
      AND t.expira_em > now()
      AND (
        (t.reminders_enviados = 0 AND t.created_at <= now() - interval '2 days')
        OR (t.reminders_enviados = 1 AND t.created_at <= now() - interval '5 days')
        OR (t.reminders_enviados <= 2 AND t.expira_em <= now() + interval '1 day')
      )
      AND (t.ultimo_reminder_at IS NULL OR t.ultimo_reminder_at <= now() - interval '12 hours')
  LOOP
    INSERT INTO public.notificacoes (user_id, empresa_id, tipo, titulo, mensagem, link, prioridade, created_at)
    SELECT DISTINCT
      ur.user_id,
      r.empresa_id,
      'contrato_assinatura_pendente',
      'Contrato aguardando assinatura',
      format('O contrato de %s está sem assinatura há %s dias. Expira em %s.',
             COALESCE(r.nome_completo, 'colaborador'),
             EXTRACT(DAY FROM (now() - r.created_at))::int,
             to_char(r.expira_em, 'DD/MM/YYYY HH24:MI')),
      '/configuracoes/contratos-templates',
      CASE WHEN r.expira_em <= now() + interval '1 day' THEN 'alta' ELSE 'media' END,
      now()
    FROM public.user_roles ur
    JOIN public.user_empresas ue ON ue.user_id = ur.user_id
    WHERE ue.empresa_id = r.empresa_id
      AND ur.role IN ('admin','rh');

    UPDATE public.contrato_assinatura_tokens
    SET reminders_enviados = reminders_enviados + 1,
        ultimo_reminder_at = now()
    WHERE id = r.id;

    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."contratos_enviar_lembretes_assinatura"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."criar_batida_da_divergencia_afdt"("_divergencia_id" "uuid", "_tipo" "text" DEFAULT 'entrada'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_div public.afdt_divergencias%ROWTYPE;
  v_batida_id uuid;
  v_next_ordem int;
BEGIN
  SELECT * INTO v_div FROM public.afdt_divergencias WHERE id = _divergencia_id;
  IF v_div.id IS NULL THEN RAISE EXCEPTION 'Divergência não encontrada'; END IF;
  IF v_div.tipo <> 'sem_batida' THEN RAISE EXCEPTION 'Apenas divergências sem_batida podem gerar batida'; END IF;
  IF v_div.colaborador_id IS NULL OR v_div.data_hora_afdt IS NULL THEN
    RAISE EXCEPTION 'Divergência incompleta (colaborador ou timestamp ausente)';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.user_empresas WHERE user_id = auth.uid() AND empresa_id = v_div.empresa_id) THEN
    RAISE EXCEPTION 'Sem permissão para esta empresa';
  END IF;

  SELECT COALESCE(MAX(ordem), 0) + 1 INTO v_next_ordem
    FROM public.batidas_ponto
   WHERE colaborador_id = v_div.colaborador_id
     AND data = (v_div.data_hora_afdt AT TIME ZONE 'America/Sao_Paulo')::date;

  INSERT INTO public.batidas_ponto (
    colaborador_id, empresa_id, data, hora, ordem, tipo, origem,
    ajustado, ajustado_por, motivo_ajuste
  ) VALUES (
    v_div.colaborador_id, v_div.empresa_id,
    (v_div.data_hora_afdt AT TIME ZONE 'America/Sao_Paulo')::date,
    (v_div.data_hora_afdt AT TIME ZONE 'America/Sao_Paulo')::time,
    v_next_ordem, _tipo, 'afdt_reconciliacao',
    true, auth.uid()::text, 'Criada a partir de AFDT (divergência ' || _divergencia_id || ')'
  ) RETURNING id INTO v_batida_id;

  UPDATE public.afdt_divergencias
     SET resolvido = true, batida_id = v_batida_id,
         observacao = COALESCE(observacao, '') || ' [batida criada: ' || v_batida_id || ']'
   WHERE id = _divergencia_id;

  INSERT INTO public.trilha_auditoria_ponto (empresa_id, colaborador_id, acao, detalhes, executado_por)
  VALUES (v_div.empresa_id, v_div.colaborador_id, 'batida_criada_via_afdt',
          jsonb_build_object('divergencia_id', _divergencia_id, 'batida_id', v_batida_id, 'tipo', _tipo),
          auth.uid());

  RETURN v_batida_id;
END; $$;


ALTER FUNCTION "public"."criar_batida_da_divergencia_afdt"("_divergencia_id" "uuid", "_tipo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."detectar_fraude_ponto"("_batida_id" "uuid", "_colaborador_id" "uuid", "_lat_nova" numeric, "_lng_nova" numeric, "_time_nova" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    ultima_lat NUMERIC;
    ultima_lng NUMERIC;
    ultima_time TIMESTAMP WITH TIME ZONE;
    distancia_metros NUMERIC;
    segundos_diff NUMERIC;
    velocidade_kmh NUMERIC;
BEGIN
    SELECT bp.latitude, bp.longitude, bp.created_at
      INTO ultima_lat, ultima_lng, ultima_time
    FROM public.batidas_ponto bp
    WHERE bp.colaborador_id = _colaborador_id
      AND bp.created_at > (_time_nova - INTERVAL '12 hours')
      AND bp.id <> _batida_id
    ORDER BY bp.created_at DESC
    LIMIT 1;

    IF FOUND AND ultima_lat IS NOT NULL AND _lat_nova IS NOT NULL THEN
        distancia_metros := sqrt(pow(_lat_nova - ultima_lat, 2) + pow(_lng_nova - ultima_lng, 2)) * 111320;
        segundos_diff := EXTRACT(EPOCH FROM (_time_nova - ultima_time));

        IF segundos_diff > 0 THEN
            velocidade_kmh := (distancia_metros / segundos_diff) * 3.6;

            IF velocidade_kmh > 1000 THEN
                INSERT INTO public.security_alerts (type, severity, details, user_id)
                VALUES (
                    'PONTO_VELOCIDADE_IMPOSSIVEL',
                    'high',
                    jsonb_build_object(
                        'velocidade_kmh', velocidade_kmh,
                        'distancia_m', distancia_metros,
                        'colaborador_id', _colaborador_id
                    ),
                    NULL
                );

                UPDATE public.batidas_ponto
                   SET anomalia_detectada = true
                 WHERE id = _batida_id;
            END IF;
        END IF;
    END IF;
END;
$$;


ALTER FUNCTION "public"."detectar_fraude_ponto"("_batida_id" "uuid", "_colaborador_id" "uuid", "_lat_nova" numeric, "_lng_nova" numeric, "_time_nova" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."distancia_haversine"("lat1" numeric, "lng1" numeric, "lat2" numeric, "lng2" numeric) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  r CONSTANT NUMERIC := 6371;
  dlat NUMERIC; dlng NUMERIC; a NUMERIC; c NUMERIC;
BEGIN
  IF lat1 IS NULL OR lng1 IS NULL OR lat2 IS NULL OR lng2 IS NULL THEN
    RETURN NULL;
  END IF;
  dlat := radians(lat2 - lat1);
  dlng := radians(lng2 - lng1);
  a := sin(dlat/2)^2 + cos(radians(lat1)) * cos(radians(lat2)) * sin(dlng/2)^2;
  c := 2 * atan2(sqrt(a), sqrt(1-a));
  RETURN round((r * c)::numeric, 2);
END;
$$;


ALTER FUNCTION "public"."distancia_haversine"("lat1" numeric, "lng1" numeric, "lat2" numeric, "lng2" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dp_assert_rls"("p_table" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relname = p_table AND c.relrowsecurity
  ) THEN
    RAISE EXCEPTION 'dp_assert_rls: RLS NAO HABILITADO em public.%', p_table;
  END IF;
END;
$$;


