CREATE OR REPLACE FUNCTION "public"."dp_track_pii_access"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE v_event TEXT; v_user_id UUID;
BEGIN
  v_event := left(TG_TABLE_NAME || '_' || lower(TG_OP), 150);
  BEGIN v_user_id := auth.uid(); EXCEPTION WHEN OTHERS THEN v_user_id := NULL; END;
  BEGIN
    INSERT INTO public.dp_audit_log(event,event_type,actor_user_id,request_id,payload)
    VALUES(v_event,'security',v_user_id,gen_random_uuid(),
      jsonb_build_object('table',TG_TABLE_NAME,'operation',TG_OP,'when',NOW()));
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'dp_track_pii_access: audit log falhou: % %', SQLSTATE, SQLERRM;
  END;
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END;
$$;


ALTER FUNCTION "public"."dp_track_pii_access"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."dp_track_pii_access"() IS 'Trigger de compensacao para auditoria PII enquanto pgaudit nao esta via dashboard.
Aplica em tabelas com dados sensiveis: CREATE TRIGGER dp_pii_audit AFTER INSERT OR UPDATE OR DELETE ON <tabela> FOR EACH ROW EXECUTE FUNCTION dp_track_pii_access();';



CREATE OR REPLACE FUNCTION "public"."eh_dia_valido_inicio_ferias"("p_empresa_id" "uuid", "p_data" "date") RETURNS TABLE("ok" boolean, "motivo" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_offset integer;
  v_dia date;
  v_dow integer;
  v_feriado record;
BEGIN
  IF p_data IS NULL THEN
    RETURN QUERY SELECT false, 'FERIAS_INICIO_INVALIDO: data de início não informada.'; RETURN;
  END IF;

  -- Regra: o próprio dia + 2 dias seguintes não podem ser feriado nem DSR (domingo)
  FOR v_offset IN 0..2 LOOP
    v_dia := p_data + v_offset;
    v_dow := EXTRACT(DOW FROM v_dia); -- 0 = domingo

    IF v_dow = 0 THEN
      IF v_offset = 0 THEN
        RETURN QUERY SELECT false, 'FERIAS_INICIO_INVALIDO: férias não podem iniciar em domingo (DSR).'; RETURN;
      ELSE
        RETURN QUERY SELECT false, format('FERIAS_INICIO_INVALIDO: início a %s dia(s) do DSR (domingo em %s). Art. 134 §3º CLT.', v_offset, to_char(v_dia,'DD/MM/YYYY')); RETURN;
      END IF;
    END IF;

    SELECT id, descricao INTO v_feriado
    FROM public.feriados
    WHERE data = v_dia
      AND (empresa_id IS NULL OR empresa_id = p_empresa_id)
    LIMIT 1;

    IF FOUND THEN
      IF v_offset = 0 THEN
        RETURN QUERY SELECT false, format('FERIAS_INICIO_INVALIDO: %s é feriado (%s).', to_char(v_dia,'DD/MM/YYYY'), v_feriado.descricao); RETURN;
      ELSE
        RETURN QUERY SELECT false, format('FERIAS_INICIO_INVALIDO: início a %s dia(s) do feriado %s (%s). Art. 134 §3º CLT.', v_offset, v_feriado.descricao, to_char(v_dia,'DD/MM/YYYY')); RETURN;
      END IF;
    END IF;
  END LOOP;

  RETURN QUERY SELECT true, NULL::text;
END;
$$;


ALTER FUNCTION "public"."eh_dia_valido_inicio_ferias"("p_empresa_id" "uuid", "p_data" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enfileirar_esocial_medida_disciplinar"("p_medida_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_medida record;
  v_colab record;
  v_evento_id uuid;
  v_tipo_evento text;
  v_dados jsonb;
  v_competencia text;
BEGIN
  SELECT * INTO v_medida FROM medidas_disciplinares WHERE id = p_medida_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'medida_nao_encontrada');
  END IF;

  -- Autorização por tenant
  IF v_medida.empresa_id IS NULL OR v_medida.empresa_id NOT IN (SELECT get_user_empresas(auth.uid())) THEN
    -- permitir trigger interna (auth.uid() null)
    IF auth.uid() IS NOT NULL THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'sem_permissao');
    END IF;
  END IF;

  SELECT id, nome, cpf, matricula, cargo, salario_base
    INTO v_colab
  FROM colaboradores WHERE id = v_medida.colaborador_id;

  v_competencia := to_char(coalesce(v_medida.data_ocorrencia, current_date), 'YYYY-MM');

  IF v_medida.tipo = 'justa_causa' THEN
    v_tipo_evento := 'S-2299';
    v_dados := jsonb_build_object(
      'medida_id', v_medida.id,
      'colaborador', jsonb_build_object(
        'id', v_colab.id, 'nome', v_colab.nome, 'cpf', v_colab.cpf, 'matricula', v_colab.matricula
      ),
      'desligamento', jsonb_build_object(
        'motivo', 'justa_causa',
        'artigo_clt', coalesce(v_medida.artigo_clt, '482'),
        'data', v_medida.data_ocorrencia,
        'descricao', v_medida.descricao_ocorrido
      ),
      'origem', 'medida_disciplinar'
    );
  ELSIF v_medida.tipo = 'suspensao' THEN
    v_tipo_evento := 'S-2206';
    v_dados := jsonb_build_object(
      'medida_id', v_medida.id,
      'colaborador', jsonb_build_object(
        'id', v_colab.id, 'nome', v_colab.nome, 'cpf', v_colab.cpf, 'matricula', v_colab.matricula
      ),
      'alteracao', jsonb_build_object(
        'motivo', 'suspensao_disciplinar',
        'artigo_clt', coalesce(v_medida.artigo_clt, '474'),
        'data_inicio', v_medida.data_ocorrencia,
        'dias', v_medida.dias_suspensao
      ),
      'origem', 'medida_disciplinar'
    );
  ELSE
    RETURN jsonb_build_object('ok', false, 'erro', 'tipo_nao_gera_esocial', 'tipo', v_medida.tipo);
  END IF;

  -- Idempotência: evita duplicidade para a mesma medida
  SELECT id INTO v_evento_id
  FROM esocial_eventos
  WHERE empresa_id = v_medida.empresa_id
    AND tipo_evento = v_tipo_evento
    AND (dados->>'medida_id')::uuid = v_medida.id
  LIMIT 1;

  IF v_evento_id IS NOT NULL THEN
    RETURN jsonb_build_object('ok', true, 'evento_id', v_evento_id, 'reused', true);
  END IF;

  INSERT INTO esocial_eventos (empresa_id, tipo_evento, dados, competencia, status)
  VALUES (v_medida.empresa_id, v_tipo_evento, v_dados, v_competencia, 'rascunho')
  RETURNING id INTO v_evento_id;

  RETURN jsonb_build_object('ok', true, 'evento_id', v_evento_id, 'tipo', v_tipo_evento);
END;
$$;


ALTER FUNCTION "public"."enfileirar_esocial_medida_disciplinar"("p_medida_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_afastamento_hash"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_canonical TEXT;
BEGIN
  IF NEW.status IN ('encerrado','cancelado') OR NEW.aprovado_em IS NOT NULL THEN
    v_canonical := COALESCE(NEW.colaborador_id::text,'')      || '|' ||
                   COALESCE(NEW.empresa_id::text,'')          || '|' ||
                   COALESCE(NEW.tipo::text,'')                || '|' ||
                   COALESCE(NEW.data_inicio::text,'')         || '|' ||
                   COALESCE(NEW.data_fim_prevista::text,'')   || '|' ||
                   COALESCE(NEW.data_fim_real::text,'')       || '|' ||
                   COALESCE(NEW.dias_empresa::text,'0')       || '|' ||
                   COALESCE(NEW.dias_inss::text,'0')          || '|' ||
                   COALESCE(NEW.cid::text,'')                 || '|' ||
                   COALESCE(NEW.numero_beneficio::text,'')    || '|' ||
                   COALESCE(NEW.medico_nome::text,'')         || '|' ||
                   COALESCE(NEW.medico_crm::text,'')          || '|' ||
                   COALESCE(NEW.atestado_numero::text,'')     || '|' ||
                   COALESCE(NEW.data_pericia::text,'')        || '|' ||
                   COALESCE(NEW.status::text,'');

    IF NEW.hash_integridade IS NULL OR NEW.hash_integridade = '' THEN
      NEW.hash_integridade := encode(digest(v_canonical,'sha256'),'hex');
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_afastamento_hash"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_aso_hash"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_canonical TEXT;
BEGIN
  -- ASO é considerado emitido quando possui médico + CRM + arquivo
  IF NEW.medico_nome IS NOT NULL
     AND NEW.medico_crm IS NOT NULL
     AND NEW.arquivo_url IS NOT NULL
     AND NEW.arquivo_url <> '' THEN

    v_canonical := COALESCE(NEW.colaborador_id::text,'')  || '|' ||
                   COALESCE(NEW.empresa_id::text,'')      || '|' ||
                   COALESCE(NEW.tipo,'')                  || '|' ||
                   COALESCE(NEW.data_exame::text,'')      || '|' ||
                   COALESCE(NEW.data_validade::text,'')   || '|' ||
                   COALESCE(NEW.resultado,'')             || '|' ||
                   COALESCE(NEW.medico_nome,'')           || '|' ||
                   COALESCE(NEW.medico_crm,'')            || '|' ||
                   COALESCE(NEW.clinica,'')               || '|' ||
                   COALESCE(NEW.arquivo_url,'');

    IF NEW.hash_integridade IS NULL OR NEW.hash_integridade = '' THEN
      NEW.hash_integridade := encode(digest(v_canonical,'sha256'),'hex');
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_aso_hash"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_batida_ponto_hash"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_canonical TEXT;
  v_expected TEXT;
BEGIN
  -- Canonicalização determinística (mesmo formato usado nas edge functions)
  v_canonical := COALESCE(NEW.colaborador_id::text, '') || '|' ||
                 COALESCE(NEW.data::text, '')          || '|' ||
                 COALESCE(NEW.hora::text, '')          || '|' ||
                 COALESCE(NEW.tipo, '')                || '|' ||
                 COALESCE(NEW.dispositivo_id, '');

  v_expected := encode(digest(v_canonical, 'sha256'), 'hex');

  -- Se cliente não enviou hash, preenchemos (compat legado)
  IF NEW.hash_integridade IS NULL OR NEW.hash_integridade = '' THEN
    NEW.hash_integridade := v_expected;
  END IF;

  RETURN NEW;
END;
$$;


