CREATE OR REPLACE FUNCTION "public"."fn_fila_dlq_check"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Ao falhar, incrementa tentativa e agenda backoff exponencial (2^n minutos, cap 60min)
  IF NEW.status = 'failed' AND OLD.status <> 'failed' THEN
    NEW.tentativas := COALESCE(OLD.tentativas, 0) + 1;
    NEW.ultimo_erro := COALESCE(NEW.erro_log, OLD.erro_log);

    IF NEW.tentativas >= NEW.max_tentativas THEN
      NEW.dlq := true;
      NEW.dlq_movido_em := now();
    ELSE
      -- Backoff exponencial: 2, 4, 8, 16, 32 minutos (cap 60)
      NEW.proxima_tentativa_em := now() + make_interval(mins => LEAST(power(2, NEW.tentativas)::int, 60));
      NEW.status := 'pending'; -- volta pra fila
    END IF;
  END IF;
  RETURN NEW;
END $$;


ALTER FUNCTION "public"."fn_fila_dlq_check"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_folha_optimistic_lock"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Se o cliente enviou uma versão explícita diferente da atual → CONFLITO
  IF NEW.version IS NOT NULL
     AND NEW.version <> OLD.version
     AND NEW.version <> OLD.version + 1 THEN

    -- Registra o conflito para observabilidade (best-effort)
    BEGIN
      INSERT INTO public.folha_lock_conflicts
        (folha_id, empresa_id, competencia, version_esperada, version_atual, user_id)
      VALUES
        (OLD.id, OLD.empresa_id, OLD.competencia::text, NEW.version, OLD.version, auth.uid());
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;

    RAISE EXCEPTION 'Conflito de concorrência em folha_pagamento (id=%): versão esperada %, versão atual %. Recarregue e tente novamente.',
      OLD.id, NEW.version, OLD.version
      USING ERRCODE = '40001'; -- serialization_failure → retry-friendly
  END IF;

  -- Auto-incremento da versão em qualquer UPDATE
  NEW.version := OLD.version + 1;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_folha_optimistic_lock"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_link_gov_br_account"("_user_id" "uuid", "_cpf" "text", "_nivel" "text") RETURNS "void"
