CREATE OR REPLACE FUNCTION "public"."fn_recalcular_dobra_e_alertas"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_updated integer;
BEGIN
  UPDATE public.periodos_aquisitivos
  SET data_limite_concessao = data_fim + INTERVAL '12 months',
      em_dobra = (CURRENT_DATE > (data_fim + INTERVAL '12 months') AND COALESCE(perdeu_direito,false) = false)
  WHERE (data_limite_concessao IS DISTINCT FROM (data_fim + INTERVAL '12 months')::date)
     OR (em_dobra IS DISTINCT FROM (CURRENT_DATE > (data_fim + INTERVAL '12 months') AND COALESCE(perdeu_direito,false) = false));
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated;
END;
$$;


ALTER FUNCTION "public"."fn_recalcular_dobra_e_alertas"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_start_workflow_on_colaborador_create"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_workflow_id uuid;
BEGIN
  -- Tenta criar execução de workflow para admissão (best-effort).
  -- Se tabela alvo/coluna não existir (banco em migração), ignora silenciosamente.
  BEGIN
    -- Verifica se workflows_execucoes existe
    IF NOT EXISTS (
      SELECT 1 FROM information_schema.tables
      WHERE table_schema = 'public' AND table_name = 'workflows_execucoes'
    ) THEN
      RETURN NEW;
    END IF;

    -- Tenta resolver workflow default; se não existir, pula silenciosamente
    BEGIN
      EXECUTE 'SELECT id FROM public.workflows_definitions WHERE categoria = ''admissao'' AND ativo = true LIMIT 1'
        INTO v_workflow_id;
    EXCEPTION WHEN OTHERS THEN
      v_workflow_id := NULL;
    END;

    IF v_workflow_id IS NULL THEN
      RETURN NEW;
    END IF;

    INSERT INTO public.workflows_execucoes (
      workflow_id, entidade_tipo, entidade_id, status, created_at, updated_at
    ) VALUES (
      v_workflow_id, 'colaborador', NEW.id, 'pendente', now(), now()
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING '[fn_start_workflow_on_colaborador_create] skipped: %', SQLERRM;
  END;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_start_workflow_on_colaborador_create"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_trigger_whatsapp_on_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Notificação WhatsApp na admissão (best-effort)
  -- Defensive: se a tabela/coluna alvo não existir, ignora silenciosamente
  BEGIN
    IF TG_TABLE_NAME = 'colaboradores' THEN
      IF EXISTS (
        SELECT 1 FROM information_schema.tables
        WHERE table_schema = 'public' AND table_name = 'whatsapp_mensagens_logs'
      ) THEN
        INSERT INTO public.whatsapp_mensagens_logs (
          empresa_id, colaborador_id, telefone, status
        ) VALUES (
          COALESCE(
            (NEW.empresa_id)::text,
            '00000000-0000-0000-0000-000000000000'
          )::uuid,
          NEW.id,
          COALESCE(
            current_setting('app.fake_phone', true),
            'pending'
          ),
          'pending_trigger'
        );
      END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    -- WhatsApp é um side-effect, nunca pode bloquear o INSERT
    RAISE WARNING '[fn_trigger_whatsapp_on_event] ignorado: %', SQLERRM;
  END;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_trigger_whatsapp_on_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_update_admissao_checklist"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF (NEW.status = 'aprovado' AND OLD.status != 'aprovado') THEN
        IF (NEW.tipo_documento = 'RG' OR NEW.tipo_documento = 'CPF') THEN
            UPDATE public.admissoes SET checklist_documentos_pessoais = true WHERE id = NEW.admissao_id;
        ELSIF (NEW.tipo_documento = 'COMPROVANTE_RESIDENCIA') THEN
            UPDATE public.admissoes SET checklist_comprovante_endereco = true WHERE id = NEW.admissao_id;
        ELSIF (NEW.tipo_documento = 'ASO') THEN
            UPDATE public.admissoes SET checklist_exame_admissional = true WHERE id = NEW.admissao_id;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


