CREATE OR REPLACE FUNCTION "public"."impedir_alteracao_afastamento_encerrado"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF OLD.status IN ('encerrado','cancelado') OR OLD.aprovado_em IS NOT NULL THEN
    IF NEW.status = OLD.status THEN
      IF NEW.colaborador_id     IS DISTINCT FROM OLD.colaborador_id
         OR NEW.empresa_id      IS DISTINCT FROM OLD.empresa_id
         OR NEW.tipo            IS DISTINCT FROM OLD.tipo
         OR NEW.data_inicio     IS DISTINCT FROM OLD.data_inicio
         OR NEW.data_fim_prevista IS DISTINCT FROM OLD.data_fim_prevista
         OR NEW.data_fim_real   IS DISTINCT FROM OLD.data_fim_real
         OR NEW.dias_empresa    IS DISTINCT FROM OLD.dias_empresa
         OR NEW.dias_inss       IS DISTINCT FROM OLD.dias_inss
         OR NEW.cid             IS DISTINCT FROM OLD.cid
         OR NEW.numero_beneficio IS DISTINCT FROM OLD.numero_beneficio
         OR NEW.medico_nome     IS DISTINCT FROM OLD.medico_nome
         OR NEW.medico_crm      IS DISTINCT FROM OLD.medico_crm
         OR NEW.atestado_numero IS DISTINCT FROM OLD.atestado_numero
         OR NEW.data_pericia    IS DISTINCT FROM OLD.data_pericia
         OR NEW.aprovado_em     IS DISTINCT FROM OLD.aprovado_em
         OR NEW.aprovado_por    IS DISTINCT FROM OLD.aprovado_por
         OR NEW.hash_integridade IS DISTINCT FROM OLD.hash_integridade THEN
        RAISE EXCEPTION 'Afastamento encerrado/aprovado é imutável (eSocial S-2230). Registre novo evento ou prorrogação oficial.'
          USING ERRCODE = 'check_violation';
      END IF;
    ELSE
      IF NEW.status NOT IN ('cancelado','encerrado') THEN
        RAISE EXCEPTION 'Transição de status inválida em afastamento encerrado/aprovado.'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."impedir_alteracao_afastamento_encerrado"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."impedir_alteracao_aso_emitido"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF OLD.arquivo_url IS NOT NULL AND OLD.arquivo_url <> ''
     AND OLD.medico_crm IS NOT NULL THEN
    IF NEW.colaborador_id  IS DISTINCT FROM OLD.colaborador_id
       OR NEW.empresa_id   IS DISTINCT FROM OLD.empresa_id
       OR NEW.tipo         IS DISTINCT FROM OLD.tipo
       OR NEW.data_exame   IS DISTINCT FROM OLD.data_exame
       OR NEW.resultado    IS DISTINCT FROM OLD.resultado
       OR NEW.medico_nome  IS DISTINCT FROM OLD.medico_nome
       OR NEW.medico_crm   IS DISTINCT FROM OLD.medico_crm
       OR NEW.clinica      IS DISTINCT FROM OLD.clinica
       OR NEW.arquivo_url  IS DISTINCT FROM OLD.arquivo_url
       OR NEW.hash_integridade IS DISTINCT FROM OLD.hash_integridade THEN
      RAISE EXCEPTION 'ASO emitido é imutável (NR-7/PCMSO). Emita um novo ASO retificador.'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."impedir_alteracao_aso_emitido"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."impedir_alteracao_batida_em_periodo_fechado"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row RECORD;
  v_fechado BOOLEAN := false;
BEGIN
  v_row := CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;

  SELECT EXISTS (
    SELECT 1 FROM public.periodos_ponto pp
    WHERE pp.status IN ('fechado','fechada','closed','homologado')
      AND v_row.data BETWEEN pp.data_inicio AND pp.data_fim
  ) INTO v_fechado;

  IF v_fechado THEN
    IF TG_OP = 'DELETE' THEN
      RAISE EXCEPTION 'Batida de ponto em período fechado não pode ser deletada (Portaria 671 MTP).'
        USING ERRCODE = 'check_violation';
    ELSE
      -- Só permitimos flags de conciliação/observação, jamais alterar essência da batida
      IF NEW.data           IS DISTINCT FROM OLD.data
         OR NEW.hora        IS DISTINCT FROM OLD.hora
         OR NEW.tipo        IS DISTINCT FROM OLD.tipo
         OR NEW.colaborador_id IS DISTINCT FROM OLD.colaborador_id
         OR NEW.dispositivo_id IS DISTINCT FROM OLD.dispositivo_id
         OR NEW.hash_integridade IS DISTINCT FROM OLD.hash_integridade THEN
        RAISE EXCEPTION 'Batida de ponto em período fechado é imutável. Use ajuste oficial com aprovação e trilha de auditoria.'
          USING ERRCODE = 'check_violation';
      END IF;
    END IF;
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


ALTER FUNCTION "public"."impedir_alteracao_batida_em_periodo_fechado"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."impedir_alteracao_cat_transmitida"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF (OLD.protocolo_esocial IS NOT NULL AND OLD.protocolo_esocial <> '')
     OR OLD.status_esocial IN ('enviado','processado','aceito','transmitido') THEN
    IF NEW.colaborador_id       IS DISTINCT FROM OLD.colaborador_id
       OR NEW.empresa_id        IS DISTINCT FROM OLD.empresa_id
       OR NEW.data_acidente     IS DISTINCT FROM OLD.data_acidente
       OR NEW.tipo_acidente     IS DISTINCT FROM OLD.tipo_acidente
       OR NEW.local_acidente    IS DISTINCT FROM OLD.local_acidente
       OR NEW.parte_corpo_atingida IS DISTINCT FROM OLD.parte_corpo_atingida
       OR NEW.agente_causador   IS DISTINCT FROM OLD.agente_causador
       OR NEW.houve_afastamento IS DISTINCT FROM OLD.houve_afastamento
       OR NEW.houve_obito       IS DISTINCT FROM OLD.houve_obito
       OR NEW.protocolo_esocial IS DISTINCT FROM OLD.protocolo_esocial
       OR NEW.hash_integridade  IS DISTINCT FROM OLD.hash_integridade THEN
      RAISE EXCEPTION 'CAT transmitida ao eSocial (S-2210) é imutável. Emita CAT de reabertura/retificação via evento oficial.'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."impedir_alteracao_cat_transmitida"() OWNER TO "postgres";


