CREATE OR REPLACE FUNCTION "public"."listar_auditoria"("p_empresa_id" "uuid", "p_tabela" "text" DEFAULT NULL::"text", "p_acao" "text" DEFAULT NULL::"text", "p_registro_id" "text" DEFAULT NULL::"text", "p_data_inicio" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_data_fim" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_limite" integer DEFAULT 200) RETURNS TABLE("id" "uuid", "tabela" "text", "registro_id" "text", "acao" "text", "user_id" "uuid", "payload" "jsonb", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.pertence_a_empresa(p_empresa_id) THEN
    RAISE EXCEPTION 'empresa fora do escopo do usuario';
  END IF;

  IF NOT (public.is_admin(auth.uid()) OR public.has_role(auth.uid(), 'rh'::app_role)) THEN
    RAISE EXCEPTION 'permissao insuficiente para consultar auditoria';
  END IF;

  RETURN QUERY
  SELECT a.id, a.entity, a.entity_id, a.action, a.user_id, a.payload, a.occurred_at
  FROM public.audit_log_unified a
  WHERE a.empresa_id = p_empresa_id
    AND (p_tabela IS NULL OR a.entity = p_tabela)
    AND (p_acao IS NULL OR a.action = p_acao)
    AND (p_registro_id IS NULL OR a.entity_id = p_registro_id)
    AND (p_data_inicio IS NULL OR a.occurred_at >= p_data_inicio)
    AND (p_data_fim IS NULL OR a.occurred_at <= p_data_fim)
  ORDER BY a.occurred_at DESC
  LIMIT greatest(1, least(coalesce(p_limite, 200), 1000));
END;
$$;


ALTER FUNCTION "public"."listar_auditoria"("p_empresa_id" "uuid", "p_tabela" "text", "p_acao" "text", "p_registro_id" "text", "p_data_inicio" timestamp with time zone, "p_data_fim" timestamp with time zone, "p_limite" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_audit_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  old_data JSONB;
  new_data JSONB;
  changed_fields TEXT[];
  current_user_id UUID;
  current_user_email TEXT;
BEGIN
  -- Get current user info
  current_user_id := auth.uid();
  current_user_email := (SELECT email FROM auth.users WHERE id = current_user_id);

  IF (TG_OP = 'DELETE') THEN
    old_data := to_jsonb(OLD);
    INSERT INTO public.audit_log (tabela, registro_id, acao, dados_anteriores, user_id, user_email)
    VALUES (TG_TABLE_NAME, OLD.id, 'DELETE', old_data, current_user_id, current_user_email);
    RETURN OLD;
    
  ELSIF (TG_OP = 'UPDATE') THEN
    old_data := to_jsonb(OLD);
    new_data := to_jsonb(NEW);
    
    -- Get changed fields
    SELECT array_agg(key) INTO changed_fields
    FROM (
      SELECT key FROM jsonb_each(old_data)
      EXCEPT
      SELECT key FROM jsonb_each(new_data)
      UNION
      SELECT key FROM jsonb_each(new_data)
      EXCEPT  
      SELECT key FROM jsonb_each(old_data)
      UNION
      SELECT o.key FROM jsonb_each(old_data) o
      JOIN jsonb_each(new_data) n ON o.key = n.key
      WHERE o.value IS DISTINCT FROM n.value
    ) changed;
    
    -- Only log if there are actual changes
    IF changed_fields IS NOT NULL AND array_length(changed_fields, 1) > 0 THEN
      INSERT INTO public.audit_log (tabela, registro_id, acao, dados_anteriores, dados_novos, campos_alterados, user_id, user_email)
      VALUES (TG_TABLE_NAME, NEW.id, 'UPDATE', old_data, new_data, changed_fields, current_user_id, current_user_email);
    END IF;
    RETURN NEW;
    
  ELSIF (TG_OP = 'INSERT') THEN
    new_data := to_jsonb(NEW);
    INSERT INTO public.audit_log (tabela, registro_id, acao, dados_novos, user_id, user_email)
    VALUES (TG_TABLE_NAME, NEW.id, 'INSERT', new_data, current_user_id, current_user_email);
    RETURN NEW;
  END IF;
  
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."log_audit_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_despesa_status_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.despesas_aprovacoes_log(despesa_id, usuario_id, acao, status_novo, empresa_id)
    VALUES (NEW.id, COALESCE(auth.uid(), NEW.colaborador_id), 'submetido', COALESCE(NEW.status,'pendente'), NEW.empresa_id);
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
    INSERT INTO public.despesas_aprovacoes_log(
      despesa_id, usuario_id, acao, status_anterior, status_novo, motivo, empresa_id
    )
    VALUES (
      NEW.id,
      COALESCE(auth.uid(), NEW.aprovado_por, NEW.colaborador_id),
      CASE NEW.status
        WHEN 'aprovado' THEN 'aprovado'
        WHEN 'rejeitado' THEN 'rejeitado'
        WHEN 'integrado_folha' THEN 'integrado_folha'
        WHEN 'pago' THEN 'pago'
        WHEN 'cancelado' THEN 'cancelado'
        ELSE 'editado'
      END,
      OLD.status, NEW.status,
      NEW.rejeitado_motivo,
      NEW.empresa_id
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."log_despesa_status_change"() OWNER TO "postgres";


