CREATE OR REPLACE FUNCTION "public"."maintenance_archive_old_audit"("_days" integer DEFAULT 180, "_batch" integer DEFAULT 5000) RETURNS TABLE("archived" bigint, "purged" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_cutoff TIMESTAMPTZ := now() - make_interval(days => _days);
  v_archived BIGINT := 0;
  v_purged BIGINT := 0;
  v_ids UUID[];
BEGIN
  LOOP
    SELECT array_agg(id) INTO v_ids
    FROM (
      SELECT id FROM public.audit_log_unified
      WHERE occurred_at < v_cutoff
      ORDER BY occurred_at ASC
      LIMIT _batch
    ) s;

    EXIT WHEN v_ids IS NULL OR array_length(v_ids, 1) = 0;

    -- Arquiva (ignora conflitos, idempotente)
    WITH moved AS (
      INSERT INTO public.audit_log_unified_archive
      SELECT * FROM public.audit_log_unified WHERE id = ANY(v_ids)
      ON CONFLICT (id) DO NOTHING
      RETURNING 1
    )
    SELECT count(*) INTO v_archived FROM moved;

    -- Purga da tabela quente (bypass do trigger append-only via SECURITY DEFINER + session_replication_role)
    PERFORM set_config('session_replication_role', 'replica', true);
    DELETE FROM public.audit_log_unified WHERE id = ANY(v_ids);
    GET DIAGNOSTICS v_purged = ROW_COUNT;
    PERFORM set_config('session_replication_role', 'origin', true);

    -- Commit implícito por iteração via COMMIT não é possível em plpgsql aqui;
    -- lote pequeno mantém transação curta.
  END LOOP;

  RETURN QUERY SELECT v_archived, v_purged;
END;
$$;


ALTER FUNCTION "public"."maintenance_archive_old_audit"("_days" integer, "_batch" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maintenance_weekly_analyze"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
DECLARE
  tables text[] := ARRAY[
    'registros_ponto',
    'batidas_ponto',
    'folhas_pagamento',
    'folha_itens',
    'colaboradores',
    'audit_log_unified',
    'notificacoes',
    'esocial_eventos'
  ];
  t text;
BEGIN
  FOREACH t IN ARRAY tables LOOP
    IF EXISTS (
      SELECT 1 FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public' AND c.relname = t AND c.relkind = 'r'
    ) THEN
      EXECUTE format('ANALYZE public.%I', t);
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."maintenance_weekly_analyze"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."medida_aprovar"("_medida_id" "uuid", "_observacao" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_medida record; v_uid uuid := auth.uid(); v_prox text; v_requer_juridico boolean;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'não autenticado'; END IF;
  SELECT * INTO v_medida FROM public.medidas_disciplinares WHERE id = _medida_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'medida não encontrada'; END IF;
  IF NOT public.user_belongs_to_empresa(v_uid, v_medida.empresa_id) THEN
    RAISE EXCEPTION 'acesso negado';
  END IF;
  v_requer_juridico := v_medida.tipo IN ('suspensao','justa_causa')
                    OR v_medida.gravidade IN ('grave','gravissima');
  IF v_medida.status_workflow = 'aguardando_gestor' THEN
    v_prox := 'aguardando_rh';
    UPDATE public.medidas_disciplinares
       SET status_workflow = v_prox, aprovado_gestor_por = v_uid,
           aprovado_gestor_em = now(), updated_at = now()
     WHERE id = _medida_id;
  ELSIF v_medida.status_workflow = 'aguardando_rh' THEN
    v_prox := CASE WHEN v_requer_juridico THEN 'aguardando_juridico' ELSE 'aplicada' END;
    UPDATE public.medidas_disciplinares
       SET status_workflow = v_prox, aprovado_rh_por = v_uid, aprovado_rh_em = now(),
           data_aprovacao = COALESCE(data_aprovacao, now()),
           aprovador_id = COALESCE(aprovador_id, v_uid), updated_at = now()
     WHERE id = _medida_id;
  ELSIF v_medida.status_workflow = 'aguardando_juridico' THEN
    v_prox := 'aplicada';
    UPDATE public.medidas_disciplinares
       SET status_workflow = v_prox, aprovado_juridico_por = v_uid,
           aprovado_juridico_em = now(), updated_at = now()
     WHERE id = _medida_id;
  ELSE
    RAISE EXCEPTION 'status atual não permite aprovação (%)', v_medida.status_workflow;
  END IF;
  INSERT INTO public.medidas_disciplinares_workflow_log
    (medida_id, empresa_id, de_status, para_status, acao, ator_id, observacao)
    VALUES (_medida_id, v_medida.empresa_id, v_medida.status_workflow, v_prox, 'aprovar', v_uid, _observacao);
  RETURN jsonb_build_object('ok', true, 'status', v_prox);
END; $$;


ALTER FUNCTION "public"."medida_aprovar"("_medida_id" "uuid", "_observacao" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."medida_arquivar"("_medida_id" "uuid", "_observacao" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_medida record; v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'não autenticado'; END IF;
  SELECT * INTO v_medida FROM public.medidas_disciplinares WHERE id = _medida_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'medida não encontrada'; END IF;
  IF NOT public.user_belongs_to_empresa(v_uid, v_medida.empresa_id) THEN
    RAISE EXCEPTION 'acesso negado';
  END IF;
  IF v_medida.status_workflow NOT IN ('aplicada','rejeitada') THEN
    RAISE EXCEPTION 'só é possível arquivar medidas aplicadas ou rejeitadas';
  END IF;
  UPDATE public.medidas_disciplinares
     SET status_workflow = 'arquivada', arquivado_por = v_uid,
