CREATE OR REPLACE FUNCTION "public"."medida_gerar_link_ciencia"("p_medida_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_medida RECORD;
  v_token TEXT;
  v_id UUID;
BEGIN
  IF NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'rh')) THEN
    RAISE EXCEPTION 'Sem permissão para gerar link de ciência';
  END IF;

  SELECT id, empresa_id, colaborador_id, status_workflow
  INTO v_medida
  FROM public.medidas_disciplinares
  WHERE id = p_medida_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Medida não encontrada';
  END IF;

  IF v_medida.empresa_id NOT IN (SELECT empresa_id FROM public.user_empresas WHERE user_id = auth.uid()) THEN
    RAISE EXCEPTION 'Acesso negado à empresa';
  END IF;

  IF v_medida.status_workflow NOT IN ('aplicada','aprovada_rh','aprovada_juridico') THEN
    RAISE EXCEPTION 'Medida deve estar aplicada/aprovada para gerar ciência';
  END IF;

  v_token := encode(gen_random_bytes(32), 'hex');

  INSERT INTO public.medidas_ciencia_tokens (medida_id, empresa_id, colaborador_id, token, created_by)
  VALUES (v_medida.id, v_medida.empresa_id, v_medida.colaborador_id, v_token, auth.uid())
  RETURNING id INTO v_id;

  RETURN jsonb_build_object(
    'success', true,
    'token', v_token,
    'token_id', v_id,
    'expires_at', now() + interval '7 days',
    'url_path', '/ciencia-medida/' || v_token
  );
END; $$;


ALTER FUNCTION "public"."medida_gerar_link_ciencia"("p_medida_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."medida_registrar_ciencia_publica"("p_token" "text", "p_acao" "text", "p_motivo_recusa" "text" DEFAULT NULL::"text", "p_ip" "text" DEFAULT NULL::"text", "p_user_agent" "text" DEFAULT NULL::"text", "p_geo" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tok RECORD;
  v_hash TEXT;
BEGIN
  IF p_acao NOT IN ('ciencia','recusa') THEN
    RAISE EXCEPTION 'Ação inválida';
  END IF;

  SELECT * INTO v_tok FROM public.medidas_ciencia_tokens
  WHERE token = p_token AND used_at IS NULL AND expires_at > now()
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Token inválido ou expirado');
  END IF;

  IF p_acao = 'recusa' AND (p_motivo_recusa IS NULL OR length(trim(p_motivo_recusa)) < 10) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Motivo de recusa obrigatório (mín. 10 caracteres)');
  END IF;

  v_hash := encode(digest(
    v_tok.token || '|' || p_acao || '|' || coalesce(p_motivo_recusa,'') || '|' || now()::text || '|' || coalesce(p_ip,''),
    'sha256'
  ), 'hex');

  UPDATE public.medidas_ciencia_tokens
  SET used_at = now(),
      acao = p_acao,
      motivo_recusa = p_motivo_recusa,
      ip_address = p_ip,
      user_agent = p_user_agent,
      geolocation = p_geo,
      assinatura_hash = v_hash
  WHERE id = v_tok.id;

  UPDATE public.medidas_disciplinares
  SET colaborador_ciente = (p_acao = 'ciencia'),
      recusa_assinatura = (p_acao = 'recusa'),
      motivo_recusa = CASE WHEN p_acao = 'recusa' THEN p_motivo_recusa ELSE motivo_recusa END,
      data_ciencia = now(),
      assinado_em = CASE WHEN p_acao = 'ciencia' THEN now() ELSE assinado_em END,
      updated_at = now()
  WHERE id = v_tok.medida_id;

  INSERT INTO public.medidas_disciplinares_workflow_log
    (medida_id, empresa_id, acao, executado_por, detalhes)
  VALUES (
    v_tok.medida_id, v_tok.empresa_id,
    'ciencia_' || p_acao,
    NULL,
    jsonb_build_object('token_id', v_tok.id, 'ip', p_ip, 'user_agent', p_user_agent,
                       'hash', v_hash, 'motivo_recusa', p_motivo_recusa)
  );

  INSERT INTO public.notificacoes (user_id, empresa_id, titulo, mensagem, tipo, link)
  SELECT ue.user_id, v_tok.empresa_id,
         CASE WHEN p_acao='ciencia' THEN 'Ciência registrada' ELSE 'Recusa de assinatura registrada' END,
         'Colaborador ' || p_acao || ' via ciência digital.',
         CASE WHEN p_acao='ciencia' THEN 'info' ELSE 'warning' END,
         '/medidas-disciplinares?id=' || v_tok.medida_id
  FROM public.user_empresas ue
  JOIN public.user_roles ur ON ur.user_id = ue.user_id
  WHERE ue.empresa_id = v_tok.empresa_id AND ur.role IN ('admin','rh');

  RETURN jsonb_build_object('success', true, 'acao', p_acao, 'hash', v_hash, 'registrado_em', now());
END; $$;


ALTER FUNCTION "public"."medida_registrar_ciencia_publica"("p_token" "text", "p_acao" "text", "p_motivo_recusa" "text", "p_ip" "text", "p_user_agent" "text", "p_geo" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."medida_rejeitar"("_medida_id" "uuid", "_motivo" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_medida record; v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'não autenticado'; END IF;
  IF _motivo IS NULL OR length(trim(_motivo)) < 5 THEN
    RAISE EXCEPTION 'motivo da rejeição obrigatório (mín. 5 caracteres)';
  END IF;
  SELECT * INTO v_medida FROM public.medidas_disciplinares WHERE id = _medida_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'medida não encontrada'; END IF;
  IF NOT public.user_belongs_to_empresa(v_uid, v_medida.empresa_id) THEN
    RAISE EXCEPTION 'acesso negado';
  END IF;
  IF v_medida.status_workflow NOT IN ('aguardando_gestor','aguardando_rh','aguardando_juridico') THEN
    RAISE EXCEPTION 'só é possível rejeitar medidas em fluxo de aprovação';
  END IF;
  UPDATE public.medidas_disciplinares
     SET status_workflow = 'rejeitada', rejeitado_por = v_uid,
         rejeitado_em = now(), motivo_rejeicao = _motivo, updated_at = now()
   WHERE id = _medida_id;
  INSERT INTO public.medidas_disciplinares_workflow_log
    (medida_id, empresa_id, de_status, para_status, acao, ator_id, observacao)
    VALUES (_medida_id, v_medida.empresa_id, v_medida.status_workflow, 'rejeitada', 'rejeitar', v_uid, _motivo);
  RETURN jsonb_build_object('ok', true, 'status', 'rejeitada');
END; $$;


ALTER FUNCTION "public"."medida_rejeitar"("_medida_id" "uuid", "_motivo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."medida_responder_contestacao"("_medida_id" "uuid", "_resposta" "text", "_aceita" boolean) RETURNS "public"."medidas_disciplinares"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.medidas_disciplinares;
  v_user uuid := auth.uid();
  v_is_admin boolean;
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF _resposta IS NULL OR length(btrim(_resposta)) < 10 THEN
    RAISE EXCEPTION 'resposta_minimo_10_chars';
  END IF;

  SELECT * INTO v_row FROM public.medidas_disciplinares WHERE id = _medida_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'medida_nao_encontrada'; END IF;

  SELECT EXISTS(
    SELECT 1 FROM public.user_roles ur
    JOIN public.user_empresas ue ON ue.user_id = ur.user_id AND ue.empresa_id = v_row.empresa_id
    WHERE ur.user_id = v_user AND ur.role IN ('admin','rh')
  ) INTO v_is_admin;

  IF NOT v_is_admin THEN
    RAISE EXCEPTION 'apenas_rh_ou_admin_pode_responder';
  END IF;

  IF v_row.status_workflow <> 'contestada' THEN
    RAISE EXCEPTION 'medida_nao_esta_contestada';
  END IF;

  UPDATE public.medidas_disciplinares SET
    contestacao_resposta = _resposta,
    contestacao_respondida_em = now(),
    contestacao_respondida_por = v_user,
    contestacao_aceita = _aceita,
    status_workflow = CASE WHEN _aceita THEN 'arquivada' ELSE 'aplicada' END
  WHERE id = _medida_id
  RETURNING * INTO v_row;

  INSERT INTO public.medidas_disciplinares_workflow_log(medida_id, empresa_id, actor_user_id, from_status, to_status, acao, observacao)
  VALUES (_medida_id, v_row.empresa_id, v_user, 'contestada', v_row.status_workflow,
    CASE WHEN _aceita THEN 'contestacao_aceita' ELSE 'contestacao_rejeitada' END,
    left(_resposta, 500));

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."medida_responder_contestacao"("_medida_id" "uuid", "_resposta" "text", "_aceita" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."medida_verificar_ciencia_hash"("p_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_result JSONB;
BEGIN
  IF NOT public.check_ciencia_rate_limit('medida_verificar_ciencia_hash', left(p_hash, 12)) THEN
    RAISE EXCEPTION 'rate_limit_exceeded'
      USING HINT = 'Muitas tentativas. Aguarde 10 minutos.';
  END IF;

  SELECT jsonb_build_object(
    'valid', true,
    'medida_id', md.id,
    'tipo', md.tipo,
    'data_ocorrencia', md.data_ocorrencia,
    'empresa_nome', e.nome_fantasia,
    'acao', mct.acao,
    'data_ciencia', mct.used_at,
    'ip_mascarado', host(set_masklen(mct.ip_address::CIDR, 24))
  ) INTO v_result
  FROM public.medidas_ciencia_tokens mct
  JOIN public.medidas_disciplinares md ON md.id = mct.medida_id
  JOIN public.empresas e ON e.id = md.empresa_id
  WHERE mct.hash_comprovante = p_hash
    AND mct.used_at IS NOT NULL;

  IF v_result IS NULL THEN
    RETURN jsonb_build_object('valid', false, 'reason', 'hash_not_found');
  END IF;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."medida_verificar_ciencia_hash"("p_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."medidas_analytics_reincidencia"("p_empresa_id" "uuid", "p_data_inicio" "date", "p_data_fim" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_result JSONB;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  IF NOT (public.has_role(v_uid, 'admin'::app_role) OR public.has_role(v_uid, 'rh'::app_role)) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  IF p_empresa_id IS NULL OR p_data_inicio IS NULL OR p_data_fim IS NULL THEN
    RAISE EXCEPTION 'invalid_arguments';
  END IF;

  WITH base AS (
    SELECT
      m.id,
      m.tipo,
      m.gravidade,
      m.data_ocorrencia::date AS data_ocorrencia,
      m.colaborador_id,
      c.nome_completo,
      COALESCE(NULLIF(TRIM(c.departamento), ''), 'Sem setor') AS setor,
      c.gestor_ferias_id,
      g.nome_completo AS gestor_nome
    FROM public.medidas_disciplinares m
    JOIN public.colaboradores c ON c.id = m.colaborador_id
    LEFT JOIN public.colaboradores g ON g.id = c.gestor_ferias_id
    WHERE m.empresa_id = p_empresa_id
      AND m.data_ocorrencia::date BETWEEN p_data_inicio AND p_data_fim
  ),
  por_colaborador AS (
    SELECT
      colaborador_id,
      nome_completo,
      setor,
      gestor_nome,
      COUNT(*)::int AS total,
      COUNT(*) FILTER (WHERE tipo = 'advertencia_verbal')::int  AS advertencia_verbal,
      COUNT(*) FILTER (WHERE tipo = 'advertencia_escrita')::int AS advertencia_escrita,
      COUNT(*) FILTER (WHERE tipo = 'suspensao')::int           AS suspensao,
      COUNT(*) FILTER (WHERE tipo = 'justa_causa')::int         AS justa_causa,
      COUNT(*) FILTER (WHERE gravidade = 'grave')::int          AS graves,
      MAX(data_ocorrencia)                                       AS ultima_ocorrencia,
      (COUNT(*) > 1)                                             AS reincidente
    FROM base
    GROUP BY colaborador_id, nome_completo, setor, gestor_nome
  ),
  por_setor AS (
    SELECT
      setor,
      COUNT(*)::int AS total,
      COUNT(DISTINCT colaborador_id)::int AS colaboradores_envolvidos,
      COUNT(DISTINCT colaborador_id) FILTER (
        WHERE colaborador_id IN (SELECT colaborador_id FROM por_colaborador WHERE reincidente)
      )::int AS reincidentes,
      COUNT(*) FILTER (WHERE tipo = 'suspensao')::int   AS suspensoes,
      COUNT(*) FILTER (WHERE tipo = 'justa_causa')::int AS justas_causas
    FROM base
    GROUP BY setor
  ),
  por_gestor AS (
    SELECT
      COALESCE(gestor_nome, 'Sem gestor') AS gestor_nome,
      COUNT(*)::int AS total,
      COUNT(DISTINCT colaborador_id)::int AS colaboradores_envolvidos,
      COUNT(DISTINCT colaborador_id) FILTER (
        WHERE colaborador_id IN (SELECT colaborador_id FROM por_colaborador WHERE reincidente)
      )::int AS reincidentes,
      COUNT(*) FILTER (WHERE tipo = 'suspensao')::int   AS suspensoes,
      COUNT(*) FILTER (WHERE tipo = 'justa_causa')::int AS justas_causas
    FROM base
    GROUP BY COALESCE(gestor_nome, 'Sem gestor')
  ),
  heatmap AS (
    SELECT
      to_char(date_trunc('month', data_ocorrencia), 'YYYY-MM') AS mes,
      tipo,
      COUNT(*)::int AS total
    FROM base
    GROUP BY 1, 2
  ),
  resumo AS (
    SELECT
      COUNT(*)::int                                                             AS total_medidas,
      COUNT(DISTINCT colaborador_id)::int                                       AS colaboradores_envolvidos,
      (SELECT COUNT(*) FROM por_colaborador WHERE reincidente)::int             AS colaboradores_reincidentes,
      COUNT(*) FILTER (WHERE tipo = 'suspensao')::int                           AS total_suspensoes,
      COUNT(*) FILTER (WHERE tipo = 'justa_causa')::int                         AS total_justas_causas
    FROM base
  )
  SELECT jsonb_build_object(
    'periodo',           jsonb_build_object('inicio', p_data_inicio, 'fim', p_data_fim),
    'resumo',            COALESCE((SELECT to_jsonb(r) FROM resumo r), '{}'::jsonb),
    'por_colaborador',   COALESCE((SELECT jsonb_agg(pc ORDER BY pc.total DESC, pc.nome_completo)
                                    FROM (SELECT * FROM por_colaborador) pc), '[]'::jsonb),
    'por_setor',         COALESCE((SELECT jsonb_agg(ps ORDER BY ps.total DESC)
                                    FROM (SELECT * FROM por_setor) ps), '[]'::jsonb),
    'por_gestor',        COALESCE((SELECT jsonb_agg(pg ORDER BY pg.total DESC)
                                    FROM (SELECT * FROM por_gestor) pg), '[]'::jsonb),
    'heatmap',           COALESCE((SELECT jsonb_agg(h ORDER BY h.mes, h.tipo)
                                    FROM (SELECT * FROM heatmap) h), '[]'::jsonb)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


