CREATE OR REPLACE FUNCTION "public"."notificar_divergencias_afdt"("_importacao_id" "uuid") RETURNS TABLE("notificacoes_criadas" integer, "criticas" integer, "avisos" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_empresa uuid;
  v_criticas int;
  v_avisos int;
  v_total int;
  v_inseridas int := 0;
BEGIN
  -- Resolve empresa da importação
  SELECT empresa_id INTO v_empresa
  FROM public.afdt_importacoes
  WHERE id = _importacao_id;

  IF v_empresa IS NULL THEN
    RAISE EXCEPTION 'Importação AFDT não encontrada: %', _importacao_id;
  END IF;

  -- Autorização: apenas admins ou membros da empresa
  IF NOT (
    public.has_role(auth.uid(), 'admin'::app_role)
    OR EXISTS (SELECT 1 FROM public.user_empresas WHERE user_id = auth.uid() AND empresa_id = v_empresa)
  ) THEN
    RAISE EXCEPTION 'Sem permissão para notificar divergências desta empresa';
  END IF;

  -- Contagem de divergências pendentes por severidade
  SELECT
    COUNT(*) FILTER (WHERE tipo = 'sem_colaborador'),
    COUNT(*) FILTER (WHERE tipo IN ('sem_batida','duplicado')),
    COUNT(*)
  INTO v_criticas, v_avisos, v_total
  FROM public.afdt_divergencias
  WHERE importacao_id = _importacao_id AND resolvido = false;

  IF v_total = 0 THEN
    RETURN QUERY SELECT 0, 0, 0;
    RETURN;
  END IF;

  -- Insere 1 notificação por membro da empresa (idempotente via entidade_id)
  WITH destinatarios AS (
    SELECT DISTINCT ue.user_id
    FROM public.user_empresas ue
    WHERE ue.empresa_id = v_empresa
  ),
  inseridas AS (
    INSERT INTO public.notificacoes (
      user_id, empresa_id, titulo, mensagem, tipo, lida,
      entidade_id, entidade_tipo
    )
    SELECT
      d.user_id,
      v_empresa,
      CASE WHEN v_criticas > 0
        THEN format('AFDT: %s divergência(s) crítica(s)', v_criticas)
        ELSE format('AFDT: %s divergência(s) para revisar', v_total)
      END,
      format(
        'Importação AFDT concluída com %s divergências (%s críticas, %s avisos). Acesse /admin/ponto/divergencias.',
        v_total, v_criticas, v_avisos
      ),
      CASE WHEN v_criticas > 0 THEN 'alerta' ELSE 'info' END,
      false,
      _importacao_id,
      'afdt_importacao'
    FROM destinatarios d
    WHERE NOT EXISTS (
      SELECT 1 FROM public.notificacoes n
      WHERE n.user_id = d.user_id
        AND n.entidade_tipo = 'afdt_importacao'
        AND n.entidade_id = _importacao_id
    )
    RETURNING 1
  )
  SELECT COUNT(*)::int INTO v_inseridas FROM inseridas;

  RETURN QUERY SELECT v_inseridas, v_criticas, v_avisos;
END;
$$;


ALTER FUNCTION "public"."notificar_divergencias_afdt"("_importacao_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notificar_ferias_pagamento_d5"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_alerta RECORD;
  v_user RECORD;
  v_count INT := 0;
  v_titulo TEXT;
  v_msg TEXT;
BEGIN
  FOR v_alerta IN
    SELECT id, empresa_id, colaborador_id, data_inicio, dias_ate_inicio, severidade
      FROM public.v_ferias_alerta_pagamento_d2
     WHERE severidade IN ('atencao','critico','violacao_grave')
  LOOP
    v_titulo := CASE v_alerta.severidade
      WHEN 'violacao_grave' THEN '🚨 Férias iniciada SEM pagamento (Art. 145 CLT)'
      WHEN 'critico'        THEN '⚠️ Pagamento de férias vence em ≤2 dias (Art. 145)'
      ELSE                       'ℹ️ Pagamento de férias vence em ≤5 dias'
    END;
    v_msg := format(
      'Colaborador %s — início %s (em %s dia(s)). Confirme o pagamento no painel de Férias.',
      v_alerta.colaborador_id, to_char(v_alerta.data_inicio, 'DD/MM/YYYY'), v_alerta.dias_ate_inicio
    );

    FOR v_user IN
      SELECT DISTINCT ur.user_id
        FROM public.user_roles ur
        JOIN public.user_empresas ue ON ue.user_id = ur.user_id
       WHERE ue.empresa_id = v_alerta.empresa_id
         AND ur.role::text IN ('admin','rh')
    LOOP
      INSERT INTO public.notificacoes (
        user_id, empresa_id, tipo, titulo, mensagem,
        entidade_tipo, entidade_id, data_referencia, lida
      ) VALUES (
        v_user.user_id, v_alerta.empresa_id, 'ferias_pagamento_d5',
        v_titulo, v_msg, 'ferias', v_alerta.id, CURRENT_DATE, false
      )
      ON CONFLICT DO NOTHING;
      v_count := v_count + 1;
    END LOOP;
  END LOOP;

  INSERT INTO public.logs_sistema (nivel, mensagem, contexto)
  VALUES ('info', format('Notificações Art.145 geradas: %s', v_count),
          jsonb_build_object('job','ferias_d5','executed_at', now(), 'count', v_count));

  RETURN v_count;
EXCEPTION WHEN OTHERS THEN
  INSERT INTO public.logs_sistema (nivel, mensagem, contexto)
  VALUES ('error', SQLERRM, jsonb_build_object('job','ferias_d5','sqlstate', SQLSTATE));
  RAISE;
END;
$$;


ALTER FUNCTION "public"."notificar_ferias_pagamento_d5"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notificar_ferias_reconciliacao_sla_baixo"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_threshold NUMERIC := 80;
  v_empresa RECORD;
  v_sla_ontem NUMERIC;
  v_sla_anteontem NUMERIC;
  v_total_ontem INT;
  v_total_anteontem INT;
  v_alertados INT := 0;
  v_empresas_afetadas INT := 0;
  v_hoje DATE := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  v_ontem DATE := v_hoje - 1;
  v_anteontem DATE := v_hoje - 2;
BEGIN
  FOR v_empresa IN
    SELECT DISTINCT empresa_id
    FROM public.ferias_reconciliacao_logs
    WHERE empresa_id IS NOT NULL
      AND executado_em >= (v_anteontem::timestamp AT TIME ZONE 'America/Sao_Paulo')
      AND executado_em <  ((v_hoje)::timestamp AT TIME ZONE 'America/Sao_Paulo')
  LOOP
    SELECT
      COUNT(*),
      ROUND(100.0 * COUNT(*) FILTER (WHERE restantes = 0) / NULLIF(COUNT(*),0), 2)
      INTO v_total_ontem, v_sla_ontem
    FROM public.ferias_reconciliacao_logs
    WHERE empresa_id = v_empresa.empresa_id
      AND (executado_em AT TIME ZONE 'America/Sao_Paulo')::date = v_ontem;

    SELECT
      COUNT(*),
      ROUND(100.0 * COUNT(*) FILTER (WHERE restantes = 0) / NULLIF(COUNT(*),0), 2)
      INTO v_total_anteontem, v_sla_anteontem
    FROM public.ferias_reconciliacao_logs
    WHERE empresa_id = v_empresa.empresa_id
      AND (executado_em AT TIME ZONE 'America/Sao_Paulo')::date = v_anteontem;

    IF COALESCE(v_total_ontem,0) = 0 OR COALESCE(v_total_anteontem,0) = 0 THEN
      CONTINUE;
    END IF;

    IF v_sla_ontem >= v_threshold OR v_sla_anteontem >= v_threshold THEN
      CONTINUE;
    END IF;

    v_empresas_afetadas := v_empresas_afetadas + 1;

    INSERT INTO public.notificacoes (user_id, empresa_id, tipo, titulo, mensagem, entidade_tipo, lida, data_referencia)
    SELECT
      ue.user_id,
      v_empresa.empresa_id,
      'sla_reconciliacao_ferias',
      'SLA de reconciliação de férias abaixo do alvo (2 dias)',
      format('SLA %s%% (ontem) e %s%% (anteontem) — alvo ≥ %s%%. Verifique o cron reconciliar_ferias_folha_batch.',
             v_sla_ontem, v_sla_anteontem, v_threshold),
      'ferias_reconciliacao',
      false,
      v_hoje
    FROM public.user_empresas ue
    JOIN public.user_roles ur ON ur.user_id = ue.user_id
    WHERE ue.empresa_id = v_empresa.empresa_id
      AND ur.role IN ('admin','rh')
      AND NOT EXISTS (
        SELECT 1 FROM public.notificacoes n
        WHERE n.user_id = ue.user_id
          AND n.tipo = 'sla_reconciliacao_ferias'
          AND n.data_referencia = v_hoje
      );

    GET DIAGNOSTICS v_alertados = ROW_COUNT;
  END LOOP;

  RETURN jsonb_build_object(
    'executado_em', now(),
    'empresas_afetadas', v_empresas_afetadas,
    'notificacoes_enviadas', v_alertados,
    'threshold', v_threshold
  );
END;
$$;


ALTER FUNCTION "public"."notificar_ferias_reconciliacao_sla_baixo"() OWNER TO "postgres";


