    "salario_base" numeric DEFAULT 0 NOT NULL,
    "saldo_salario" numeric DEFAULT 0,
    "aviso_previo" numeric DEFAULT 0,
    "ferias_vencidas" numeric DEFAULT 0,
    "ferias_proporcionais" numeric DEFAULT 0,
    "terco_constitucional" numeric DEFAULT 0,
    "decimo_terceiro" numeric DEFAULT 0,
    "multa_fgts" numeric DEFAULT 0,
    "total_proventos" numeric DEFAULT 0,
    "total_descontos" numeric DEFAULT 0,
    "valor_liquido" numeric DEFAULT 0,
    "checklist_comunicacao" boolean DEFAULT false,
    "checklist_documentacao" boolean DEFAULT false,
    "checklist_calculo_rescisao" boolean DEFAULT false,
    "checklist_homologacao" boolean DEFAULT false,
    "checklist_revogacao_acessos" boolean DEFAULT false,
    "checklist_devolucao_equipamentos" boolean DEFAULT false,
    "checklist_esocial" boolean DEFAULT false,
    "checklist_pagamento" boolean DEFAULT false,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "empresa_id" "uuid",
    "tipo_desligamento_id" integer,
    "tipo_aviso_previo_id" integer,
    "data_aviso_previo" "text",
    "quebra_contrato" boolean DEFAULT false,
    "remover_beneficios" boolean DEFAULT false,
    "data_remocao_acesso" "text",
    "novo_supervisor_id" "uuid",
    "etapa" "text" DEFAULT 'iniciado'::"text",
    "data_contabilidade" "text",
    "hash_integridade" "text",
    "assinado_empresa" boolean DEFAULT false,
    "assinado_colaborador" boolean DEFAULT false,
    "hash_assinatura_empresa" "text",
    "hash_assinatura_colaborador" "text",
    "data_assinatura_empresa" timestamp with time zone,
    "data_assinatura_colaborador" timestamp with time zone,
    "data_pagamento" timestamp with time zone,
    "comprovante_pagamento_url" "text",
    CONSTRAINT "chk_desligamentos_etapa" CHECK ((("etapa" IS NULL) OR ("etapa" = ANY (ARRAY['iniciado'::"text", 'comunicacao'::"text", 'documentacao'::"text", 'calculo_rescisao'::"text", 'pagamento'::"text", 'homologacao'::"text", 'esocial'::"text", 'devolucao_equipamentos'::"text", 'revogacao_acessos'::"text", 'concluido'::"text"])))),
    CONSTRAINT "chk_desligamentos_status" CHECK ((("status" IS NULL) OR ("status" = ANY (ARRAY['rascunho'::"text", 'pendente'::"text", 'em_andamento'::"text", 'aguardando_aprovacao'::"text", 'aprovado'::"text", 'rejeitado'::"text", 'calculado'::"text", 'em_homologacao'::"text", 'homologado'::"text", 'pago'::"text", 'concluido'::"text", 'finalizado'::"text", 'cancelado'::"text"]))))
);


ALTER TABLE "public"."desligamentos" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pagar_desligamento"("_desligamento_id" "uuid", "_comprovante_url" "text" DEFAULT NULL::"text") RETURNS "public"."desligamentos"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.desligamentos%ROWTYPE;
BEGIN
  IF NOT public.is_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Apenas administradores podem registrar pagamento de rescisao' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_row FROM public.desligamentos WHERE id = _desligamento_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Desligamento nao encontrado' USING ERRCODE = 'P0002';
  END IF;
  IF v_row.status IS DISTINCT FROM 'homologado' THEN
    RAISE EXCEPTION 'Rescisao so pode ser paga apos homologacao (status atual: %)', v_row.status
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT COALESCE(v_row.assinado_empresa, false) OR NOT COALESCE(v_row.assinado_colaborador, false) THEN
    RAISE EXCEPTION 'Rescisao precisa da assinatura da empresa e do colaborador antes do pagamento'
      USING ERRCODE = 'check_violation';
  END IF;

  UPDATE public.desligamentos
  SET status = 'pago', etapa = 'concluido', checklist_pagamento = true,
      data_pagamento = now(), comprovante_pagamento_url = _comprovante_url
  WHERE id = _desligamento_id
  RETURNING * INTO v_row;

  INSERT INTO public.audit_log (tabela, registro_id, acao, user_id, dados_novos)
  VALUES ('desligamentos', _desligamento_id, 'UPDATE', auth.uid(),
          jsonb_build_object('action','pagar_desligamento','comprovante_url',_comprovante_url));

  RETURN v_row;
END;
$$;


