CREATE OR REPLACE FUNCTION "public"."process_audit_log"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    IF (TG_OP = 'DELETE') THEN
        INSERT INTO public.auditoria_logs(entidade, entidade_id, acao, dados_anteriores, user_id)
        VALUES (TG_TABLE_NAME, OLD.id::text, TG_OP, to_jsonb(OLD), auth.uid());
        RETURN OLD;
    ELSIF (TG_OP = 'UPDATE') THEN
        INSERT INTO public.auditoria_logs(entidade, entidade_id, acao, dados_anteriores, dados_novos, user_id)
        VALUES (TG_TABLE_NAME, NEW.id::text, TG_OP, to_jsonb(OLD), to_jsonb(NEW), auth.uid());
        RETURN NEW;
    ELSIF (TG_OP = 'INSERT') THEN
        INSERT INTO public.auditoria_logs(entidade, entidade_id, acao, dados_novos, user_id)
        VALUES (TG_TABLE_NAME, NEW.id::text, TG_OP, to_jsonb(NEW), auth.uid());
        RETURN NEW;
    END IF;
    RETURN NULL;
END; $$;


ALTER FUNCTION "public"."process_audit_log"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_ferias_audit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_empresa_id UUID;
    v_acao TEXT;
BEGIN
    IF (TG_OP = 'DELETE') THEN
        v_empresa_id := OLD.empresa_id;
        v_acao := 'DELETE';
    ELSE
        v_empresa_id := NEW.empresa_id;
        IF (TG_OP = 'INSERT') THEN
            v_acao := 'CREATE';
        ELSE
            v_acao := 'UPDATE';
            -- Detecção específica de aprovação
            IF (TG_TABLE_NAME = 'ferias_solicitacoes') THEN
                IF (OLD.status_gestor <> NEW.status_gestor AND NEW.status_gestor = 'aprovado') THEN
                    v_acao := 'APPROVE_GESTOR';
                ELSIF (OLD.status_rh <> NEW.status_rh AND NEW.status_rh = 'aprovado') THEN
                    v_acao := 'APPROVE_RH';
                ELSIF (OLD.status <> NEW.status AND NEW.status = 'rejeitado') THEN
                    v_acao := 'REJECT';
                END IF;
            END IF;
        END IF;
    END IF;

    INSERT INTO public.ferias_audit_log (
        empresa_id, 
        usuario_id, 
        entidade_tipo, 
        entidade_id, 
        acao, 
        dados_anteriores, 
        dados_novos
    )
    VALUES (
        v_empresa_id,
        auth.uid(),
        TG_TABLE_NAME,
        CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END,
        v_acao,
        CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE to_jsonb(OLD) END,
        CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE to_jsonb(NEW) END
    );
    
    RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."process_ferias_audit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_lgpd_cleanup_queue"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_processed integer := 0;
BEGIN
  -- Marca como processado o que passou do prazo de retenção
  UPDATE public.lgpd_fila_limpeza
     SET status = 'processado', processado_em = now()
   WHERE status = 'pendente'
     AND data_prevista_limpeza <= now();
  GET DIAGNOSTICS v_processed = ROW_COUNT;
  RETURN v_processed;
END $$;


ALTER FUNCTION "public"."process_lgpd_cleanup_queue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."processar_ajuste_aprovado"("p_solicitacao_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_solicitacao RECORD;
BEGIN
    -- 1. Get request data
    SELECT * INTO v_solicitacao FROM public.solicitacoes_ajuste_ponto WHERE id = p_solicitacao_id;
    
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Solicitação não encontrada';
    END IF;

    IF v_solicitacao.status != 'aprovado' THEN
        RAISE EXCEPTION 'Apenas solicitações aprovadas podem ser processadas';
    END IF;

    -- 2. Insert corrected clock-in/out record
    INSERT INTO public.batidas_ponto (
        colaborador_id,
        empresa_id,
        data,
        hora,
        tipo,
        origem,
        ajustada,
        motivo_ajuste,
        hash_integridade
    ) VALUES (
        v_solicitacao.colaborador_id,
        v_solicitacao.empresa_id,
        v_solicitacao.data_ponto,
        v_solicitacao.hora_sugerida,
        v_solicitacao.tipo_ponto,
        'ajuste_manual',
        true,
        v_solicitacao.motivo,
        encode(digest(v_solicitacao.id::text || now()::text, 'sha256'), 'hex')
    );
END;
$$;


ALTER FUNCTION "public"."processar_ajuste_aprovado"("p_solicitacao_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."processar_auditoria_premiacao"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_user_id UUID;
BEGIN
    -- Try to get current user ID (might be null in some contexts)
    BEGIN
        v_user_id := auth.uid();
    EXCEPTION WHEN OTHERS THEN
        v_user_id := NULL;
    END;

    INSERT INTO public.premiacoes_auditoria (
        entidade_tipo,
        entidade_id,
        usuario_id,
        acao,
        dados_anteriores,
        dados_novos,
        created_at
    ) VALUES (
        TG_TABLE_NAME,
        COALESCE(NEW.id, OLD.id),
        v_user_id,
        TG_OP,
        CASE WHEN TG_OP = 'UPDATE' THEN to_jsonb(OLD) ELSE NULL END,
        to_jsonb(NEW),
        now()
    );
    RETURN NEW;
END;
$$;


