CREATE OR REPLACE FUNCTION "public"."reconciliar_afdt"("_importacao_id" "uuid", "_janela_seg" integer DEFAULT 300) RETURNS TABLE("total" integer, "ok" integer, "sem_colaborador" integer, "sem_batida" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_empresa UUID;
  v_total INT := 0; v_ok INT := 0; v_sc INT := 0; v_sb INT := 0;
BEGIN
  SELECT empresa_id INTO v_empresa FROM public.afdt_importacoes WHERE id = _importacao_id;
  IF v_empresa IS NULL THEN
    RAISE EXCEPTION 'Importação não encontrada';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.user_empresas WHERE user_id = auth.uid() AND empresa_id = v_empresa) THEN
    RAISE EXCEPTION 'Sem permissão nesta empresa';
  END IF;

  DELETE FROM public.afdt_divergencias WHERE importacao_id = _importacao_id;

  WITH raw AS (
    SELECT r.id AS raw_id, r.pis, r.data_hora_marcacao
      FROM public.afdt_registros_raw r
     WHERE r.importacao_id = _importacao_id
       AND r.tipo_registro = '3'
       AND r.data_hora_marcacao IS NOT NULL
       AND r.pis IS NOT NULL
  ),
  matched AS (
    SELECT
      raw.raw_id,
      raw.pis,
      raw.data_hora_marcacao,
      c.id AS colaborador_id,
      b.id AS batida_id,
      CASE WHEN b.id IS NOT NULL THEN
        EXTRACT(EPOCH FROM (raw.data_hora_marcacao - ((b.data::timestamp + b.hora))))::int
      END AS delta
    FROM raw
    LEFT JOIN public.colaboradores c
      ON c.empresa_id = v_empresa AND regexp_replace(coalesce(c.pis_pasep,''), '\D', '', 'g') = raw.pis
    LEFT JOIN LATERAL (
      SELECT bp.id, bp.data, bp.hora
        FROM public.batidas_ponto bp
       WHERE bp.empresa_id = v_empresa
         AND bp.colaborador_id = c.id
         AND (bp.data::timestamp + bp.hora)
             BETWEEN raw.data_hora_marcacao - make_interval(secs => _janela_seg)
                 AND raw.data_hora_marcacao + make_interval(secs => _janela_seg)
       ORDER BY abs(extract(epoch from ((bp.data::timestamp + bp.hora) - raw.data_hora_marcacao)))
       LIMIT 1
    ) b ON c.id IS NOT NULL
  ),
  ins AS (
    INSERT INTO public.afdt_divergencias
      (importacao_id, empresa_id, registro_raw_id, colaborador_id, batida_id, pis, data_hora_afdt, tipo, delta_segundos)
    SELECT
      _importacao_id, v_empresa, m.raw_id, m.colaborador_id, m.batida_id, m.pis, m.data_hora_marcacao,
      CASE
        WHEN m.colaborador_id IS NULL THEN 'sem_colaborador'
        WHEN m.batida_id      IS NULL THEN 'sem_batida'
        ELSE 'ok'
      END,
      m.delta
    FROM matched m
    RETURNING tipo
  )
  SELECT
    count(*)::int,
    count(*) FILTER (WHERE tipo = 'ok')::int,
    count(*) FILTER (WHERE tipo = 'sem_colaborador')::int,
    count(*) FILTER (WHERE tipo = 'sem_batida')::int
  INTO v_total, v_ok, v_sc, v_sb
  FROM ins;

  RETURN QUERY SELECT v_total, v_ok, v_sc, v_sb;
END;
$$;


ALTER FUNCTION "public"."reconciliar_afdt"("_importacao_id" "uuid", "_janela_seg" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."ferias_reconciliacao_logs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "executado_em" timestamp with time zone DEFAULT "now"() NOT NULL,
    "verificadas" integer DEFAULT 0 NOT NULL,
    "corrigidas" integer DEFAULT 0 NOT NULL,
    "restantes" integer DEFAULT 0 NOT NULL,
    "duracao_ms" integer DEFAULT 0 NOT NULL,
    "detalhes" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "empresa_id" "uuid"
);


ALTER TABLE "public"."ferias_reconciliacao_logs" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reconciliar_ferias_folha_batch"() RETURNS SETOF "public"."ferias_reconciliacao_logs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_started    timestamptz;
  v_verificadas int;
  v_corrigidas  int;
  v_restantes   int;
  v_emp record;
  v_row record;
  v_log public.ferias_reconciliacao_logs;
BEGIN
  FOR v_emp IN
    SELECT DISTINCT c.empresa_id
    FROM public.v_ferias_folha_reconciliacao v
    JOIN public.colaboradores c ON c.id = v.colaborador_id
    WHERE v.situacao = 'divergente' AND c.empresa_id IS NOT NULL
  LOOP
    v_started := clock_timestamp();
    v_verificadas := 0;
    v_corrigidas  := 0;

    FOR v_row IN
      SELECT v.ferias_id
      FROM public.v_ferias_folha_reconciliacao v
      JOIN public.colaboradores c ON c.id = v.colaborador_id
      WHERE v.situacao = 'divergente' AND c.empresa_id = v_emp.empresa_id
      LIMIT 500
    LOOP
      v_verificadas := v_verificadas + 1;
      BEGIN
        PERFORM public.gerar_rubricas_ferias(v_row.ferias_id);
        v_corrigidas := v_corrigidas + 1;
      EXCEPTION WHEN OTHERS THEN
        NULL;
      END;
    END LOOP;

    SELECT COUNT(*) INTO v_restantes
    FROM public.v_ferias_folha_reconciliacao v
    JOIN public.colaboradores c ON c.id = v.colaborador_id
    WHERE v.situacao = 'divergente' AND c.empresa_id = v_emp.empresa_id;

    INSERT INTO public.ferias_reconciliacao_logs (
      empresa_id, verificadas, corrigidas, restantes, duracao_ms
    ) VALUES (
      v_emp.empresa_id, v_verificadas, v_corrigidas, v_restantes,
      (EXTRACT(EPOCH FROM (clock_timestamp() - v_started)) * 1000)::int
    ) RETURNING * INTO v_log;

    RETURN NEXT v_log;
  END LOOP;

  RETURN;
END;
$$;


ALTER FUNCTION "public"."reconciliar_ferias_folha_batch"() OWNER TO "postgres";


