CREATE OR REPLACE FUNCTION "public"."record_failed_login"("p_identifier" "text", "p_identifier_type" "text" DEFAULT 'email'::"text") RETURNS TABLE("attempts" integer, "is_locked" boolean, "lockout_minutes" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_attempts integer;
  v_locked boolean := false;
  v_lock_min integer := 0;
BEGIN
  INSERT INTO public.login_lockouts (identifier, identifier_type, attempts, last_attempt)
  VALUES (lower(p_identifier), p_identifier_type, 1, now())
  ON CONFLICT (identifier, identifier_type) DO UPDATE
    SET attempts = public.login_lockouts.attempts + 1,
        last_attempt = now(),
        updated_at = now()
  RETURNING public.login_lockouts.attempts INTO v_attempts;

  IF v_attempts >= 5 THEN
    v_locked := true;
    v_lock_min := CASE
      WHEN v_attempts >= 10 THEN 60
      WHEN v_attempts >= 7 THEN 15
      ELSE 5
    END;
    UPDATE public.login_lockouts
       SET is_locked = true,
           lockout_until = now() + make_interval(mins => v_lock_min),
           updated_at = now()
     WHERE identifier = lower(p_identifier)
       AND identifier_type = p_identifier_type;
  END IF;

  RETURN QUERY SELECT v_attempts, v_locked, v_lock_min;
END;
$$;


ALTER FUNCTION "public"."record_failed_login"("p_identifier" "text", "p_identifier_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_pii_access"("p_empresa_id" "uuid", "p_tabela" "text", "p_acao" "text" DEFAULT 'select'::"text", "p_registro_id" "text" DEFAULT NULL::"text", "p_registro_count" integer DEFAULT 1) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_uid uuid := auth.uid();
  v_id uuid;
  v_headers jsonb := '{}'::jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED' USING ERRCODE = '42501';
  END IF;
  IF p_empresa_id IS NULL OR NOT public.user_belongs_to_empresa(v_uid, p_empresa_id) THEN
    RAISE EXCEPTION 'TENANT_FORBIDDEN' USING ERRCODE = '42501';
  END IF;
  IF p_tabela IS NULL OR p_tabela !~ '^[a-z][a-z0-9_]{0,62}$' THEN
    RAISE EXCEPTION 'INVALID_TABLE' USING ERRCODE = '22023';
  END IF;
  IF p_acao IS NULL OR p_acao NOT IN ('select', 'export', 'print', 'download') THEN
    RAISE EXCEPTION 'INVALID_ACTION' USING ERRCODE = '22023';
  END IF;
  IF p_registro_count IS NULL OR p_registro_count NOT BETWEEN 1 AND 100000 THEN
    RAISE EXCEPTION 'INVALID_COUNT' USING ERRCODE = '22023';
  END IF;
  IF p_registro_id IS NOT NULL AND length(p_registro_id) > 256 THEN
    RAISE EXCEPTION 'INVALID_RECORD_ID' USING ERRCODE = '22023';
  END IF;

  BEGIN
    v_headers := COALESCE(NULLIF(current_setting('request.headers', true), '')::jsonb, '{}'::jsonb);
  EXCEPTION WHEN invalid_text_representation THEN
    v_headers := '{}'::jsonb;
  END;

  INSERT INTO public.pii_access_logs (
    user_id, empresa_id, tabela, acao, registro_id, registro_count, ip, user_agent
  ) VALUES (
    v_uid, p_empresa_id, p_tabela, p_acao, p_registro_id, p_registro_count,
    left(split_part(COALESCE(v_headers->>'x-forwarded-for', ''), ',', 1), 64),
    left(COALESCE(v_headers->>'user-agent', ''), 1024)
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$_$;


ALTER FUNCTION "public"."record_pii_access"("p_empresa_id" "uuid", "p_tabela" "text", "p_acao" "text", "p_registro_id" "text", "p_registro_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_dashboard_mvs"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  t_start timestamptz := clock_timestamp();
  ok_count int := 0;
  errors jsonb := '[]'::jsonb;
BEGIN
  IF NOT pg_try_advisory_lock(hashtext('refresh_dashboard_mvs')) THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'already_running');
  END IF;

  BEGIN
    REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_status_change_daily;
    ok_count := ok_count + 1;
  EXCEPTION WHEN OTHERS THEN
    errors := errors || jsonb_build_object('mv','mv_status_change_daily','error',SQLERRM);
  END;

  BEGIN
    REFRESH MATERIALIZED VIEW CONCURRENTLY public.mv_anomalies_hourly;
    ok_count := ok_count + 1;
  EXCEPTION WHEN OTHERS THEN
    errors := errors || jsonb_build_object('mv','mv_anomalies_hourly','error',SQLERRM);
  END;

  PERFORM pg_advisory_unlock(hashtext('refresh_dashboard_mvs'));

  RETURN jsonb_build_object(
    'refreshed', ok_count,
    'errors', errors,
    'elapsed_ms', extract(millisecond FROM clock_timestamp() - t_start)
  );
END;
$$;


ALTER FUNCTION "public"."refresh_dashboard_mvs"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."registrar_auditoria"("p_tabela" "text", "p_registro_id" "text", "p_acao" "text", "p_dados_anteriores" "jsonb" DEFAULT NULL::"jsonb", "p_dados_novos" "jsonb" DEFAULT NULL::"jsonb", "p_empresa_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_id  uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'nao autenticado';
  END IF;

  IF p_tabela IS NULL OR length(btrim(p_tabela)) = 0 OR length(p_tabela) > 128 THEN
    RAISE EXCEPTION 'tabela invalida';
  END IF;

  IF p_acao IS NULL OR p_acao NOT IN ('INSERT','UPDATE','DELETE','VISUALIZACAO','EXPORT') THEN
    RAISE EXCEPTION 'acao invalida: %', p_acao;
  END IF;

  -- Escopo de tenant: a empresa informada precisa pertencer ao usuario.
  IF p_empresa_id IS NOT NULL AND NOT public.pertence_a_empresa(p_empresa_id) THEN
    RAISE EXCEPTION 'empresa fora do escopo do usuario';
  END IF;

  INSERT INTO public.audit_log_unified (
    source_table, empresa_id, user_id, action, entity, entity_id, payload, occurred_at
  ) VALUES (
    'app', p_empresa_id, v_uid, p_acao, p_tabela, left(coalesce(p_registro_id,''), 128),
    jsonb_build_object('anteriores', p_dados_anteriores, 'novos', p_dados_novos),
    now()
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."registrar_auditoria"("p_tabela" "text", "p_registro_id" "text", "p_acao" "text", "p_dados_anteriores" "jsonb", "p_dados_novos" "jsonb", "p_empresa_id" "uuid") OWNER TO "postgres";


