CREATE OR REPLACE FUNCTION "public"."registrar_comunicado_ferias_coletivas"("_coletiva_id" "uuid", "_mte_path" "text", "_mte_hash" "text", "_sindicato_path" "text", "_sindicato_hash" "text", "_sindicato_nome" "text") RETURNS "public"."ferias_coletivas"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.ferias_coletivas;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Autenticação obrigatória' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_row FROM public.ferias_coletivas WHERE id = _coletiva_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Férias coletivas não encontradas' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.user_belongs_to_empresa(auth.uid(), v_row.empresa_id) THEN
    RAISE EXCEPTION 'Sem acesso a essa empresa' USING ERRCODE = '42501';
  END IF;

  IF NOT (public.has_role(auth.uid(), 'admin'::app_role)
       OR public.has_role(auth.uid(), 'rh'::app_role)) THEN
    RAISE EXCEPTION 'Apenas RH ou Admin podem gerar comunicados' USING ERRCODE = '42501';
  END IF;

  UPDATE public.ferias_coletivas SET
    comunicado_mte_path       = _mte_path,
    comunicado_mte_hash       = _mte_hash,
    comunicado_sindicato_path = _sindicato_path,
    comunicado_sindicato_hash = _sindicato_hash,
    comunicado_sindicato_nome = _sindicato_nome,
    comunicado_gerado_em      = now(),
    comunicado_gerado_por     = auth.uid(),
    updated_at                = now()
  WHERE id = _coletiva_id
  RETURNING * INTO v_row;

  INSERT INTO public.audit_log_unified (
    empresa_id, entity, entity_id, action, actor_id, metadata
  ) VALUES (
    v_row.empresa_id, 'ferias_coletivas', v_row.id, 'comunicado_gerado', auth.uid(),
    jsonb_build_object('mte_hash', _mte_hash, 'sindicato_hash', _sindicato_hash, 'sindicato_nome', _sindicato_nome)
  );

  RETURN v_row;
END $$;


ALTER FUNCTION "public"."registrar_comunicado_ferias_coletivas"("_coletiva_id" "uuid", "_mte_path" "text", "_mte_hash" "text", "_sindicato_path" "text", "_sindicato_hash" "text", "_sindicato_nome" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."registrar_pagamento_ferias"("p_ferias_id" "uuid", "p_valor" numeric, "p_comprovante_path" "text" DEFAULT NULL::"text") RETURNS "public"."ferias"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.ferias;
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'AUTH_REQUIRED' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_row FROM public.ferias WHERE id = p_ferias_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'FERIAS_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  -- Isolamento multi-tenant + role
  IF NOT public.user_belongs_to_empresa(v_uid, v_row.empresa_id)
     OR NOT (public.has_role(v_uid,'admin') OR public.has_role(v_uid,'rh')) THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501';
  END IF;

  IF v_row.pagamento_confirmado_em IS NOT NULL THEN
    RAISE EXCEPTION 'PAGAMENTO_JA_CONFIRMADO' USING ERRCODE = '23505';
  END IF;

  IF p_valor IS NULL OR p_valor <= 0 THEN
    RAISE EXCEPTION 'VALOR_INVALIDO' USING ERRCODE = '22023';
  END IF;

  UPDATE public.ferias
     SET pagamento_confirmado_em  = now(),
         pagamento_confirmado_por = v_uid,
         pagamento_valor          = p_valor,
         pagamento_comprovante_path = p_comprovante_path,
         data_pagamento           = COALESCE(data_pagamento, CURRENT_DATE)
   WHERE id = p_ferias_id
   RETURNING * INTO v_row;

  -- Auditoria unificada (best-effort)
  BEGIN
    INSERT INTO public.audit_log_unified (empresa_id, user_id, action, entity_type, entity_id, metadata)
    VALUES (v_row.empresa_id, v_uid, 'FERIAS_PAGAMENTO_CONFIRMADO', 'ferias', v_row.id,
      jsonb_build_object('valor', p_valor, 'data_inicio', v_row.data_inicio,
                         'dias_antecedencia', (v_row.data_inicio - CURRENT_DATE)));
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."registrar_pagamento_ferias"("p_ferias_id" "uuid", "p_valor" numeric, "p_comprovante_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rejeitar_despesa"("_despesa_id" "uuid", "_motivo" "text") RETURNS "public"."despesas"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _row public.despesas;
BEGIN
  IF _motivo IS NULL OR length(trim(_motivo)) < 3 THEN
    RAISE EXCEPTION 'Motivo da rejeição é obrigatório';
  END IF;

  UPDATE public.despesas
    SET status = 'rejeitado',
        aprovado_por = auth.uid(),
        aprovado_em = now(),
        rejeitado_motivo = _motivo,
        updated_at = now()
    WHERE id = _despesa_id
      AND status = 'pendente'
      AND empresa_id IN (SELECT get_user_empresas(auth.uid()))
    RETURNING * INTO _row;

  IF _row.id IS NULL THEN
    RAISE EXCEPTION 'Despesa não encontrada ou não pode ser rejeitada';
  END IF;
  RETURN _row;
END;
$$;


