    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "type" "text" NOT NULL,
    "severity" "text" DEFAULT 'medium'::"text" NOT NULL,
    "ip_address" "text",
    "user_id" "uuid",
    "details" "jsonb",
    "resolved" boolean DEFAULT false,
    "resolved_by" "uuid",
    "resolved_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"()
);


ALTER TABLE "public"."security_alerts" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_security_alert"("_alert_id" "uuid", "_note" "text" DEFAULT NULL::"text") RETURNS "public"."security_alerts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _uid uuid := auth.uid();
  _row public.security_alerts;
BEGIN
  IF _uid IS NULL OR NOT public.is_admin(_uid) THEN
    RAISE EXCEPTION 'Apenas administradores podem resolver alertas'
      USING ERRCODE = '42501';
  END IF;

  UPDATE public.security_alerts
  SET resolved = true,
      resolved_by = _uid,
      resolved_at = now(),
      details = COALESCE(details, '{}'::jsonb)
                || jsonb_build_object('resolution_note', _note,
                                      'resolved_by_uid', _uid)
  WHERE id = _alert_id
    AND COALESCE(resolved, false) = false
  RETURNING * INTO _row;

  IF _row.id IS NULL THEN
    RAISE EXCEPTION 'Alerta não encontrado ou já resolvido'
      USING ERRCODE = 'no_data_found';
  END IF;

  -- Trilha de auditoria da resolução
  INSERT INTO public.audit_log (tabela, registro_id, acao, user_id, dados_novos)
  VALUES ('security_alerts', _alert_id, 'RESOLVE_ALERT', _uid,
          jsonb_build_object('type', _row.type, 'severity', _row.severity,
                             'note', _note, 'at', now()));

  RETURN _row;
END;
$$;


ALTER FUNCTION "public"."resolve_security_alert"("_alert_id" "uuid", "_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolver_divergencia_afdt"("_divergencia_id" "uuid", "_observacao" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_empresa uuid;
BEGIN
  SELECT empresa_id INTO v_empresa FROM public.afdt_divergencias WHERE id = _divergencia_id;
  IF v_empresa IS NULL THEN
    RAISE EXCEPTION 'Divergência não encontrada';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.user_empresas WHERE user_id = auth.uid() AND empresa_id = v_empresa) THEN
    RAISE EXCEPTION 'Sem permissão para esta empresa';
  END IF;

  UPDATE public.afdt_divergencias
     SET resolvido = true,
         observacao = COALESCE(_observacao, observacao)
   WHERE id = _divergencia_id;

  INSERT INTO public.trilha_auditoria_ponto (empresa_id, colaborador_id, acao, detalhes, executado_por)
  SELECT empresa_id, colaborador_id, 'divergencia_afdt_resolvida',
         jsonb_build_object('divergencia_id', _divergencia_id, 'observacao', _observacao),
         auth.uid()
    FROM public.afdt_divergencias WHERE id = _divergencia_id;
END; $$;


