    espelho_id, revogado_por_user_id, motivo, ip, user_agent
  ) VALUES (_espelho_id, auth.uid(), _motivo, _ip, _user_agent);

  RETURN jsonb_build_object('success', true, 'espelho_id', _espelho_id);
