CREATE OR REPLACE FUNCTION "public"."rls_auto_enable"() RETURNS "event_trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."rls_auto_enable"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rls_auto_enable"() IS 'Event trigger: ativa RLS em toda CREATE TABLE no schema public.
SECURITY DEFINER necessário para ALTER TABLE ENABLE ROW LEVEL SECURITY.
Acesso: somente postgres (sistema). Não é chamável por usuários — 
só o mecanismo interno de event triggers do PostgreSQL pode invocá-la.
Security finding secdef_exposed foi tratado: EXECUTE revogado de PUBLIC/anon.';



CREATE OR REPLACE FUNCTION "public"."run_rls_tests"() RETURNS SETOF "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
    RETURN NEXT has_extension('pgtap');
    
    -- Test: Collaborators RLS
    -- Verify that RLS is enabled
    RETURN NEXT is_rls_enabled('public', 'colaboradores');
    
    -- Test: Payroll RLS
    RETURN NEXT is_rls_enabled('public', 'folhas_pagamento');

    -- Detailed policy checks
    RETURN NEXT has_policy('public', 'colaboradores', 'Users can view their own company collaborators');
    RETURN NEXT has_policy('public', 'folhas_pagamento', 'Users can view their own company payroll');

    -- Note: Real row-access tests require creating temporary users, 
    -- which is best done in a controlled test environment.
END;
$$;


ALTER FUNCTION "public"."run_rls_tests"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_audit_unified"("_empresa_id" "uuid" DEFAULT NULL::"uuid", "_user_id" "uuid" DEFAULT NULL::"uuid", "_source_table" "text" DEFAULT NULL::"text", "_from" timestamp with time zone DEFAULT ("now"() - '30 days'::interval), "_to" timestamp with time zone DEFAULT "now"(), "_limit" integer DEFAULT 100) RETURNS TABLE("id" "uuid", "source_table" "text", "source_id" "uuid", "empresa_id" "uuid", "user_id" "uuid", "action" "text", "entity" "text", "entity_id" "text", "payload" "jsonb", "ip_address" "inet", "occurred_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    a.id, a.source_table, a.source_id, a.empresa_id, a.user_id,
    a.action, a.entity, a.entity_id, a.payload, a.ip_address, a.occurred_at
  FROM public.audit_log_unified a
  WHERE a.occurred_at BETWEEN _from AND _to
    AND (_empresa_id  IS NULL OR a.empresa_id  = _empresa_id)
    AND (_user_id     IS NULL OR a.user_id     = _user_id)
    AND (_source_table IS NULL OR a.source_table = _source_table)
    AND public.has_role(auth.uid(), 'admin')
  ORDER BY a.occurred_at DESC
  LIMIT LEAST(GREATEST(_limit, 1), 1000);
$$;


ALTER FUNCTION "public"."search_audit_unified"("_empresa_id" "uuid", "_user_id" "uuid", "_source_table" "text", "_from" timestamp with time zone, "_to" timestamp with time zone, "_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sec_audit_policies"() RETURNS TABLE("tabela" "text", "policy_name" "text", "cmd" "text", "motivo" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $_$
  SELECT p.tablename::text,
         p.policyname::text,
         p.cmd::text,
         CASE
           WHEN coalesce(p.qual,'') ~* '^\s*true\s*$' THEN 'USING (true) — sem restricao'
           WHEN (coalesce(p.qual,'')||coalesce(p.with_check,'')) ~* 'IN \( SELECT [a-z_]+\.(id|empresa_id)[^)]*FROM'
            AND (coalesce(p.qual,'')||coalesce(p.with_check,'')) !~* 'WHERE'
             THEN 'subconsulta sem correlacao com o usuario'
           WHEN (coalesce(p.qual,'')||coalesce(p.with_check,'')) ~* 'auth\.role\(\)\s*=\s*''authenticated'''
             THEN 'qualquer autenticado (sem escopo de empresa)'
           WHEN coalesce(p.qual,'')||coalesce(p.with_check,'') = '' THEN 'sem predicado'
           ELSE NULL
         END
  FROM pg_policies p
  WHERE p.schemaname = 'public'
    AND public.is_admin(auth.uid())
    AND CASE
          WHEN coalesce(p.qual,'') ~* '^\s*true\s*$' THEN true
          WHEN (coalesce(p.qual,'')||coalesce(p.with_check,'')) ~* 'IN \( SELECT [a-z_]+\.(id|empresa_id)[^)]*FROM'
           AND (coalesce(p.qual,'')||coalesce(p.with_check,'')) !~* 'WHERE' THEN true
          WHEN (coalesce(p.qual,'')||coalesce(p.with_check,'')) ~* 'auth\.role\(\)\s*=\s*''authenticated''' THEN true
          WHEN coalesce(p.qual,'')||coalesce(p.with_check,'') = '' THEN true
          ELSE false
        END
  ORDER BY 1, 2;
$_$;


ALTER FUNCTION "public"."sec_audit_policies"() OWNER TO "postgres";


