CREATE OR REPLACE FUNCTION "public"."solicitar_adiantamento_13_ferias"("p_ferias_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ferias RECORD;
  v_ano INT;
  v_salario NUMERIC;
  v_meses NUMERIC;
  v_valor NUMERIC;
  v_ja_existe BOOLEAN;
  v_uid UUID := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Não autenticado' USING ERRCODE = '42501';
  END IF;

  SELECT f.*, c.salario_base AS c_salario, c.data_admissao AS c_admissao
    INTO v_ferias
  FROM public.ferias f
  JOIN public.colaboradores c ON c.id = f.colaborador_id
  WHERE f.id = p_ferias_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Férias não encontrada' USING ERRCODE = 'P0002';
  END IF;

  -- Autorização: RH/admin da empresa OU o próprio colaborador
  IF NOT (
    public.has_role(v_uid, 'admin'::app_role)
    OR EXISTS (SELECT 1 FROM public.user_empresas ue WHERE ue.user_id = v_uid AND ue.empresa_id = v_ferias.empresa_id)
    OR EXISTS (SELECT 1 FROM public.colaboradores c WHERE c.id = v_ferias.colaborador_id AND c.user_id = v_uid)
  ) THEN
    RAISE EXCEPTION 'Sem permissão' USING ERRCODE = '42501';
  END IF;

  v_ano := EXTRACT(YEAR FROM v_ferias.data_inicio)::INT;

  -- Prazo legal: solicitação até 31/janeiro do ano do gozo
  IF CURRENT_DATE > make_date(v_ano, 1, 31) AND v_ferias.data_inicio > CURRENT_DATE THEN
    -- permite se férias já em curso não faz sentido, então bloqueia após jan
    RAISE EXCEPTION 'Prazo legal expirado (Lei 4.749/65 Art. 2º §2º: solicitar até 31/jan de %)', v_ano
      USING ERRCODE = 'P0001';
  END IF;

  -- Impedir duplicidade no ano
  SELECT EXISTS (
    SELECT 1 FROM public.ferias
    WHERE colaborador_id = v_ferias.colaborador_id
      AND adiantamento_13o = true
      AND adiantamento_13_ano_exercicio = v_ano
      AND id <> p_ferias_id
  ) INTO v_ja_existe;

  IF v_ja_existe THEN
    RAISE EXCEPTION 'Colaborador já recebeu adiantamento do 13º em %', v_ano
      USING ERRCODE = 'P0001';
  END IF;

  -- Cálculo: 50% de (salário * avos/12); avos = meses trabalhados no ano até início das férias
  v_salario := COALESCE(v_ferias.c_salario, 0);
  v_meses := LEAST(12, GREATEST(0,
    EXTRACT(MONTH FROM v_ferias.data_inicio)::INT
    - CASE WHEN EXTRACT(YEAR FROM v_ferias.c_admissao)::INT = v_ano
           THEN EXTRACT(MONTH FROM v_ferias.c_admissao)::INT - 1
           ELSE 0 END
  ));
  v_valor := ROUND((v_salario * v_meses / 12.0) * 0.5, 2);

  UPDATE public.ferias
     SET adiantamento_13o = true,
         adiantamento_13 = true,
         valor_adiantamento_13 = v_valor,
         adiantamento_13_solicitado_em = now(),
         adiantamento_13_solicitado_por = v_uid,
         adiantamento_13_ano_exercicio = v_ano
   WHERE id = p_ferias_id;

  INSERT INTO public.audit_log_unified (
    empresa_id, actor_id, action, source_table, entity, entity_id, payload
  ) VALUES (
    v_ferias.empresa_id, v_uid, 'ferias.adiantamento_13.solicitado', 'ferias',
    'ferias', p_ferias_id,
    jsonb_build_object('ano', v_ano, 'valor', v_valor, 'meses_avos', v_meses)
  );

  RETURN jsonb_build_object('ok', true, 'ano', v_ano, 'valor', v_valor, 'meses_avos', v_meses);
END;
$$;


ALTER FUNCTION "public"."solicitar_adiantamento_13_ferias"("p_ferias_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sst_cat_dashboard"("p_empresa_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_result JSONB;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.user_empresas WHERE user_id = auth.uid() AND empresa_id = p_empresa_id) THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  SELECT jsonb_build_object(
    'total_cats', COUNT(*),
    'pendentes_envio', COUNT(*) FILTER (WHERE data_envio_esocial IS NULL),
    'transmitidas', COUNT(*) FILTER (WHERE data_envio_esocial IS NOT NULL),
    'em_atraso', COUNT(*) FILTER (WHERE data_envio_esocial IS NULL AND prazo_limite_envio < now()),
    'obitos_ano', COUNT(*) FILTER (WHERE houve_obito AND EXTRACT(YEAR FROM data_acidente) = EXTRACT(YEAR FROM now())),
    'com_afastamento', COUNT(*) FILTER (WHERE houve_afastamento),
    'por_tipo', (
      SELECT jsonb_object_agg(tipo_acidente, cnt) FROM (
        SELECT tipo_acidente, COUNT(*) cnt FROM public.sst_cat WHERE empresa_id = p_empresa_id GROUP BY tipo_acidente
      ) t
    )
  ) INTO v_result
  FROM public.sst_cat
  WHERE empresa_id = p_empresa_id;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."sst_cat_dashboard"("p_empresa_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sst_dashboard_sla"("p_empresa_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_result JSONB;
  v_hoje DATE := CURRENT_DATE;
BEGIN
  -- Autorização: usuário precisa ter vínculo com a empresa
  IF NOT EXISTS (
    SELECT 1 FROM public.user_empresas ue
    WHERE ue.user_id = auth.uid() AND ue.empresa_id = p_empresa_id
  ) THEN
    RAISE EXCEPTION 'Acesso negado à empresa informada';
  END IF;

  WITH aso_stats AS (
    SELECT
      COUNT(*) FILTER (WHERE data_validade < v_hoje) AS vencidos,
      COUNT(*) FILTER (WHERE data_validade BETWEEN v_hoje AND v_hoje + INTERVAL '30 days') AS vencendo_30,
      COUNT(*) FILTER (WHERE data_validade BETWEEN v_hoje + INTERVAL '31 days' AND v_hoje + INTERVAL '60 days') AS vencendo_60,
      COUNT(*) FILTER (WHERE data_validade BETWEEN v_hoje + INTERVAL '61 days' AND v_hoje + INTERVAL '90 days') AS vencendo_90,
      COUNT(*) FILTER (WHERE data_validade > v_hoje + INTERVAL '90 days') AS validos,
      COUNT(*) AS total
    FROM public.asos
    WHERE empresa_id = p_empresa_id
      AND status IN ('validado','recebido_rh')
  ),
  colab_sem_aso AS (
    SELECT COUNT(*) AS qtd
    FROM public.colaboradores c
    WHERE c.empresa_id = p_empresa_id
      AND c.status = 'ativo'
      AND NOT EXISTS (
        SELECT 1 FROM public.asos a
        WHERE a.colaborador_id = c.id AND a.status IN ('validado','recebido_rh')
      )
  ),
  epi_stats AS (
    SELECT
      COUNT(*) FILTER (WHERE ca_validade < v_hoje) AS ca_vencidos,
      COUNT(*) FILTER (WHERE ca_validade BETWEEN v_hoje AND v_hoje + INTERVAL '60 days') AS ca_vencendo_60
    FROM public.epis
    WHERE empresa_id = p_empresa_id
  ),
  agenda_stats AS (
    SELECT
      COUNT(*) FILTER (WHERE status = 'agendado' AND data_agendada >= v_hoje) AS pendentes,
      COUNT(*) FILTER (WHERE status = 'agendado' AND data_agendada < v_hoje) AS atrasados,
      COUNT(*) FILTER (WHERE status = 'realizado' AND data_agendada >= date_trunc('month', v_hoje)) AS realizados_mes
    FROM public.exames_agendamentos
    WHERE empresa_id = p_empresa_id
  ),
  sla_clinicas AS (
    SELECT AVG(EXTRACT(EPOCH FROM (a.validado_em - ag.created_at)) / 86400.0) AS dias_medio
    FROM public.asos a
    JOIN public.exames_agendamentos ag ON ag.id = a.agendamento_id
    WHERE a.empresa_id = p_empresa_id
      AND a.status = 'validado'
      AND a.validado_em IS NOT NULL
      AND a.validado_em >= v_hoje - INTERVAL '90 days'
  )
  SELECT jsonb_build_object(
    'asos', (SELECT to_jsonb(a) FROM aso_stats a),
    'colaboradores_sem_aso', (SELECT qtd FROM colab_sem_aso),
    'epis', (SELECT to_jsonb(e) FROM epi_stats e),
    'agendamentos', (SELECT to_jsonb(ag) FROM agenda_stats ag),
    'sla_clinicas_dias', COALESCE((SELECT ROUND(dias_medio::numeric, 2) FROM sla_clinicas), 0)
  ) INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."sst_dashboard_sla"("p_empresa_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sst_extintores_dashboard"("p_empresa_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_result JSONB;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.user_empresas WHERE user_id = auth.uid() AND empresa_id = p_empresa_id) THEN
    RAISE EXCEPTION 'Acesso negado';
  END IF;

  SELECT jsonb_build_object(
    'total', COUNT(*),
    'ativos', COUNT(*) FILTER (WHERE status = 'ATIVO'),
    'vencidos', COUNT(*) FILTER (WHERE status = 'VENCIDO'),
    'em_manutencao', COUNT(*) FILTER (WHERE status = 'MANUTENCAO'),
    'recarga_30d', COUNT(*) FILTER (WHERE data_proxima_recarga BETWEEN CURRENT_DATE AND CURRENT_DATE + 30),
    'hidro_90d', COUNT(*) FILTER (WHERE data_proximo_teste_hidrostatico BETWEEN CURRENT_DATE AND CURRENT_DATE + 90),
    'inspecoes_mes', (SELECT COUNT(*) FROM public.sst_extintores_inspecoes 
                       WHERE empresa_id = p_empresa_id 
                       AND data_inspecao >= date_trunc('month', CURRENT_DATE)),
    'nao_conformes_mes', (SELECT COUNT(*) FROM public.sst_extintores_inspecoes 
                           WHERE empresa_id = p_empresa_id 
                           AND data_inspecao >= date_trunc('month', CURRENT_DATE)
                           AND resultado <> 'CONFORME')
  ) INTO v_result
  FROM public.sst_extintores
  WHERE empresa_id = p_empresa_id AND deleted_at IS NULL;

  RETURN v_result;
END;
$$;


