CREATE OR REPLACE FUNCTION "public"."sst_regimento_assinar"("p_documento_id" "uuid", "p_colaborador_id" "uuid", "p_ip" "text" DEFAULT NULL::"text", "p_user_agent" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_doc RECORD;
  v_hash_ass TEXT;
BEGIN
  SELECT * INTO v_doc FROM public.sst_regimento_documentos WHERE id = p_documento_id;
  IF NOT FOUND OR v_doc.status <> 'PUBLICADO' THEN
    RAISE EXCEPTION 'Documento não publicado';
  END IF;

  v_hash_ass := encode(digest(
    v_doc.hash_sha256 || '|' || p_colaborador_id::text || '|' || now()::text,
    'sha256'
  ), 'hex');

  INSERT INTO public.sst_regimento_assinaturas
    (documento_id, colaborador_id, empresa_id, hash_documento, hash_assinatura, ip_origem, user_agent)
  VALUES
    (p_documento_id, p_colaborador_id, v_doc.empresa_id, v_doc.hash_sha256, v_hash_ass, p_ip, p_user_agent)
  ON CONFLICT (documento_id, colaborador_id) DO NOTHING;

  RETURN jsonb_build_object('ok', true, 'hash_assinatura', v_hash_ass);
END;
$$;


ALTER FUNCTION "public"."sst_regimento_assinar"("p_documento_id" "uuid", "p_colaborador_id" "uuid", "p_ip" "text", "p_user_agent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sst_regimento_dashboard"("p_empresa_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_doc RECORD;
  v_total_colab INTEGER;
  v_assinados INTEGER;
BEGIN
  IF p_empresa_id NOT IN (SELECT empresa_id FROM public.user_empresas WHERE user_id = auth.uid()) THEN
    RAISE EXCEPTION 'Sem acesso à empresa';
  END IF;

  SELECT * INTO v_doc FROM public.sst_regimento_documentos
   WHERE empresa_id = p_empresa_id AND status = 'PUBLICADO' LIMIT 1;

  SELECT count(*) INTO v_total_colab FROM public.colaboradores
   WHERE empresa_id = p_empresa_id
     AND coalesce(status::text, 'ativo') = 'ativo';

  IF v_doc.id IS NULL THEN
    RETURN jsonb_build_object('documento', null, 'total_colaboradores', v_total_colab, 'assinados', 0, 'pendentes', v_total_colab, 'adesao_pct', 0);
  END IF;

  SELECT count(*) INTO v_assinados FROM public.sst_regimento_assinaturas
   WHERE documento_id = v_doc.id;

  RETURN jsonb_build_object(
    'documento', jsonb_build_object('id', v_doc.id, 'titulo', v_doc.titulo, 'versao', v_doc.versao, 'publicado_em', v_doc.publicado_em, 'hash', v_doc.hash_sha256),
    'total_colaboradores', v_total_colab,
    'assinados', v_assinados,
    'pendentes', GREATEST(v_total_colab - v_assinados, 0),
    'adesao_pct', CASE WHEN v_total_colab > 0 THEN round((v_assinados::numeric / v_total_colab) * 100, 2) ELSE 0 END
  );
END;
$$;


ALTER FUNCTION "public"."sst_regimento_dashboard"("p_empresa_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sst_regimento_notificar_pendentes"("p_empresa_id" "uuid") RETURNS TABLE("notificados" integer, "ja_assinados" integer, "sem_user" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_doc RECORD;
  v_notif int := 0;
  v_assin int := 0;
  v_sem_user int := 0;
BEGIN
  -- Requer papel administrativo na empresa
  IF NOT (
    public.has_role(auth.uid(), 'admin'::app_role)
    OR public.has_role(auth.uid(), 'super_admin'::app_role)
    OR public.has_role(auth.uid(), 'rh'::app_role)
  ) THEN
    RAISE EXCEPTION 'Acesso negado: requer papel administrativo';
  END IF;

  -- Documento vigente
  SELECT id, titulo, versao
    INTO v_doc
    FROM public.sst_regimento_documentos
   WHERE empresa_id = p_empresa_id
     AND status = 'PUBLICADO'
   ORDER BY versao DESC
   LIMIT 1;

  IF v_doc.id IS NULL THEN
    RETURN QUERY SELECT 0, 0, 0;
    RETURN;
  END IF;

  -- Contadores auxiliares
  SELECT count(*) INTO v_assin
    FROM public.sst_regimento_assinaturas a
    JOIN public.colaboradores c ON c.id = a.colaborador_id
   WHERE a.documento_id = v_doc.id
     AND c.empresa_id = p_empresa_id;

  SELECT count(*) INTO v_sem_user
    FROM public.colaboradores c
   WHERE c.empresa_id = p_empresa_id
     AND COALESCE(c.status, 'ativo') = 'ativo'
     AND c.user_id IS NULL
     AND NOT EXISTS (
       SELECT 1 FROM public.sst_regimento_assinaturas a
        WHERE a.documento_id = v_doc.id AND a.colaborador_id = c.id
     );

  -- Insere notificações para colaboradores ativos, com user_id, ainda não assinantes,
  -- e sem notificação da MESMA versão nos últimos 7 dias (dedupe).
  WITH candidatos AS (
    SELECT c.id AS colaborador_id, c.user_id
      FROM public.colaboradores c
     WHERE c.empresa_id = p_empresa_id
       AND COALESCE(c.status, 'ativo') = 'ativo'
       AND c.user_id IS NOT NULL
       AND NOT EXISTS (
         SELECT 1 FROM public.sst_regimento_assinaturas a
          WHERE a.documento_id = v_doc.id
            AND a.colaborador_id = c.id
       )
       AND NOT EXISTS (
         SELECT 1 FROM public.notificacoes n
          WHERE n.user_id = c.user_id
            AND n.tipo = 'regimento_sst_pendente'
            AND n.entidade_id = v_doc.id
            AND n.created_at > now() - interval '7 days'
       )
  ), ins AS (
    INSERT INTO public.notificacoes
      (user_id, empresa_id, tipo, titulo, mensagem, entidade_tipo, entidade_id, lida)
    SELECT
      user_id,
      p_empresa_id,
      'regimento_sst_pendente',
      'Regimento Interno de SST — assinatura pendente',
      format('Você ainda não assinou %s (versão %s). Acesse o portal para regularizar.',
             v_doc.titulo, v_doc.versao),
      'sst_regimento_documento',
      v_doc.id,
      false
    FROM candidatos
    RETURNING 1
  )
  SELECT count(*) INTO v_notif FROM ins;

  RETURN QUERY SELECT v_notif, v_assin, v_sem_user;
END;
$$;


ALTER FUNCTION "public"."sst_regimento_notificar_pendentes"("p_empresa_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sst_regimento_pendentes_lista"("p_empresa_id" "uuid") RETURNS TABLE("colaborador_id" "uuid", "nome" "text", "email" "text", "cargo" "text", "departamento" "text", "tem_usuario" boolean, "ultima_notificacao" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_doc_id uuid;
  v_versao integer;
BEGIN
  IF NOT (
    public.has_role(auth.uid(), 'admin')
    OR public.has_role(auth.uid(), 'super_admin')
    OR public.has_role(auth.uid(), 'rh')
  ) THEN
    RAISE EXCEPTION 'Acesso negado' USING ERRCODE = '42501';
  END IF;

  SELECT d.id, d.versao INTO v_doc_id, v_versao
  FROM public.sst_regimento_documentos d
  WHERE d.empresa_id = p_empresa_id AND d.status = 'PUBLICADO'
  ORDER BY d.versao DESC
  LIMIT 1;

  IF v_doc_id IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    c.id,
    COALESCE(c.nome_completo, c.nome, 'Sem nome')::text,
    c.email::text,
    c.cargo::text,
    c.departamento::text,
    (c.user_id IS NOT NULL) AS tem_usuario,
    (
      SELECT MAX(n.created_at)
      FROM public.notificacoes n
      WHERE n.user_id = c.user_id
        AND n.tipo = 'sst_regimento_pendente'
        AND (n.metadata->>'documento_id')::uuid = v_doc_id
    ) AS ultima_notificacao
  FROM public.colaboradores c
  WHERE c.empresa_id = p_empresa_id
    AND coalesce(c.status::text, 'ativo') = 'ativo'
    AND NOT EXISTS (
      SELECT 1 FROM public.sst_regimento_assinaturas a
      WHERE a.documento_id = v_doc_id AND a.colaborador_id = c.id
    )
  ORDER BY COALESCE(c.nome_completo, c.nome) ASC
  LIMIT 500;
END;
$$;


ALTER FUNCTION "public"."sst_regimento_pendentes_lista"("p_empresa_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sst_regimento_publicar"("p_documento_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_doc RECORD;
  v_hash TEXT;
BEGIN
  SELECT * INTO v_doc FROM public.sst_regimento_documentos WHERE id = p_documento_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Documento não encontrado'; END IF;

  IF NOT (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'rh')) THEN
    RAISE EXCEPTION 'Sem permissão';
  END IF;

  -- Arquiva versão publicada anterior
  UPDATE public.sst_regimento_documentos
     SET status = 'ARQUIVADO'
   WHERE empresa_id = v_doc.empresa_id AND status = 'PUBLICADO' AND id <> p_documento_id;

  -- Hash canônico do conteúdo
  v_hash := encode(digest(coalesce(v_doc.titulo,'') || '|' || coalesce(v_doc.conteudo_html,'') || '|v' || v_doc.versao, 'sha256'), 'hex');

  UPDATE public.sst_regimento_documentos
     SET status = 'PUBLICADO',
         hash_sha256 = v_hash,
         publicado_em = now(),
         publicado_por = auth.uid()
   WHERE id = p_documento_id;

  RETURN jsonb_build_object('ok', true, 'hash', v_hash);
END;
$$;


ALTER FUNCTION "public"."sst_regimento_publicar"("p_documento_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."storage_path_empresa_id"("p_name" "text") RETURNS "uuid"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_catalog'
    AS $_$
  SELECT CASE
    WHEN (storage.foldername(p_name))[1] ~
         '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
      THEN ((storage.foldername(p_name))[1])::uuid
    ELSE NULL
  END;
$_$;


ALTER FUNCTION "public"."storage_path_empresa_id"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sugerir_proxima_medida"("p_colaborador_id" "uuid", "p_empresa_id" "uuid") RETURNS TABLE("tipo_sugerido" "text", "justificativa" "text", "historico_12m" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_verbal int;
  v_escrita int;
  v_suspensao int;
  v_tipo text;
  v_just text;
BEGIN
  -- Segurança: valida que o usuário pertence à empresa
  IF NOT (p_empresa_id = ANY (SELECT get_user_empresas(auth.uid()))) THEN
    RAISE EXCEPTION 'Acesso negado: empresa % fora do escopo do usuário', p_empresa_id
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT
    COUNT(*) FILTER (WHERE tipo = 'advertencia_verbal'),
    COUNT(*) FILTER (WHERE tipo = 'advertencia_escrita'),
    COUNT(*) FILTER (WHERE tipo = 'suspensao')
  INTO v_verbal, v_escrita, v_suspensao
  FROM public.medidas_disciplinares
  WHERE colaborador_id = p_colaborador_id
    AND empresa_id = p_empresa_id
    AND status_workflow = 'aplicada'
    AND data_ocorrencia >= (CURRENT_DATE - INTERVAL '12 months');

  -- Gradação CLT
  IF v_suspensao >= 2 THEN
    v_tipo := 'justa_causa';
    v_just := format('Colaborador com %s suspensão(ões) em 12 meses. Padrão de reincidência sustenta justa causa (Art. 482 CLT).', v_suspensao);
  ELSIF v_escrita >= 2 OR v_suspensao >= 1 THEN
    v_tipo := 'suspensao';
    v_just := format('Colaborador com %s advertência(s) escrita(s) e %s suspensão(ões). Gradação: aplicar suspensão.', v_escrita, v_suspensao);
  ELSIF v_verbal >= 2 OR v_escrita >= 1 THEN
    v_tipo := 'advertencia_escrita';
    v_just := format('Colaborador com %s advertência(s) verbal(is). Gradação: advertência escrita.', v_verbal);
  ELSE
    v_tipo := 'advertencia_verbal';
    v_just := 'Colaborador sem histórico relevante. Iniciar por advertência verbal.';
  END IF;

  RETURN QUERY SELECT
    v_tipo,
    v_just,
    jsonb_build_object(
      'advertencia_verbal', v_verbal,
      'advertencia_escrita', v_escrita,
      'suspensao', v_suspensao
    );
END;
$$;


