CREATE OR REPLACE FUNCTION "public"."trg_contrato_token_auditar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.contrato_token_eventos(empresa_id, token_id, contrato_id, evento, detalhes, ator_id)
    VALUES (NEW.empresa_id, NEW.id, NEW.contrato_id, 'gerado',
      jsonb_build_object('expira_em', NEW.expira_em, 'email', NEW.email_destinatario),
      NEW.created_by);
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF NEW.revogado_em IS NOT NULL AND OLD.revogado_em IS NULL THEN
      INSERT INTO public.contrato_token_eventos(empresa_id, token_id, contrato_id, evento, detalhes, ator_id)
      VALUES (NEW.empresa_id, NEW.id, NEW.contrato_id, 'revogado',
        jsonb_build_object('motivo', NEW.revogacao_motivo), NEW.revogado_por);
    END IF;

    IF NEW.expira_em > OLD.expira_em THEN
      INSERT INTO public.contrato_token_eventos(empresa_id, token_id, contrato_id, evento, detalhes, ator_id)
      VALUES (NEW.empresa_id, NEW.id, NEW.contrato_id, 'estendido',
        jsonb_build_object('de', OLD.expira_em, 'para', NEW.expira_em), auth.uid());
    END IF;

    IF NEW.usado_em IS NOT NULL AND OLD.usado_em IS NULL THEN
      INSERT INTO public.contrato_token_eventos(empresa_id, token_id, contrato_id, evento, detalhes, ip, user_agent)
      VALUES (NEW.empresa_id, NEW.id, NEW.contrato_id, 'assinado',
        jsonb_build_object('hash', NEW.assinatura_hash), NEW.assinado_ip, NEW.assinado_ua);
    END IF;

    IF NEW.reminders_enviados > OLD.reminders_enviados THEN
      INSERT INTO public.contrato_token_eventos(empresa_id, token_id, contrato_id, evento, detalhes)
      VALUES (NEW.empresa_id, NEW.id, NEW.contrato_id, 'lembrete_enviado',
        jsonb_build_object('total', NEW.reminders_enviados, 'em', NEW.ultimo_reminder_at));
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_contrato_token_auditar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_desligamentos_status_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF OLD.status = 'pago' AND NEW.status IS DISTINCT FROM 'pago' THEN
    RAISE EXCEPTION 'Rescisão paga é definitiva e não pode ser reaberta ou alterada'
      USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.status = 'pago' AND OLD.status IS DISTINCT FROM 'pago' THEN
    IF OLD.status IS DISTINCT FROM 'homologado' THEN
      RAISE EXCEPTION 'Rescisao só pode ser paga após homologação (status atual: %)', OLD.status
        USING ERRCODE = 'check_violation';
    END IF;
    IF NOT COALESCE(NEW.assinado_empresa, false) OR NOT COALESCE(NEW.assinado_colaborador, false) THEN
      RAISE EXCEPTION 'Rescisao só pode ser paga com assinatura da empresa e do colaborador registradas'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF public._is_admin_bypass() THEN RETURN NEW; END IF;

  PERFORM public.validate_status_transition('desligamentos', OLD.status, NEW.status, '{
    "rascunho": ["em_andamento","cancelado"],
    "pendente": ["em_andamento","cancelado"],
    "em_andamento": ["aprovado","rejeitado","cancelado","calculado"],
    "calculado": ["em_homologacao","em_andamento","cancelado"],
    "em_homologacao": ["homologado","calculado","cancelado"],
    "aprovado": ["concluido","homologado","cancelado"],
    "concluido": ["homologado"],
    "homologado": ["pago"]
  }'::jsonb);
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_desligamentos_status_transition"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_detect_status_anomaly"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _count integer;
  _threshold constant integer := 50;
  _window constant interval := interval '5 minutes';
BEGIN
  IF NEW.acao <> 'STATUS_CHANGE' OR NEW.user_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT count(*) INTO _count
  FROM public.audit_log
  WHERE user_id = NEW.user_id
    AND tabela  = NEW.tabela
    AND acao    = 'STATUS_CHANGE'
    AND created_at >= now() - _window;

  IF _count >= _threshold THEN
    -- Dedup: só um alerta aberto por (user,tabela) na janela
    IF NOT EXISTS (
      SELECT 1 FROM public.security_alerts
      WHERE type = 'status_change_burst'
        AND user_id = NEW.user_id
        AND details->>'tabela' = NEW.tabela
        AND COALESCE(resolved,false) = false
        AND created_at >= now() - _window
    ) THEN
      INSERT INTO public.security_alerts (type, severity, user_id, details)
      VALUES (
        'status_change_burst', 'high', NEW.user_id,
        jsonb_build_object('tabela', NEW.tabela, 'count', _count,
                           'window_minutes', 5, 'threshold', _threshold,
                           'detected_at', now())
      );
    END IF;
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END; $$;


ALTER FUNCTION "public"."trg_detect_status_anomaly"() OWNER TO "postgres";


