CREATE OR REPLACE FUNCTION "public"."user_empresa_id"() RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
  DECLARE
    v_empresa UUID;
  BEGIN
    -- Prioridade 1: user_metadata.empresa_id (logins antigos, mantém compat).
    v_empresa := (auth.jwt() -> 'user_metadata' ->> 'empresa_id')::UUID;
    IF v_empresa IS NOT NULL THEN
      RETURN v_empresa;
    END IF;

    -- Prioridade 2: empresa padrão (is_default=true) do vínculo do usuário.
    SELECT empresa_id INTO v_empresa
      FROM public.user_empresas
      WHERE user_id = auth.uid() AND is_default = true
      LIMIT 1;
    IF v_empresa IS NOT NULL THEN
      RETURN v_empresa;
    END IF;

    -- Prioridade 3: primeira empresa vinculada (caso não tenha is_default).
    SELECT empresa_id INTO v_empresa
      FROM public.user_empresas
      WHERE user_id = auth.uid()
      ORDER BY created_at ASC
      LIMIT 1;

    RETURN v_empresa;
  END;
$$;


ALTER FUNCTION "public"."user_empresa_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validar_contrato_clt"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_tipo TEXT;
  v_dias INTEGER;
  v_anterior_dias INTEGER;
BEGIN
  SELECT tipo_contrato INTO v_tipo FROM public.contrato_templates WHERE id = NEW.template_id;

  IF NEW.data_inicio IS NOT NULL AND NEW.data_fim IS NOT NULL THEN
    v_dias := (NEW.data_fim - NEW.data_inicio);

    IF v_dias < 0 THEN
      RAISE EXCEPTION 'CLT: data_fim não pode ser anterior a data_inicio';
    END IF;

    -- Experiência: máx 45 dias por período, 90 no total (Art. 445 §único)
    IF v_tipo = 'clt_experiencia' THEN
      IF v_dias > 45 THEN
        RAISE EXCEPTION 'CLT Art. 445 §único: contrato de experiência não pode exceder 45 dias por período (informado: % dias)', v_dias;
      END IF;

      IF NEW.contrato_anterior_id IS NOT NULL THEN
        SELECT (data_fim - data_inicio) INTO v_anterior_dias
        FROM public.contratos_gerados WHERE id = NEW.contrato_anterior_id;

        IF COALESCE(v_anterior_dias,0) + v_dias > 90 THEN
          RAISE EXCEPTION 'CLT Art. 445 §único: soma dos períodos de experiência (45+45) não pode exceder 90 dias';
        END IF;

        -- Marca o anterior como prorrogado
        UPDATE public.contratos_gerados SET prorrogado = TRUE WHERE id = NEW.contrato_anterior_id;
      END IF;
    END IF;

    -- Determinado: máx 2 anos (Art. 445 caput)
    IF v_tipo = 'clt_determinado' AND v_dias > 730 THEN
      RAISE EXCEPTION 'CLT Art. 445: contrato por prazo determinado não pode exceder 2 anos';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validar_contrato_clt"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validar_split_ferias"("p_colaborador_id" "uuid", "p_periodo_aquisitivo_id" "uuid", "p_dias_novo" integer, "p_ferias_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("ok" boolean, "motivo" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_periodos integer;
  v_total_dias integer;
  v_maior integer;
  v_min_periodo integer;
BEGIN
  IF p_periodo_aquisitivo_id IS NULL THEN
    RETURN QUERY SELECT true, NULL::text; RETURN;
  END IF;

  SELECT COUNT(*), COALESCE(SUM(dias_gozo),0), COALESCE(MAX(dias_gozo),0), COALESCE(MIN(dias_gozo),9999)
    INTO v_periodos, v_total_dias, v_maior, v_min_periodo
  FROM public.ferias
  WHERE colaborador_id = p_colaborador_id
    AND periodo_aquisitivo_id = p_periodo_aquisitivo_id
    AND COALESCE(cancelado, false) = false
    AND (p_ferias_id IS NULL OR id <> p_ferias_id);

  -- Simular inclusão/alteração do registro atual
  v_periodos := v_periodos + 1;
  v_total_dias := v_total_dias + p_dias_novo;
  v_maior := GREATEST(v_maior, p_dias_novo);
  v_min_periodo := LEAST(v_min_periodo, p_dias_novo);

  IF v_periodos > 3 THEN
    RETURN QUERY SELECT false, 'FERIAS_SPLIT_INVALIDO: máximo de 3 períodos por aquisitivo (Art. 134 §1º CLT).'; RETURN;
  END IF;

  IF v_periodos >= 2 AND v_maior < 14 THEN
    RETURN QUERY SELECT false, 'FERIAS_SPLIT_INVALIDO: ao fracionar, um dos períodos deve ter no mínimo 14 dias corridos (Art. 134 §1º CLT).'; RETURN;
  END IF;

  IF v_periodos >= 2 AND v_min_periodo < 5 THEN
    RETURN QUERY SELECT false, 'FERIAS_SPLIT_INVALIDO: nenhum período fracionado pode ter menos de 5 dias corridos (Art. 134 §1º CLT).'; RETURN;
  END IF;

  RETURN QUERY SELECT true, NULL::text;
END;
$$;


ALTER FUNCTION "public"."validar_split_ferias"("p_colaborador_id" "uuid", "p_periodo_aquisitivo_id" "uuid", "p_dias_novo" integer, "p_ferias_id" "uuid") OWNER TO "postgres";


