CREATE OR REPLACE FUNCTION "public"."validate_ponto_compliance"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
    v_config RECORD;
BEGIN
    -- Busca configurações da empresa
    SELECT * INTO v_config FROM public.configuracoes_ponto WHERE empresa_id = NEW.empresa_id LIMIT 1;

    -- 1. Validação de Integridade (Hash SHA256)
    -- O hash deve ser validado no backend se houver segredo, aqui apenas checamos presença
    IF NEW.hash_integridade IS NULL THEN
        INSERT INTO public.conformidade_ponto_logs (empresa_id, batida_id, tipo_alerta, descricao, severidade)
        VALUES (NEW.empresa_id, NEW.id, 'integridade', 'Batida sem hash de integridade gerado.', 'alta');
    END IF;

    -- 2. Validação de Geofencing (se ativo)
    IF NEW.dentro_raio = false THEN
        INSERT INTO public.conformidade_ponto_logs (empresa_id, batida_id, tipo_alerta, descricao, severidade)
        VALUES (NEW.empresa_id, NEW.id, 'geofencing', 'Colaborador registrou ponto fora do raio permitido.', 'media');
    END IF;

    -- 3. Validação de Timezone Divergente
    IF NEW.timezone IS NOT NULL AND NEW.timezone <> 'America/Sao_Paulo' THEN -- Exemplo, ideal buscar da empresa
         INSERT INTO public.conformidade_ponto_logs (empresa_id, batida_id, tipo_alerta, descricao, severidade)
        VALUES (NEW.empresa_id, NEW.id, 'timezone', 'Timezone divergente detectado: ' || NEW.timezone, 'baixa');
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_ponto_compliance"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_status_transition"("_table" "text", "_old" "text", "_new" "text", "_allowed" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF _old IS NULL OR _new IS NULL OR _old = _new THEN RETURN; END IF;
  IF _allowed ? _old AND (_allowed -> _old) ? _new THEN RETURN; END IF;
  RAISE EXCEPTION 'Transição de status inválida em %: % → % (permitidas: %)',
    _table, _old, _new, COALESCE(_allowed -> _old, '[]'::jsonb)
    USING ERRCODE = 'check_violation';
END;
$$;


ALTER FUNCTION "public"."validate_status_transition"("_table" "text", "_old" "text", "_new" "text", "_allowed" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verificar_divergencias_folha"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
    media_anterior DECIMAL;
BEGIN
    -- Busca média dos últimos 3 meses para o mesmo colaborador
    SELECT AVG(total_proventos) INTO media_anterior 
    FROM public.folhas_pagamento 
    WHERE colaborador_id = NEW.colaborador_id 
      AND status = 'fechada'
      AND competencia < NEW.competencia
    LIMIT 3;

    -- Se houver uma variação maior que 30%, marca alerta
    IF media_anterior IS NOT NULL AND (ABS(NEW.total_proventos - media_anterior) / media_anterior) > 0.3 THEN
        NEW.alerta_calculo = jsonb_build_object(
            'tipo', 'VARIACAO_SALARIAL_ALTA',
            'valor_anterior', media_anterior,
            'variacao_percentual', ROUND(((NEW.total_proventos - media_anterior) / media_anterior) * 100, 2),
            'mensagem', 'Variação de proventos superior a 30% detectada.'
        );
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."verificar_divergencias_folha"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verificar_espelho_ponto"("_espelho_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v record;
  v_canonical_atual jsonb;
  v_hash_atual text;
BEGIN
  SELECT * INTO v FROM public.ponto_espelhos_assinados WHERE id = _espelho_id;
  IF v IS NULL THEN
    RAISE EXCEPTION 'Espelho não encontrado';
  END IF;

  -- Verificar permissão
  IF NOT EXISTS (
    SELECT 1 FROM public.user_empresas
    WHERE user_id = auth.uid() AND empresa_id = v.empresa_id
  ) AND auth.uid() <> v.colaborador_id THEN
    RAISE EXCEPTION 'Sem permissão';
  END IF;

  v_canonical_atual := public.gerar_canonical_espelho_ponto(v.colaborador_id, v.competencia);
  v_hash_atual := encode(digest(v_canonical_atual::text, 'sha256'), 'hex');

  RETURN jsonb_build_object(
    'espelho_id', v.id,
    'hash_original', v.hash_sha256,
    'hash_atual', v_hash_atual,
    'integro', v.hash_sha256 = v_hash_atual,
    'assinado_em', v.assinado_em,
    'total_batidas_original', v.total_batidas,
    'total_batidas_atual', (v_canonical_atual->>'total_batidas')::int,
    'revogado', EXISTS(SELECT 1 FROM public.ponto_espelhos_revogacoes WHERE espelho_id = v.id)
  );
END;
$$;


ALTER FUNCTION "public"."verificar_espelho_ponto"("_espelho_id" "uuid") OWNER TO "postgres";


