CREATE OR REPLACE VIEW "public"."pontos_abertos" AS
 SELECT "rp"."id",
    "rp"."colaborador_id",
    "c"."nome_completo",
    "rp"."data",
    "rp"."entrada_1",
    "rp"."saida_1",
    "rp"."entrada_2",
    "rp"."saida_2",
    "rp"."empresa_id"
   FROM ("public"."registros_ponto" "rp"
     JOIN "public"."colaboradores" "c" ON (("c"."id" = "rp"."colaborador_id")))
  WHERE (("rp"."saida_1" IS NULL) AND ("rp"."data" <= CURRENT_DATE))
  ORDER BY "rp"."data" DESC;


