CREATE OR REPLACE VIEW "public"."v_audit_trail" AS
 SELECT "a"."id",
    "a"."created_at",
    "a"."tabela",
    "a"."registro_id",
    "a"."acao",
    "a"."user_id",
    "u"."email" AS "user_email",
    "p"."nome" AS "user_nome",
    ("a"."dados_anteriores" ->> 'status'::"text") AS "status_anterior",
    ("a"."dados_novos" ->> 'status'::"text") AS "status_novo",
    (NULLIF(("a"."dados_novos" ->> 'empresa_id'::"text"), ''::"text"))::"uuid" AS "empresa_id",
    "a"."dados_anteriores",
    "a"."dados_novos"
   FROM (("public"."audit_log" "a"
     LEFT JOIN "auth"."users" "u" ON (("u"."id" = "a"."user_id")))
     LEFT JOIN "public"."profiles" "p" ON (("p"."user_id" = "a"."user_id")));


ALTER VIEW "public"."v_audit_trail" OWNER TO "postgres";


