CREATE OR REPLACE VIEW "public"."vw_cadastro_incompleto" AS
 SELECT "id",
    "nome_completo",
    "empresa_id",
    "status",
    "array_remove"(ARRAY[
        CASE
            WHEN (("cpf" IS NULL) OR ("cpf" = ''::"text")) THEN 'CPF'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("rg" IS NULL) OR ("rg" = ''::"text")) THEN 'RG'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("email" IS NULL) OR ("email" = ''::"text")) THEN 'Email'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("celular" IS NULL) OR ("celular" = ''::"text")) THEN 'Celular'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("cep" IS NULL) OR ("cep" = ''::"text")) THEN 'CEP'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("pis_pasep" IS NULL) OR ("pis_pasep" = ''::"text")) THEN 'PIS'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN ("data_nascimento" IS NULL) THEN 'Data Nascimento'::"text"
            ELSE NULL::"text"
        END], NULL::"text") AS "campos_faltantes",
    "array_length"("array_remove"(ARRAY[
        CASE
            WHEN (("cpf" IS NULL) OR ("cpf" = ''::"text")) THEN 'CPF'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("rg" IS NULL) OR ("rg" = ''::"text")) THEN 'RG'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("email" IS NULL) OR ("email" = ''::"text")) THEN 'Email'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("celular" IS NULL) OR ("celular" = ''::"text")) THEN 'Celular'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("cep" IS NULL) OR ("cep" = ''::"text")) THEN 'CEP'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("pis_pasep" IS NULL) OR ("pis_pasep" = ''::"text")) THEN 'PIS'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN ("data_nascimento" IS NULL) THEN 'Data Nascimento'::"text"
            ELSE NULL::"text"
        END], NULL::"text"), 1) AS "total_faltantes"
   FROM "public"."colaboradores" "c"
  WHERE (("status" = 'ativo'::"public"."status_colaborador") AND (("cpf" IS NULL) OR ("cpf" = ''::"text") OR ("rg" IS NULL) OR ("rg" = ''::"text") OR ("email" IS NULL) OR ("email" = ''::"text") OR ("pis_pasep" IS NULL) OR ("pis_pasep" = ''::"text")))
  ORDER BY ("array_length"("array_remove"(ARRAY[
        CASE
            WHEN (("cpf" IS NULL) OR ("cpf" = ''::"text")) THEN 'CPF'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("rg" IS NULL) OR ("rg" = ''::"text")) THEN 'RG'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("email" IS NULL) OR ("email" = ''::"text")) THEN 'Email'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("celular" IS NULL) OR ("celular" = ''::"text")) THEN 'Celular'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("cep" IS NULL) OR ("cep" = ''::"text")) THEN 'CEP'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("pis_pasep" IS NULL) OR ("pis_pasep" = ''::"text")) THEN 'PIS'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN ("data_nascimento" IS NULL) THEN 'Data Nascimento'::"text"
            ELSE NULL::"text"
        END], NULL::"text"), 1)) DESC NULLS LAST;


ALTER VIEW "public"."vw_cadastro_incompleto" OWNER TO "postgres";


