CREATE POLICY "Acesso aos itens via folha" ON "public"."itens_folha" USING ((EXISTS ( SELECT 1
   FROM "public"."folhas_pagamento" "f"
  WHERE (("f"."id" = "itens_folha"."folha_id") AND ("f"."empresa_id" IN ( SELECT "user_empresas"."empresa_id"
           FROM "public"."user_empresas"
          WHERE ("user_empresas"."user_id" = "auth"."uid"())))))));



CREATE POLICY "Acesso aos logs de aprovação" ON "public"."ferias_aprovacoes_log" FOR SELECT USING (("auth"."uid"() IN ( SELECT "user_roles"."user_id"
   FROM "public"."user_roles"
  WHERE ("user_roles"."role" = ANY (ARRAY['admin'::"public"."app_role", 'rh'::"public"."app_role", 'gestor'::"public"."app_role"])))));



CREATE POLICY "Acesso aos riscos da empresa" ON "public"."sst_riscos_ambientais" FOR SELECT USING (("auth"."uid"() IN ( SELECT "user_roles"."user_id"
